returns text language plpgsql security invoker set search_path = '' as $official_bank$
declare
  v_bank jsonb := $official_bank_source${"code":"INS101","courseId":"cd0f182c-a770-5232-892c-22fdc00d8686","seedActor":"00000000-0000-4000-8000-000000000042","actor":"00000000-0000-4000-8000-000000000043","bankCount":458,"shell":{"contentKey":"introduction-insurance","titles":["Introduction to Insurance"],"level":"100-level","semesters":["first-semester"]},"audited":[],"keep":[],"retire":[],"add":[{"itemId":"ce091df0-12c1-526d-9aea-3d6bd35eae3c","questionId":"e5162475-b8aa-5fd0-9027-9313405a0400","sourceKey":"bank:INS101:INS-0010","payload":{"prompt":"A pure risk is defined as","options":["anything that increases either the severity or frequency of loss","a risk that produces a loss where the outcome is either a loss or no loss","the possibility that a loss will occur","the proximate cause of loss"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"A pure risk is one where the only possible outcomes are a loss or no loss; there is no chance of gain. Option A describes a hazard, which increases the chance or size of a loss. Option D is wrong because proximate cause is the dominant cause of a loss, not a type of risk."}},{"itemId":"0e6fa1de-706c-5009-883b-d76f6e7551b6","questionId":"6a1dbd08-6e6a-5c25-be94-a1e02b480570","sourceKey":"bank:INS101:INS-0025","payload":{"prompt":"The possibility that actual results may differ from predicted results is known as______________.","options":["Risk","Uncertainty","Peril","Hazards"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"Risk is the possibility that actual results will differ from what was expected or predicted. Option B, uncertainty, is close, but it describes the doubt a person feels about the future rather than the variation itself. Options C and D are wrong because a peril is the cause of a loss and a hazard is something that increases the chance of loss."}},{"itemId":"99eecef6-87a2-5438-b10a-0899eaf32647","questionId":"6eb027cc-c3c9-585c-ad65-ed293ad345dc","sourceKey":"bank:INS101:INS-0026","payload":{"prompt":"Which of the following definitions could easily pass for what risk basically is about?","options":["A variation in possible outcome","The degree of uncertainty associated to a particular loss","The combination of hazards","All of the above"],"correctOption":3,"section":"Concept of risk and insurance","explanation":"Risk has been described in several ways: as variation in possible outcomes, as the degree of uncertainty about a loss, and as a combination of hazards measured by probability. Since each statement captures part of what risk means, D is the best answer. Picking only A, B or C would leave out the other accepted descriptions."}},{"itemId":"58d0efa0-2650-5a79-be2e-ab8957b132e9","questionId":"537f993d-a1ef-5a64-b5fe-084e5e66dc5c","sourceKey":"bank:INS101:INS-0027","payload":{"prompt":"Which of the following is defined as the relative variation of actual loss from expected loss?","options":["Subjective risk","Pure loss","Objective risk","Expected risk"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"Objective risk is the relative variation of actual loss from expected loss, and it falls as the number of exposures grows. Option A, subjective risk, is a person's own feeling of uncertainty, which is not measured this way. Options B and D are not standard risk terms."}},{"itemId":"cdc20fdf-e0e7-5414-bb41-ef0717d03fb0","questionId":"5885d7cf-6941-541a-8df7-723ff91e387f","sourceKey":"bank:INS101:INS-0082","payload":{"prompt":"The law of large numbers states that:","options":["A large number of people must make claims before an insurance company begin to pay out","A large number of people are exposed to the same risk, a predictable number of losses will occur during a given period of time","Items that will be covered by an insurance policy must not be above a certain amount, i.e. the larger number which is set by actuaries","If losses from an occurrence are large enough, the insurance company will turn the policies over to a re-insurance company"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"The law of large numbers says that when many similar units are exposed to the same risk, the number of losses in a period becomes predictable. This lets insurers estimate claims and set premiums. Options A, C and D describe things that have nothing to do with this statistical principle."}},{"itemId":"292e8c81-be72-5fd6-ac99-63619c2b0e61","questionId":"23415ab7-e3f9-565e-9150-590ba1257441","sourceKey":"bank:INS101:INS-0090","payload":{"prompt":"Insurance or risk transfer is best used in risk management when the frequency of loss is ______ and the severity of loss is ______","options":["Low, high","high, low","low, low","high, High"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"Insurance works best for losses that happen rarely but would be very costly if they occurred, that is low frequency and high severity. Option D, high frequency and high severity, is better handled by avoiding the risk, and option C is usually retained. Option B is better managed through loss prevention and retention."}},{"itemId":"9b7bd913-c783-5abb-a62c-6176982bb4b2","questionId":"b4377026-6143-5ff5-8e07-808489ccd1be","sourceKey":"bank:INS101:INS-0115","payload":{"prompt":"Which of the following types of risk best meets the requirements for being insurable by private insurers?","options":["market risks","property risks","gambling risks","political risks"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Property risks, such as fire damage to a building, are pure risks whose losses can be measured and that affect many similar exposures, so private insurers can predict and price them. Market risks (A) and gambling risks (C) are speculative, because they can bring a gain as well as a loss. Political risks (D) are hard to predict and can hit many people at once, so private insurers rarely cover them."}},{"itemId":"e00be096-e80e-5c72-bb01-17c5c59f7906","questionId":"78611bfa-f82c-559e-8633-ae46499faac6","sourceKey":"bank:INS101:INS-0116","payload":{"prompt":"Why is a large number of exposure units generally required before a pure risk is insurable?","options":["it prevents the insurer from losing money","it eliminate intentional losses","it minimizes moral hazard","it enables the insurer to predict losses based on the law of large numbers."],"correctOption":3,"section":"Concept of risk and insurance","explanation":"A large number of similar exposure units lets the insurer predict future losses accurately using the law of large numbers. Option A is wrong because a large pool does not guarantee profits. Options B and C are wrong because intentional losses and moral hazard are controlled by underwriting and policy terms, not by numbers alone."}},{"itemId":"0cbba652-aa22-576b-ac50-407d2ab6e97a","questionId":"900388ba-0a5e-5869-b3db-9724b7ff775f","sourceKey":"bank:INS101:INS-0117","payload":{"prompt":"Traditionally, risk has been defined as","options":["any situation in which the probability of loss is one","any situation in which the probability of loss is zero","uncertainty concerning the occurrence of loss","the probability of a loss occurring."],"correctOption":2,"section":"Concept of risk and insurance","explanation":"Traditionally, risk has been defined as uncertainty about whether a loss will occur. Options A and B describe certain outcomes (loss certain or impossible), where there is no risk at all. Option D, the probability of loss, is a related idea, but it is the chance of loss, not the traditional definition of risk."}},{"itemId":"7d58c0a7-cc21-53ad-9ae6-19fb5886da24","questionId":"2ef750dc-34dd-5506-bb81-81b4a3ae5036","sourceKey":"bank:INS101:INS-0133","payload":{"prompt":"Only one describes the frequency of risk occurrence","options":["Rate of occurrence","Intensity of occurrence","Severity of occurrence","None of the above"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"Frequency is how often a loss happens, which is the rate of occurrence. Options B and C, intensity and severity, describe how large or serious a loss is when it happens, not how often it happens."}},{"itemId":"96a6c7e3-7676-51a3-b282-6ea27e80777c","questionId":"9583a2f8-92e5-5085-882b-efc97cd890af","sourceKey":"bank:INS101:INS-0134","payload":{"prompt":"Life is fraught with risk implies","options":["Risk abound","Everybody is exposed to risk","Life must be managed","A & B only"],"correctOption":3,"section":"Concept of risk and insurance","explanation":"Saying life is fraught with risk means that risks are everywhere and that everybody is exposed to them, so A and B together are the best answer. Option C, that life must be managed, may follow from this idea, but it is not what the phrase itself means."}},{"itemId":"4a202071-0556-59b6-84d0-d73bf5924ffb","questionId":"2e7536aa-0d7f-5d14-a92b-96b6682c183d","sourceKey":"bank:INS101:INS-0152","payload":{"prompt":"Only one is not a pure risk","options":["Premature death","Assassination","Stock loss","Ship wreck"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"A loss on stocks (shares) is a speculative risk, because the same investment could just as easily produce a gain. Premature death (A), assassination (B) and a shipwreck (D) can only bring a loss or no loss, which is what makes them pure risks."}},{"itemId":"761e09d0-7731-543b-9cbd-65fd0ed95980","questionId":"ca2e7312-9ed2-51c6-bfc5-f09237f61394","sourceKey":"bank:INS101:INS-0153","payload":{"prompt":"If the probability of risk occurrence is 0.8 this implies","options":["It is certain the risk would happen","The risk is not going to happen","The risk may or may not happen","The probability is deceptive."],"correctOption":2,"section":"Concept of risk and insurance","explanation":"Any probability between 0 and 1 means the event is uncertain, so 0.8 says the risk is quite likely but may or may not happen. Option A would need a probability of exactly 1, and option B would need a probability of 0."}},{"itemId":"faf99c28-3cb0-50ca-9167-16f00a6c98da","questionId":"82bb23d4-dc76-5b83-815c-2a79544e99f6","sourceKey":"bank:INS101:INS-0170","payload":{"prompt":"Which of the following statements about speculative risks is true","options":["they are almost always insurable by private insurers","they are more easily predictable than pure risks","they may benefit society even though a loss occurs","they involve only a chance of loss"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"Speculative risks involve the chance of gain as well as loss, and even when one business loses, society can benefit, for example when a stronger competitor offers better products. They are generally not insurable privately (A), they are harder to predict than pure risks (B), and they involve gain as well as loss, so D describes pure risk instead."}},{"itemId":"c0984699-b08a-5e1b-ba5b-3f65d40d1e90","questionId":"e615e600-56d8-50c0-bff3-99a03b31e4a4","sourceKey":"bank:INS101:INS-0279","payload":{"prompt":"To determine the premiums required; actuaries apply the principle derived from:","options":["The law of averages and the theory of probability","Underwriting","Rating","The size of the sample"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"Actuaries set premiums by applying the law of averages and the theory of probability to past loss experience. Underwriting (B) and rating (C) are activities that use those results, and sample size (D) is only one part of the law of large numbers."}},{"itemId":"c72b8390-9d9d-5881-bb9d-9582918fcbf0","questionId":"e9ee6739-e1f3-5dd5-b77d-eb9189a3e6d4","sourceKey":"bank:INS101:INS-0281","payload":{"prompt":"The law of large numbers states that:","options":["A large number of people must make claims before an insurance company will begin to pay out","If a large number of people are exposed to the same risk, a predictable number of losses will occur during a given period of time","Items that will be covered by an insurance policy must not be above a certain amount, i.e. the large number which is set by actuaries.","If losses from an occurrence are large enough, an insurance company will turn the policies over to a reinsurance company"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"The law of large numbers says that when many people face the same risk, the number of losses in a period becomes predictable. Option A wrongly links it to how many claims must be made, while C and D confuse it with policy limits and reinsurance."}},{"itemId":"5ce74266-e440-51b7-88d0-eed5af85ef9e","questionId":"6b753dd1-c947-587d-a910-03664fc31186","sourceKey":"bank:INS101:INS-0282","payload":{"prompt":"________ entails a situation in which either profit or loss is possible (business, investment, betting). This risk is uninsurable though with few exceptions.","options":["Particular risk","Pure risk","Speculative","Dynamic"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"Speculative risk offers the chance of either a profit or a loss, as in business, investment or betting, which is why it is usually uninsurable. Pure risk (B) offers only loss or no loss, while particular (A) and dynamic (D) risks describe the scope and cause of a risk."}},{"itemId":"8ebebee2-90c4-5bb8-9a7a-bd5eb6f94eab","questionId":"8b231035-9db1-582a-9161-9a464fe8a0ef","sourceKey":"bank:INS101:INS-0285","payload":{"prompt":"_________ risk are those resulting from changes in the economy, while _________ risk affects the entire economy.","options":["Pure, fundamental","Acceptable, pure","Dynamic, financial","Dynamic, fundamental"],"correctOption":3,"section":"Concept of risk and insurance","explanation":"Dynamic risks come from changes in the economy, such as new technology or shifts in consumer demand, while fundamental risks affect the whole economy or large groups at once. Pure risk (A) is about loss or no loss, and financial risk (C) is about measurable money loss, so they describe other ways of classifying risk."}},{"itemId":"8e34f2d2-3a88-5245-97c3-6f781668e9cc","questionId":"a4ccdc63-8354-5e49-a437-737a1aa0b1c5","sourceKey":"bank:INS101:INS-0287","payload":{"prompt":"When an insured intentionally sets his/her house on fire in order to make a claim, it is referred to as:","options":["Physical hazard","Arson hazard","Morale hazard","Moral hazard"],"correctOption":3,"section":"Concept of risk and insurance","explanation":"Moral hazard is dishonesty or bad intent in the insured, and deliberately burning your own house to claim is the classic example. Option C, morale hazard, is carelessness or indifference to loss, not a deliberate act. Option A, physical hazard, is a physical feature of the property such as poor wiring, and 'arson hazard' in B is not a recognised class of hazard."}},{"itemId":"3f6fd3c5-de94-566d-8002-b9ecb51a1cc2","questionId":"98ee4681-5b5c-550a-96ed-91ea5c067f3d","sourceKey":"bank:INS101:INS-0341","payload":{"prompt":"Which of the following is an example of a speculative risk?","options":["A trader with a large stock facing a rise or fall in its market price","A family house being damaged by fire","A car being stolen from its owner","A breadwinner dying unexpectedly"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"Speculative risk can bring either a gain or a loss, like a trader holding a large stock whose price may rise or fall. Options B, C and D are pure risks, where the only outcomes are loss or no loss, so they are the kind of risk insurers normally cover."}},{"itemId":"45a37292-599f-59c9-8256-3e2c10243361","questionId":"e8d2ee9d-bb31-51f5-89ba-ca61efaa329d","sourceKey":"bank:INS101:INS-0347","payload":{"prompt":"There are many types of losses. Insurers are only interested in ______ loss","options":["Economic loss","Sentimental loss","Total loss","Socio economic loss"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"Insurers only cover losses that can be measured in money, which is economic or financial loss. Option B, sentimental loss, cannot be valued in money, so it is not insured. Option C is wrong because insurers also pay partial losses, and option D is not a standard insurance term."}},{"itemId":"8b20d1e3-bf21-5da6-850b-ec5315a6d33d","questionId":"2e963385-bdb1-5f9e-9a9b-c0f1383af860","sourceKey":"bank:INS101:INS-0355","payload":{"prompt":"Probability of 0.0; 0.1; 0.5; 0.8 & 1.0 corresponds to","options":["Extremely unlikely, impossible even change, very likely, certainty respectively","Impossible, extremely unlikely, even chance, very likely, and certainty respectively","Uncertainty, impossible, possible, certainty and uncertainty respectively","Certainty, even chance, extremely unlikely, impossible and very likely respectively"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"On a probability scale, 0 means impossible, 0.1 extremely unlikely, 0.5 an even chance, 0.8 very likely and 1 certainty. Option A gets the order wrong by calling 0 'extremely unlikely'. Options C and D scramble the scale, for example by calling 0 certainty."}},{"itemId":"e165dee4-759f-5405-bdfd-132e26d2ee3c","questionId":"cc8c0657-5985-50e2-b0a9-abd685c07a39","sourceKey":"bank:INS101:INS-0356","payload":{"prompt":"All of the following are transferable risks EXCEPT","options":["damage from hurricane","theft of your car","fire at your home","investment risk"],"correctOption":3,"section":"Concept of risk and insurance","explanation":"Investment risk is speculative, since you may gain or lose, so it cannot normally be passed to an insurer. Options A, B and C are pure risks, which offer only loss or no loss, and can be transferred through insurance."}},{"itemId":"85810bcf-c070-50fc-8778-5ec84235d4be","questionId":"47d18f00-8aaf-5fef-a42e-ac6721ae7430","sourceKey":"bank:INS101:INS-0357","payload":{"prompt":"If there are 1,000,000 persons aged 25 and, based on past experience, it is predicted that 3,000 of them will die in a given period of time, the probability of loss is","options":["0.003","0.0003","0.00003","0.03"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"Probability of loss is the number of expected losses divided by the number exposed: 3,000 / 1,000,000 = 0.003. Option B, 0.0003, comes from misplacing a decimal place. Option D, 0.03, is ten times too high."}},{"itemId":"31b782dc-7e4d-54b8-a455-ccd3817adcc4","questionId":"ed3acd8a-17bd-5ad4-977f-548ab4a40cb4","sourceKey":"bank:INS101:INS-0358","payload":{"prompt":"If there are 1,000,000 persons aged 25 and, based on past experience, it is predicted that 3,000 of them will die in a given period of time, and an insurer has 10,000 persons covered under life insurance contracts, the probable number of losses to the insurer is","options":["300","30","3","33"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Using the probability from the population, 3,000 / 1,000,000 = 0.003, the insurer expects 10,000 x 0.003 = 30 deaths. Option A, 300, uses a probability ten times too high. Option C, 3, uses one ten times too low."}},{"itemId":"05a85e5e-74f0-5811-8fe6-ff9f4d6ce24c","questionId":"83ca783e-923b-50ae-bf39-8ab2fde6cb36","sourceKey":"bank:INS101:INS-0359","payload":{"prompt":"An insurer has 100 automobiles in an insured group and the probability of collision loss is estimated at 0.20 per year, i.e. 20 collisions per year. If it is estimated that in 5% of cases the number of collisions will exceed the average by 8, the objective risk is","options":["20%","40%","30%","10%"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Objective risk is the expected deviation divided by the expected number of losses: 8 / 20 = 0.4, or 40%. Option A, 20%, is just the probability of collision, not the objective risk. Option D, 10%, does not come from the figures given."}},{"itemId":"46fa502d-503a-5c94-a382-3d932e1de49e","questionId":"52500211-9047-5acb-a80c-33ce67520a09","sourceKey":"bank:INS101:INS-0360","payload":{"prompt":"An insurer has automobiles in an insured group with a probability of collision loss estimated at 0.20 per year. If the number of autos is increased to 900, and it is estimated that in 5% of cases the number of collisions will exceed the average by 24, the objective risk is","options":["24/180","24/900","8/20","24/100"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"With 900 cars and a 0.20 chance of collision, expected collisions are 900 x 0.20 = 180, so objective risk is 24 / 180, about 13.3%. Option B divides by the number of cars instead of the expected losses. Option C is the figure for the original 100 cars, and option D uses the wrong base."}},{"itemId":"fc680506-46e0-5176-82ff-71649cae8c5b","questionId":"0709c95f-18b0-585d-96ec-b693f7cf36a3","sourceKey":"bank:INS101:INS-0362","payload":{"prompt":"For the insurance company, a meaningful measure of risk is","options":["the probability that a loss will or will not occur","the possible deviation of actual from predicted results","the size of the population insured","the relationship of premium to average loss"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"For an insurer, the useful measure of risk is objective risk, the likely deviation of actual losses from the losses it predicted. Option A, the chance of loss, matters but does not show how far results may swing. Options C and D are inputs to pricing, not measures of risk."}},{"itemId":"ef8e352c-daae-5ed8-aaac-f1e05b19e036","questionId":"c68f3b8a-73c8-56ca-8c81-99a5b335924f","sourceKey":"bank:INS101:INS-0364","payload":{"prompt":"Risk in insurance refers to:","options":["The assurance of a predictable event","The potential for an uncertain loss","The promise of financial gain","The exclusion of fiscal planning"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Risk in insurance is the chance that an uncertain loss may happen. Option A is wrong because a predictable, assured event is not uncertain at all. Option C describes speculative gain, which insurance does not cover."}},{"itemId":"aa985fd9-cdad-5c05-a733-9e8cc803c7a5","questionId":"588c8c56-41f6-55a3-b2e8-5ec468781acb","sourceKey":"bank:INS101:INS-0367","payload":{"prompt":"Insurance is best described as:","options":["A form of speculative betting","A system for managing risk exposure","A complete shield against losses","A device to heighten risk levels"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Insurance is a way of managing exposure to risk by transferring its financial effects to an insurer. Option A is wrong because insurance reduces uncertainty rather than creating a bet. Option C is wrong because no policy protects against every loss."}},{"itemId":"c8e707c8-caba-5a4b-96e5-90e62b1b7d15","questionId":"e305da45-7545-5f5d-9c9f-dad304064961","sourceKey":"bank:INS101:INS-0368","payload":{"prompt":"Pure risk is:","options":["A gamble with potential rewards","A situation with only loss potential","A calculated speculative venture","A consistently predictable event"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Pure risk offers only two outcomes, loss or no loss, with no chance of gain. Options A and C describe speculative risk, where a gain is also possible. Option D is wrong because risk by nature involves uncertainty."}},{"itemId":"5cce7bdb-4e3f-5649-a20e-648374c78736","questionId":"c704116b-cd91-5db2-a7ec-ef7554b569f6","sourceKey":"bank:INS101:INS-0369","payload":{"prompt":"Speculative risk differs from pure risk because it:","options":["Offers only downside potential","Includes both profit and loss possibilities","Is inherently insurable","Cannot be insured under any condition"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Speculative risk can end in profit, loss or no change, as in business ventures or gambling. Option A describes pure risk instead. Option C is wrong because speculative risks are generally not insurable, and option D is too absolute."}},{"itemId":"c2c6d3f6-35cd-5b43-b0a4-9918845b3bae","questionId":"bcb65d4d-2d67-50a5-9953-93bc1c5adf3a","sourceKey":"bank:INS101:INS-0371","payload":{"prompt":"Which of the following is an example of pure risk?","options":["Trading stocks for profit","A residential fire hazard","Launching a startup venture","Betting at a gaming table"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"A house fire can only cause a loss or no loss, which makes it a pure risk. Options A, C and D can all lead to gain as well as loss, so they are speculative risks."}},{"itemId":"ac308e65-5882-5178-8c94-3f201e826a40","questionId":"449b0699-51a7-5e8c-a63f-1f552182a3d5","sourceKey":"bank:INS101:INS-0372","payload":{"prompt":"The law of large numbers in insurance is used to:","options":["Forecast specific individual outcomes","Estimate average results over many risks","Raise premium costs universally","Limit the insured population size"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"The law of large numbers says that the larger the group of similar exposures, the closer actual losses come to the expected average, which lets insurers predict total losses. Option A is wrong because it cannot forecast what will happen to any one person. Option D is the opposite, since insurers want a large insured population."}},{"itemId":"e0bc2de9-e4fd-535a-8062-a95a75fe74be","questionId":"19c56666-48f9-50ea-909b-1b797d2aef6d","sourceKey":"bank:INS101:INS-0374","payload":{"prompt":"A peril in insurance refers to:","options":["The trigger of a loss event","The monetary extent of a loss","The likelihood of occurrence","The avoidance of damage"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"A peril is the event that actually causes a loss, such as fire, flood or theft. Option C describes probability, and option B is the size of the loss, not its cause. A factor that makes loss more likely is a hazard, not a peril."}},{"itemId":"364cbe77-897a-52c4-967b-562f9ad37afa","questionId":"5503e4da-55eb-59cf-9146-06f19ad96374","sourceKey":"bank:INS101:INS-0375","payload":{"prompt":"A hazard in insurance is:","options":["The event causing a loss","A factor raising loss probability","The cost of coverage","The insurance agreement itself"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"A hazard is a condition that increases the chance or size of a loss, such as faulty wiring. Option A describes a peril, the event that causes the loss itself. Options C and D are the premium and the policy, which are not hazards."}},{"itemId":"11f1338b-e6a7-5fed-9a0d-46f040fd05a4","questionId":"bff12976-9052-51a1-931a-e852bb5394ff","sourceKey":"bank:INS101:INS-0376","payload":{"prompt":"Which of the following is a type of hazard?","options":["A wildfire outbreak","Neglected building upkeep","A burglary incident","A coastal flood"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Poor building maintenance is a condition that makes loss more likely, so it is a hazard. Options A, C and D are events that cause loss directly, which makes them perils."}},{"itemId":"00ce9a8e-469c-5853-a5b0-5f5f040dcc59","questionId":"6c3c7043-e752-5e77-a68b-efb6f5530f26","sourceKey":"bank:INS101:INS-0377","payload":{"prompt":"The concept of risk management in insurance includes:","options":["Detecting, evaluating, and reducing risks","Amplifying risks for gain","Evading all risk scenarios","Dismissing potential damages"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"Risk management is the process of identifying, measuring and controlling risks, for example by reducing, transferring or retaining them. Option C is wrong because it is not possible or sensible to avoid every risk. Options B and D are the opposite of managing risk."}},{"itemId":"9f67e8bf-5721-57a2-9bce-9a173314fa7f","questionId":"ac2ad12a-e1af-536a-b8e2-77b1dde164da","sourceKey":"bank:INS101:INS-0385","payload":{"prompt":"The function of indemnification in insurance means:","options":["Overcompensating for losses","Returning the insured to pre-loss status","Denying claim payouts","Magnifying loss values"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Indemnity aims to put the insured back in the same financial position as before the loss, no better and no worse. Option A is wrong because overcompensation would let the insured profit from a loss. Options C and D do not describe indemnity."}},{"itemId":"f791b90b-fec2-55a7-8495-817eac2ea669","questionId":"ca50185d-7f26-5d8b-bcc0-e42b848af61a","sourceKey":"bank:INS101:INS-0427","payload":{"prompt":"The analysis of insurance includes evaluating:","options":["Insured's lifestyle choices","Risk probability and severity","Insurer's ad campaigns","Insured's tax history"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Insurers analyse a risk by looking at how likely a loss is and how severe it could be. Options C and D are unrelated to the risk being insured. Option A may play a part, but it is not the core of risk analysis."}},{"itemId":"81d9790b-bd11-5d8b-badd-698bbd381ef3","questionId":"1f2e08f5-ea5e-54ae-8532-27369f7b459e","sourceKey":"bank:INS101:INS-0847","payload":{"prompt":"The asset may lose its value on the occurrence of a certain event. This chance of loss is referred to as ___. The cause of the risk event is known as ____.","options":["Profit / loss","Debit / credit","Risk / peril","Primary / secondary"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"Risk is the chance or possibility of loss, while a peril is the actual cause of loss, such as fire, flood or theft. Option A confuses risk with business results, and options B and D are accounting and general terms with no link to this idea."}},{"itemId":"60b78e71-54ac-5da3-a1a0-0cab2d7c22be","questionId":"589a1b69-8cf6-5074-943f-03db1c1bbebc","sourceKey":"bank:INS101:INS-0869","payload":{"prompt":"Insurance is a risk management technique that involves?","options":["Risk retention","Risk avoidance","Loss control","Risk transfer"],"correctOption":3,"section":"Concept of risk and insurance","explanation":"Insurance works by passing the financial burden of a possible loss from the insured to the insurer in return for a premium, which is risk transfer. Risk retention (A) means bearing the loss yourself, avoidance (B) means not doing the risky activity at all, and loss control (C) means reducing how often or how badly losses happen."}},{"itemId":"57ea045d-6bb8-57f4-84cb-6c9d2484e7ff","questionId":"433ac406-9d09-52c1-b1cf-1ca12bbb64c0","sourceKey":"bank:INS101:INS-0870","payload":{"prompt":"Risk of premature death is a?","options":["Speculative risk","Dynamic risk","Personal risk","Subjective risk"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"Premature death is a personal risk because it directly affects an individual and the income their family depends on. Option A is wrong because a speculative risk offers a chance of gain, and death offers none. Option B is wrong because dynamic risks come from changes in the economy, not from the death of one person."}},{"itemId":"1ce0e1fd-e056-524c-bc6d-36de07050d86","questionId":"c16f1bd5-a163-58af-8aca-e7fcb8d1b59f","sourceKey":"bank:INS101:INS-0875","payload":{"prompt":"Which of the following is not a peril","options":["Wet road","Fire","Theft","Burglary"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"A peril is the actual cause of a loss, such as fire, theft or burglary (options B, C and D). A wet road is a hazard, a condition that makes an accident more likely, but it is not itself the event that causes the loss."}},{"itemId":"afc40d72-7312-5ad5-a018-2e1178bffd4d","questionId":"1f0728e9-8463-5de9-a9ca-453dfd1d0607","sourceKey":"bank:INS101:INS-1019","payload":{"prompt":"Which of these offers the possibility of loss or gain?","options":["Pure risk","Speculative risk","Fundamental risk","Financial risk"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"A speculative risk has three possible outcomes: loss, no loss or gain, as with buying shares or starting a business. Pure risk (A) offers only loss or no loss, and fundamental risk (C) describes how widely a risk spreads, not whether gain is possible."}},{"itemId":"e4311352-2a9d-5e2a-a468-f07ac651ae0c","questionId":"22eeecb7-d923-5d87-bd73-37e86f24d053","sourceKey":"bank:INS101:INS-1020","payload":{"prompt":"Which of these risks is uninsurable?","options":["Investment in stocks and shares","Injury at work","Fire at a factory","Theft from a warehouse"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"Buying shares is a speculative risk, because the investor may gain as well as lose, and speculative risks are generally uninsurable. Fire at a factory, injury at work and theft from a warehouse (options B, C and D) are pure risks with only a chance of loss, so insurers routinely cover them."}},{"itemId":"e7cd3e90-eb9e-5077-b35d-9419acc93340","questionId":"67ed04dd-06ab-524c-8f51-3b3090b01498","sourceKey":"bank:INS101:INS-1022","payload":{"prompt":"An individual's personal estimate of the chance of loss is","options":["Peril","Subjective risk","Objective probability","Subjective probability"],"correctOption":3,"section":"Concept of risk and insurance","explanation":"Subjective probability is a person's own estimate of how likely a loss is, which can differ from the true figure. Subjective risk (B) is the uncertainty or worry a person feels, not an estimate of chance, and objective probability (C) is the long-run chance worked out from past data."}},{"itemId":"b8252277-6dc7-5329-a5b0-b55b82b7afd8","questionId":"d922147d-f6ff-598b-876c-a034fa22faca","sourceKey":"bank:INS101:INS-1025","payload":{"prompt":"This type of risk affects the entire economy or a large number of persons or groups within the economy","options":["Enterprise risk","Fundamental risk","Pure Risk","Speculative risk"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"A fundamental risk is impersonal and affects society widely, such as inflation, war or a major flood. Pure risk (C) and speculative risk (D) describe whether gain is possible, not how many people are affected."}},{"itemId":"d9330930-7e86-5d63-b0a5-5e1c5b1e670b","questionId":"7ca9379b-fb5e-58a0-8c7c-1e4e28911015","sourceKey":"bank:INS101:INS-1026","payload":{"prompt":"This is described as the cause of loss; the prime cause which gives rise to a loss beyond the control of anyone","options":["Hazard","Misfortune","Peril","Seal"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"A peril is the event that actually causes a loss, such as fire, flood or theft. A hazard (A) only increases the chance or size of a loss, for example storing petrol beside a generator, but it is not the cause itself."}},{"itemId":"afd694d3-23cf-5a20-bdc1-d661911e9bf2","questionId":"58063c15-1f71-5a8e-864b-0a8acad81b1d","sourceKey":"bank:INS101:INS-1028","payload":{"prompt":"Chance of loss is said to be","options":["An event that has occurred","Probability that an event will occur","Probability that an event will never occur","Change in the goods insured"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Chance of loss is the probability that a loss-causing event will happen, often shown as a fraction such as 1 in 100. Option A describes a loss that has already happened, so there is no chance left to measure, and option C reverses the meaning."}},{"itemId":"135553fa-d5b8-5022-accf-79328042774d","questionId":"367f22e7-a517-52c2-afeb-4d49c074164a","sourceKey":"bank:INS101:INS-1030","payload":{"prompt":"All insurable risks are","options":["Non financial risk","Speculative risks","Pure risk","All of the above"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"Insurable risks are pure risks, where the outcome is either loss or no loss, because covering a chance of gain would reward speculation. Option B is wrong for exactly that reason, and option A is wrong because an insurable loss must be measurable in money. Option D therefore cannot be right either."}},{"itemId":"987bac01-1cfc-52c6-93f8-b66f29efcdc8","questionId":"287d26a0-3940-5211-8823-5e6058d112dd","sourceKey":"bank:INS101:INS-1031","payload":{"prompt":"The risks which transcend all human control are","options":["Pure","Speculative","Particular","Fundamental"],"correctOption":3,"section":"Concept of risk and insurance","explanation":"Fundamental risks arise from causes beyond the control of any individual, such as earthquakes, war or economic depression, and they affect large groups. Particular risks (C) arise from individual actions and affect individuals, like a house fire or a car theft."}},{"itemId":"90f1a01b-cca8-5014-aa0f-bc7f50fb2b45","questionId":"fb786c75-4325-5223-afe6-145d901006a7","sourceKey":"bank:INS101:INS-1033","payload":{"prompt":"How many combinations of severity and frequency of loss are there?","options":["5","4","6","2"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Frequency can be high or low, and severity can be high or low, giving 2 x 2 = 4 combinations: low-low, low-high, high-low and high-high. Option D, 2, counts only the levels of one factor and forgets to combine them."}},{"itemId":"eaaacb1d-276d-5c09-8b8d-28422befbca0","questionId":"4ea773a4-744b-574a-8806-0f852dd588ac","sourceKey":"bank:INS101:INS-1035","payload":{"prompt":"One of the following is a major difference between peril and hazard","options":["Peril influences loss, hazard is the cause of loss","There is no difference between peril and hazard","Peril is the cause of loss while hazard is the factor influencing the outcome of loss","Peril and hazard are synonymous risks"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"A peril, such as fire, is what causes the loss, while a hazard, such as a thatched roof, makes the loss more likely or more serious. Option A is tempting because it uses the same words, but it swaps the two meanings around."}},{"itemId":"4e5c9776-c820-5925-91ca-5fa1c435dd1f","questionId":"583119cd-7221-55ed-82b8-b77010d67942","sourceKey":"bank:INS101:INS-1037","payload":{"prompt":"Risks that directly affect an individual are known as","options":["Personal risk","Fundamental risk","Liability risk","Pure risk"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"Personal risks directly affect a person's life or health, such as premature death, ill health, old age or unemployment. Liability risk (C) is the risk of being legally responsible for harm to others, and fundamental risk (B) affects society widely rather than one person."}},{"itemId":"00c30009-080e-5761-abec-9888c6f29f3c","questionId":"38a537b7-8124-5cb0-8990-c3f2b7c29e25","sourceKey":"bank:INS101:INS-1043","payload":{"prompt":"The law of large numbers states that","options":["the larger the sum insured, the lower the premium rate must be","if a large number of people are insured, none of them will suffer a loss","if a large number of people are exposed to the same risk, a predictable number of losses will occur during a given period of time","every person exposed to a risk will suffer a loss within a given period"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"When many similar units face the same risk, the actual losses come closer to the expected losses, so insurers can predict the number of claims and set premiums. The law does not say every person will suffer a loss or that losses disappear; it is about predictability across a group."}},{"itemId":"153405de-0c13-5497-884b-ac02019fc934","questionId":"5f62385b-15fd-52a3-8842-aebd5ab4b979","sourceKey":"bank:INS101:INS-1061","payload":{"prompt":"A pure risk is defined as","options":["a risk where the outcome may be loss, no loss or gain","a risk that can never be insured","a risk where the only possible outcomes are loss or no loss","a risk that affects the whole of society"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"With pure risk there is no chance of gain: your house either burns or it does not. The option about loss, no loss or gain describes speculative risk, such as buying shares, which insurers do not cover."}},{"itemId":"a63a178e-8a2f-51ae-9798-689c96b34a80","questionId":"9293b76d-f2fc-5c67-bbd5-c15342208784","sourceKey":"bank:INS101:INS-1108","payload":{"prompt":"For an oil and gas firm operating in the Niger Delta, which of the following would count as part of the \"risk\" it faces?","options":["Leakage of toxic products into the environment","Harm to the health or lives of its workers","Damage to its machinery and property","All of the above"],"correctOption":3,"section":"Concept of risk and insurance","explanation":"Risk covers every possible loss the firm could face, including damage to its equipment, harm to workers' health and pollution affecting the surrounding community. Since each of the other options is a real source of loss, picking only one of them leaves out the others."}},{"itemId":"1ccc4fea-721d-5bd9-bc14-b127a9fa4bc4","questionId":"2d58b3b9-1960-50b4-9aa8-4e2967af0bb2","sourceKey":"bank:INS101:INS-1148","payload":{"prompt":"Which principle, developed by Jakob Bernoulli around 1700, explains why insurers can predict losses more accurately when they cover a large number of similar risks?","options":["The principle of subrogation","The doctrine of proximate cause","The law of large numbers","The principle of utmost good faith"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"The law of large numbers says that the more similar exposures you group together, the closer actual losses come to expected losses, which lets insurers set fair premiums. Options A, B and D are legal principles of the insurance contract, not statistical ideas about predicting losses."}},{"itemId":"30199970-ef12-5a8e-bd71-97f46035e606","questionId":"4aeb9224-aed6-5281-be80-27c515f7c3a9","sourceKey":"bank:INS101:INS-1175","payload":{"prompt":"In an insurance contract, the party who promises to compensate the other party for possible losses is the","options":["Insured","Beneficiary","Insurer","Proposer"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"The insurer is the insurance company that accepts the risk and agrees to pay for covered losses in return for a premium. Option A is the person who buys the cover and is protected by it. Option D is the person applying for cover, who becomes the insured, not the one who pays claims."}},{"itemId":"4d7b29a1-636f-5390-aa97-3d640da8a318","questionId":"8b27c6f7-910c-5576-a904-e8c93f46b9ef","sourceKey":"bank:INS101:INS-1176","payload":{"prompt":"The person whose life or property is covered against risk under an insurance contract is called the","options":["Insurer","Reinsurer","Underwriter","Insured"],"correctOption":3,"section":"Concept of risk and insurance","explanation":"The insured (also called the assured or policyholder) is the person protected by the policy, whose life or property is the focus of the cover. Option A is the company that promises to pay. Options B and C sit on the insurance company side of the deal."}},{"itemId":"65011e1c-6469-5df1-9d2e-8a0212675596","questionId":"af4e534f-45be-5255-9ddb-21afcf0e76b1","sourceKey":"bank:INS101:INS-1177","payload":{"prompt":"The sum of money the insured pays to the insurer in return for the insurer's promise to compensate for losses is called the","options":["Policy","Subject matter","Sum insured","Premium"],"correctOption":3,"section":"Concept of risk and insurance","explanation":"The premium is the price of insurance, the consideration the insured gives in exchange for the insurer's promise. Option A is the document containing the contract, and B is the life or property being insured. Option C is the maximum the insurer may pay, not what the insured pays."}},{"itemId":"9ac158ed-d03f-5eba-8afd-35dbd77996ee","questionId":"b0c6a257-367d-5013-b97b-f469ab42f470","sourceKey":"bank:INS101:INS-1178","payload":{"prompt":"The life, property or liability that is actually being insured under a policy is known as the","options":["Insurable interest","Premium","Subject matter of insurance","Policy schedule"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"The subject matter is the thing insured, such as a car, a shop's stock or a person's life. Option A is the financial relationship the insured has with that thing, not the thing itself. Option D is the page of the policy that lists details, and B is the price paid."}},{"itemId":"b7342088-72c1-56fd-b36c-9b92eafd673e","questionId":"62108d72-4f74-5520-948f-c51a88227ef5","sourceKey":"bank:INS101:INS-1182","payload":{"prompt":"Insurers measure and evaluate risk mainly on the basis of the theory of","options":["Demand and supply","Probability","Comparative advantage","Diminishing returns"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Probability theory lets insurers estimate how often and how badly losses are likely to happen, and that estimate drives the premium. Options A, C and D are economic ideas about markets, trade and production, not tools for measuring the chance of a loss."}},{"itemId":"8ae36db3-a812-50ba-b24b-a19f80db60f2","questionId":"97693114-015f-5cef-9981-47aedbdc22d3","sourceKey":"bank:INS101:INS-1183","payload":{"prompt":"Which of the following is NOT a recognised classification of risk?","options":["Quantitative risk","Speculative risk","Dynamic risk","Fundamental risk"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"Risks are usually classified as pure or speculative, static or dynamic, and fundamental or particular, and quantitative is not one of these classes. Option B involves a chance of gain or loss, C comes from changes in the economy or society, and D affects large groups at once, so all three are genuine risk types."}},{"itemId":"a2bfe454-b5d0-5b10-9a1c-82fd5fa7b6c7","questionId":"147ee5f7-ef05-5681-873f-84c7787b286f","sourceKey":"bank:INS101:INS-1225","payload":{"prompt":"A business that sets aside its own fund to meet losses, instead of buying cover from an insurance company, is practising","options":["Reinsurance","Double insurance","Self-insurance","Co-insurance"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"Self-insurance means retaining the risk and paying losses from your own reserve fund, as an alternative to buying cover in the commercial market. Option A is an insurer buying cover from another insurer. Options B and D both involve buying cover from insurance companies."}},{"itemId":"c944be09-bc73-56de-a54f-a4d4877d9cc9","questionId":"dd374e56-2034-5e00-bd6e-eaeb834743c3","sourceKey":"bank:INS101:INS-1236","payload":{"prompt":"The possibility of loss arising from unforeseen future events is known as","options":["Peril","Hazard","Risk","Damage"],"correctOption":2,"section":"Concept of risk and insurance","explanation":"Risk is the uncertainty or chance that a loss will happen in the future. Option A is the actual cause of loss, like fire or theft. Option B is a condition that increases the chance of loss, and D is the harm itself after it has happened."}},{"itemId":"635c44cd-8de2-5447-951f-60b5b56ad1cc","questionId":"e3f008cc-2538-5d41-b1bf-94d9e27690db","sourceKey":"bank:INS101:INS-1241","payload":{"prompt":"The actual cause of a possible loss, such as fire, windstorm or theft, is called a","options":["Peril","Hazard","Premium","Indemnity"],"correctOption":0,"section":"Concept of risk and insurance","explanation":"A peril is the event that causes the loss, such as fire, flood or theft. Option B is a condition that makes a peril more likely or more severe, like storing petrol in a house. Options C and D are about payments under the contract, not causes of loss."}},{"itemId":"cf83badf-3116-556d-8404-16855cb4ea75","questionId":"5909c1a4-317a-561d-8766-5f56e9d02824","sourceKey":"bank:INS101:INS-1249","payload":{"prompt":"Which of the following is NOT an example of fundamental risk?","options":["War","The burning of one person's house","Mass unemployment","Inflation"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Fundamental risks affect large groups or the whole economy at once, while the burning of one house affects only one person, so it is a particular risk. Options A, C and D hit many people at the same time and are classic fundamental risks."}},{"itemId":"6583582f-44e9-58c4-9db6-f44de44e7adc","questionId":"4b264134-612a-5475-9c27-90cfc0dfc54d","sourceKey":"bank:INS101:INS-1250","payload":{"prompt":"Which type of risk is also called group risk because it affects large numbers of people at the same time?","options":["Particular risk","Fundamental risk","Static risk","Speculative risk"],"correctOption":1,"section":"Concept of risk and insurance","explanation":"Fundamental risk arises from causes outside any one person's control, such as war or a recession, and affects whole groups at once. Option A affects only individuals. Option C exists even in a stable economy, and D involves a chance of gain, so neither is defined by affecting groups."}},{"itemId":"e9eac9a8-4c80-544b-b9ae-223b4837d3b4","questionId":"a7e05634-6fcc-5612-bbb0-d84cb5a89bbf","sourceKey":"bank:INS101:INS-1277","payload":{"prompt":"Which of the following is NOT a market price risk faced by a business?","options":["Interest rate risk","Commodity price risk","Exchange rate risk","Product liability risk"],"correctOption":3,"section":"Concept of risk and insurance","explanation":"Product liability risk comes from being sued when a product injures someone, so it arises from the firm's legal responsibility, not from movements in market prices. Options A, B and C all come from changes in prices in the market: interest rates, raw material prices and the naira exchange rate."}},{"itemId":"188b62b2-f114-5e32-a72d-fb4774fe6999","questionId":"afa8f378-1cde-5df3-8079-e2b887367e58","sourceKey":"bank:INS101:INS-0066","payload":{"prompt":"The principles of insurance is based on which of the following?","options":["Principle of co-operation","Principle of probability theory","All of the above","None of the above"],"correctOption":2,"section":"Scope and functions of insurance","explanation":"Insurance rests on co-operation, where many people contribute to a common fund to pay the losses of the few, and on probability theory, which lets insurers predict losses and set premiums. Both are needed, so C is correct. Choosing only A or B leaves out one of the two foundations."}},{"itemId":"13ea0309-1dc9-5a4a-bbdb-2322786fb7c2","questionId":"eea12338-1f87-5a49-a161-6d46d6de80cc","sourceKey":"bank:INS101:INS-0099","payload":{"prompt":"Functions of insurance are categorized into which of the following?","options":["Primary functions","secondary functions","tertiary functions","a and b"],"correctOption":3,"section":"Scope and functions of insurance","explanation":"The functions of insurance are usually grouped into primary functions, such as providing protection and sharing risk, and secondary functions, such as loss prevention and providing capital. So D, covering both, is correct. Option C, tertiary functions, is not a standard category."}},{"itemId":"b988b14d-91e1-52c3-b091-72c4ab0970fe","questionId":"415a4b49-1559-5c01-808e-a75d11fddd00","sourceKey":"bank:INS101:INS-0156","payload":{"prompt":"Loss prevention includes all pre-loss management activities except one","options":["Disposal of waste material","Using fire surveyors to identify risks","Fire proof doors","Making insurance to pay for your losses"],"correctOption":3,"section":"Scope and functions of insurance","explanation":"Loss prevention means steps taken before a loss to stop it happening, such as disposing of waste, using surveyors to spot fire risks and fitting fire-proof doors. Getting an insurer to pay for your losses (D) is risk transfer and only helps after the loss, so it is not a pre-loss prevention activity."}},{"itemId":"8a2de82f-c076-555c-9d56-8ee2623d2c56","questionId":"9133dd34-51e0-5fe2-9de5-07c85e7f955c","sourceKey":"bank:INS101:INS-0166","payload":{"prompt":"A primary purpose of insurance as a risk transfer mechanism is to","options":["compensate for financial losses however sustained","provide risk control advice","spread the cost of an insured loss amongst many policyholders","provide a source of funds for capital investment."],"correctOption":2,"section":"Scope and functions of insurance","explanation":"Insurance works by collecting premiums from many policyholders so that the losses of the few are shared by the many. Option A sounds attractive, but insurance never pays for losses 'however sustained', only for losses caused by insured perils. Risk control advice (B) and investment funds (D) are useful by-products, not the main purpose."}},{"itemId":"aa79ed11-34dd-516c-b84c-74c5fced93fb","questionId":"c65700eb-2ff8-5e26-bcb9-46644fbf3b81","sourceKey":"bank:INS101:INS-0214","payload":{"prompt":"Salvage corps perform the following functions except","options":["Removal of the goods partly destroyed","Cleaning and restoring damaged goods","A & B","Payment of insurance premium"],"correctOption":3,"section":"Scope and functions of insurance","explanation":"Salvage corps were set up by fire insurers to save property during and after a fire, for example by removing partly damaged goods and cleaning and restoring them, so A, B and C are all genuine functions. Paying the insurance premium (D) is the insured's duty, not a salvage task."}},{"itemId":"c3a69780-8a8d-57dd-87f5-7ceaa00e995c","questionId":"71cdd44e-5ae6-5114-984c-f80afe56c799","sourceKey":"bank:INS101:INS-0230","payload":{"prompt":"______ insurance company is owned and established by a parent firm for the purpose of insuring the parent firm's loss exposure","options":["Marine","motor","captive","amicable"],"correctOption":2,"section":"Scope and functions of insurance","explanation":"A captive insurer is set up and owned by a parent company mainly to insure that parent's own risks. Marine (A) and motor (B) are classes of insurance, not types of company, and amicable (D) refers to an early life society."}},{"itemId":"d9c86562-ee62-524f-bc52-e7a0f9028166","questionId":"8941fbc0-88ae-578c-b413-3755fccd222f","sourceKey":"bank:INS101:INS-0231","payload":{"prompt":"Reasons for captive insurance include the following except","options":["Easier access to reinsurer","Greater stability in earnings","Difficulty in obtaining insurance","Reduced responsibility"],"correctOption":3,"section":"Scope and functions of insurance","explanation":"Firms form captive insurers because cover may be hard to obtain, because captives give easier access to reinsurers and because they help smooth out earnings, so A, B and C are genuine reasons. 'Reduced responsibility' (D) is not a reason, since the parent company still carries its own risks through the captive."}},{"itemId":"ed4575a3-84a2-5918-8a89-b51c52a1077b","questionId":"042f797c-c1ec-51e8-95b5-41f505c0e60c","sourceKey":"bank:INS101:INS-0232","payload":{"prompt":"______ is a situation whereby a company makes a conscious decision to set a fund aside to meet insurable losses.","options":["Self-insurance","Reinsurance","Intermediation","Friendly Insurance"],"correctOption":0,"section":"Scope and functions of insurance","explanation":"Self-insurance is when a firm deliberately sets aside its own fund to meet losses it could have insured. Reinsurance (B) is insurance bought by an insurer, intermediation (C) is the work of brokers and agents, and 'friendly insurance' (D) is not a method of risk financing."}},{"itemId":"e0178242-22ec-589f-80af-f2b9a1948659","questionId":"3cc172b5-ea9d-5532-84bc-c95b9c3e908e","sourceKey":"bank:INS101:INS-0284","payload":{"prompt":"Which of the following is not a nature/characteristics of insurance?","options":["Spreading of risk","Co-operative device","Insurance is not charity","None of the above"],"correctOption":3,"section":"Scope and functions of insurance","explanation":"Insurance spreads risk across many people, works as a co-operative device and is not charity, because benefits are paid for with premiums. All three are characteristics of insurance, so D is the right choice."}},{"itemId":"fe1da821-b160-5578-a33f-734c0a3d8d65","questionId":"e8720422-0f3e-5556-bc64-0a1f44861999","sourceKey":"bank:INS101:INS-0288","payload":{"prompt":"For insurance to take place, the loss must be predictable. Which of the following is false?","options":["The premium must be economically feasible","Probability of loss must not be very high","The premium can be collected back once the loss predicted didn't come to pass","None of the above"],"correctOption":2,"section":"Scope and functions of insurance","explanation":"Premium is the price of cover for the period, so it is not refunded just because no loss happened; the insured still enjoyed protection. Options A and B are genuine requirements of an insurable risk, since the premium must be affordable and the chance of loss must not be so high that loss is nearly certain. Option D is wrong because statement C is false."}},{"itemId":"8fd60c1a-94f3-5d2d-88be-eafb76ca35fb","questionId":"f34d0b0e-9187-591f-bd0e-68ec7574d0c7","sourceKey":"bank:INS101:INS-0361","payload":{"prompt":"The combination of a large number of exposure units by an insurer is important for the operation of insurance because:","options":["it reduces uncertainty in the aggregate","it allows the insurer to make accurate predictions","it spreads losses among the members of the group","all of the above."],"correctOption":3,"section":"Scope and functions of insurance","explanation":"Pooling many exposure units lets the law of large numbers work, which reduces uncertainty in the total, makes predictions more accurate and spreads each loss across the group. Since A, B and C are all true, 'all of the above' is the best answer; choosing any single one leaves out the others."}},{"itemId":"e19756b1-0f6c-55c6-af72-7685f0a96d30","questionId":"31d598e0-485e-5afb-a908-dd0b99e3b157","sourceKey":"bank:INS101:INS-0365","payload":{"prompt":"The primary purpose of insurance is to:","options":["Amplify exposure to risk","Shift risk from one to many","Eradicate all possible risks","Diminish profit margins"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"Insurance moves the financial burden of a loss from one person to a large group who all pay premiums into a common fund. Option C is wrong because insurance cannot stop risks from happening; it only shares their cost. Options A and D describe the opposite of what insurance does."}},{"itemId":"6227bc13-2c20-5eac-8ea6-efde25d18d97","questionId":"ed2b3883-a3de-5caa-9b9a-49a0fcc855f5","sourceKey":"bank:INS101:INS-0366","payload":{"prompt":"Which of the following is a characteristic of insurable risk?","options":["The loss must be widespread and devastating","The loss must be quantifiable and specific","The loss must be deliberate","The loss must be wholly unforeseeable"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"An insurable loss must be definite and measurable, so the insurer can tell whether it happened and how much to pay. Option A is wrong because catastrophic losses hitting everyone at once are hard to insure. Option C is wrong because losses must be accidental, and option D is wrong because insurers need to be able to estimate how often losses occur."}},{"itemId":"7139810c-fb0c-5beb-b9bb-e93121f6ba16","questionId":"1cbb913c-3a30-55f5-b5fe-0e8db9bc285c","sourceKey":"bank:INS101:INS-0370","payload":{"prompt":"The concept of risk pooling in insurance means:","options":["Distributing risk across a broad pool","Focusing risk on a single entity","Nullifying risk completely","Escalating risk for all involved"],"correctOption":0,"section":"Scope and functions of insurance","explanation":"Risk pooling means many people contribute to a common fund, so the losses of a few are shared by all. Option B is the opposite, since pooling spreads risk rather than concentrating it. Option C is wrong because pooling shares losses but does not make them disappear."}},{"itemId":"b1d3ef54-9500-5bc4-99cb-97a338911a7e","questionId":"2dedbf02-0bbb-5f12-86aa-53e86e499db0","sourceKey":"bank:INS101:INS-0373","payload":{"prompt":"Insurance helps to:","options":["Remove all monetary uncertainties","Safeguard against financial setbacks","Boost speculative uncertainties","Sidestep all forms of ambiguity"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"Insurance protects people and firms from the financial setback of a loss by paying compensation. Options A and D are wrong because insurance cannot remove all uncertainty. Option C is the opposite of its purpose."}},{"itemId":"3125b5c0-f14b-55a5-9dea-349bc04f9047","questionId":"4aba3b1e-8d23-5ac5-929e-94a403030fb4","sourceKey":"bank:INS101:INS-0378","payload":{"prompt":"Insurance provides peace of mind by:","options":["Wiping out all uncertainties","Lessening the financial toll of losses","Heightening speculative exposure","Eliminating premium payments"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"Insurance gives peace of mind because the insured knows the financial cost of a loss will be largely met. Option A is wrong because insurance cannot remove all uncertainty. Option D is wrong because premiums must still be paid for cover."}},{"itemId":"6b0081f1-57e7-5bcb-bff4-7d9448525f3a","questionId":"ed3e3d98-112d-510c-9f9e-099feec8f121","sourceKey":"bank:INS101:INS-0380","payload":{"prompt":"The scope of insurance includes:","options":["Solely life coverage policies","Safeguards against diverse risks","Only real estate protection","Exclusively medical coverage"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"The scope of insurance is broad, covering life, property, liability, health and many other risks. Options A, C and D each limit insurance to a single class, which is too narrow."}},{"itemId":"23013df7-a8fe-54c3-91e2-404c43f4b90c","questionId":"3d4ccb12-a2d6-5ad5-b8c5-3b305c3724d0","sourceKey":"bank:INS101:INS-0381","payload":{"prompt":"A key function of insurance is to:","options":["Elevate financial vulnerability","Offer monetary stability","Curtail job opportunities","Prevent all damages"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"A central function of insurance is to provide financial security by compensating losses, so people and businesses can recover. Option D is wrong because insurance pays for damage but cannot prevent all of it. Options A and C are the opposite of what insurance does."}},{"itemId":"22ff66e6-0ab8-549a-94db-c1815fd2bd27","questionId":"fc68b1b9-8421-5c32-bf62-86991b9e69d6","sourceKey":"bank:INS101:INS-0382","payload":{"prompt":"Insurance contributes to the economy by:","options":["Limiting investment prospects","Supplying funds for long-term projects","Raising unemployment rates","Hindering economic expansion"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"Insurers collect premiums ahead of claims and invest them, especially life funds, which supplies long-term funds to the economy. Options A and D are the opposite of this role. Option C is wrong because the insurance industry creates jobs."}},{"itemId":"77b977d5-2ef2-5ca4-be3f-0d7c2f9fc758","questionId":"71840c6e-ff12-546e-810b-2265c220beed","sourceKey":"bank:INS101:INS-0383","payload":{"prompt":"Which of the following is a social function of insurance?","options":["Heightening personal risk","Easing societal loss burdens","Withdrawing community aid","Weakening fiscal resilience"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"Insurance eases the burden of losses on society, for example by helping families and businesses recover instead of falling into hardship. Options A, C and D are the opposite of this social benefit."}},{"itemId":"d5110c49-8d38-5ecb-bbf4-4b609780c19a","questionId":"f376bdc1-44a1-5a53-a30e-3f654559c275","sourceKey":"bank:INS101:INS-0384","payload":{"prompt":"Insurance promotes risk management by:","options":["Fostering reckless behavior","Mandating safety precautions","Hiking premiums arbitrarily","Skipping risk evaluations"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"Insurers encourage loss prevention by requiring safety measures, such as fire extinguishers or alarms, as conditions of cover or for better rates. Option A is wrong because insurers try to discourage careless behaviour. Option D is wrong because insurers assess risks before accepting them."}},{"itemId":"0a39ba9f-0d6e-5f67-8ec1-29431f00dd76","questionId":"b819d914-b6c1-52e5-a73e-42bb072ea491","sourceKey":"bank:INS101:INS-0386","payload":{"prompt":"Insurance helps businesses by:","options":["Limiting their risk-taking capacity","Enabling calculated risks with backup","Raising operational expenses","Halting all commercial actions"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"With losses covered by insurance, businesses can take calculated risks such as expanding or investing, knowing they have financial backup. Option A is the opposite effect. Option D is wrong because insurance supports business activity rather than halting it."}},{"itemId":"672347a6-9646-58bb-b4cf-f1b8237331d3","questionId":"5d25310f-b655-5ca9-bfe4-c093c0d0a7b8","sourceKey":"bank:INS101:INS-0387","payload":{"prompt":"The scope of insurance includes which of the following?","options":["Life and property risk coverage","Only speculative ventures","Just gaming activities","Merely temporary risks"],"correctOption":0,"section":"Scope and functions of insurance","explanation":"Insurance covers a wide range of risks to life and property, along with liability and other classes. Option B is wrong because speculative ventures are generally not insurable. Options C and D are far too narrow."}},{"itemId":"ab04c9bb-e857-5569-a159-b3b32255b96b","questionId":"c960a647-f638-541b-be50-8e995c3ec71d","sourceKey":"bank:INS101:INS-0388","payload":{"prompt":"A function of insurance in the private sector is to:","options":["Generate investment capital","Cut public funding reliance","Boost taxation levels","Evade financial foresight"],"correctOption":0,"section":"Scope and functions of insurance","explanation":"Insurers invest the premiums they collect, which generates capital for businesses and projects in the private sector. Option B may be a side effect, but it is not the main private-sector function of insurance. Options C and D are not functions of insurance."}},{"itemId":"3ed57834-8f72-5976-86a6-8ed5f959dd5b","questionId":"6cc785f2-6c53-54ae-9264-7d0f689fd641","sourceKey":"bank:INS101:INS-0390","payload":{"prompt":"The function of risk transfer in insurance means:","options":["The insured keeps all risks","Risk moves from insured to insurer","Risk vanishes entirely","Risk grows for the insured"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"Risk transfer means the financial burden of a possible loss moves from the insured to the insurer in return for a premium. Option A is the situation without insurance. Option C is wrong because the risk still exists; only its financial cost is shifted."}},{"itemId":"b2e68488-5575-51bc-b0d8-60489daa23f0","questionId":"2831bcaa-0036-5b30-9114-e8eeddb05f5f","sourceKey":"bank:INS101:INS-0391","payload":{"prompt":"Insurance encourages savings through:","options":["Life policies with savings features","Raising premium rates","Undermining financial safety","Discouraging future planning"],"correctOption":0,"section":"Scope and functions of insurance","explanation":"Life policies with a savings element, such as endowment policies, encourage people to save regularly through their premiums. Option B is just about price, not saving. Options C and D are the opposite of how these policies work."}},{"itemId":"b3e093bc-6d2a-5cb0-89f8-d6be62e2eea3","questionId":"9d13c2cb-30a9-591e-9c03-0fde266d8844","sourceKey":"bank:INS101:INS-0395","payload":{"prompt":"The function of insurance in reducing uncertainty helps:","options":["People prepare for the future","Heighten monetary risks","Avoid all funding options","Slow economic advancement"],"correctOption":0,"section":"Scope and functions of insurance","explanation":"By reducing the uncertainty of financial loss, insurance lets people plan for the future with more confidence. Options B, C and D describe the opposite effect."}},{"itemId":"fdb65eb1-cc45-5e70-9ad1-30a1f82d7ec3","questionId":"a36ce9b9-4c01-54ea-a790-86e4a7e9882d","sourceKey":"bank:INS101:INS-0423","payload":{"prompt":"The analysis of insurance involves:","options":["Evaluating risks for premiums","Evading all payouts","Shrinking coverage areas","Overlooking contract terms"],"correctOption":0,"section":"Scope and functions of insurance","explanation":"Insurance analysis involves assessing risks so insurers can set suitable premiums and terms. Options B, C and D describe practices that would undermine insurance rather than analyse it."}},{"itemId":"aaf0c471-29c4-5415-bad4-86ac46862a8f","questionId":"bb37c3b6-74bb-5afe-8049-d571185f015d","sourceKey":"bank:INS101:INS-0428","payload":{"prompt":"The primary function of an insurance company is to:","options":["Produce physical goods","Shield against risk losses","Promote retail products","Employ large workforces"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"An insurance company exists mainly to protect policyholders against financial losses from insured risks. Options A and C describe manufacturing and retail firms. Option D may be a side effect, not the main function."}},{"itemId":"f348e240-523d-59b8-8ecf-6c79a0df29fe","questionId":"7063a1a5-7278-50b4-b443-7e46153796c2","sourceKey":"bank:INS101:INS-0839","payload":{"prompt":"Insurance helps to:","options":["Prevent adverse situations from occurring","Reduce the financial consequences of adverse situations","Negate all consequences of adverse situations","Make assets continuously productive"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"Insurance cannot stop accidents happening, but it reduces their financial impact by paying compensation when they do. Option A is wrong because preventing losses is risk control, not insurance, and option C goes too far because insurance cannot remove every consequence of a loss."}},{"itemId":"b8bf9804-69e2-5746-8351-8d9693515777","questionId":"7ce1f639-715e-5055-bae1-a5d5d426c3a3","sourceKey":"bank:INS101:INS-0846","payload":{"prompt":"By transferring risk to the insurer, it becomes possible:","options":["To enjoy from floods","To enjoy and make money from insurance","To enjoy a fire in the factory","To enjoy peace of mind and plan one's business more effectively"],"correctOption":3,"section":"Scope and functions of insurance","explanation":"Transferring risk to an insurer gives peace of mind, because the insured knows a loss will be compensated and can plan the business with more confidence. Option B is wrong because insurance is meant to compensate, not to make a profit, and options A and C make no sense."}},{"itemId":"70f2d858-778f-5f08-9dd9-a2f76d3be2c5","questionId":"2c290c64-3b6c-5e2c-8cf6-463a7fce6409","sourceKey":"bank:INS101:INS-0848","payload":{"prompt":"Which of the following statements is true?","options":["Insurance is a method of sharing the losses of a \"few\" by \"many\"","Insurance is a method of transferring the risk of an individual to another individual","Insurance is a method of sharing the losses of \"many\" by a \"few\"","Insurance is a method of transferring the gains of a few to the many"],"correctOption":0,"section":"Scope and functions of insurance","explanation":"Insurance pools the premiums of many people so that the losses of the few who suffer them can be paid. Option C reverses this, and option B is wrong because the risk is transferred to an insurer and shared through the pool, not passed to one other individual."}},{"itemId":"7e445ecf-f64f-5a7b-8c90-704163acbd43","questionId":"a1e39845-1448-5953-acb4-f755574aa411","sourceKey":"bank:INS101:INS-1049","payload":{"prompt":"An insurance company formed for the purpose of underwriting the risks of its parent company is called","options":["a reinsurance company","a captive insurance company","a proprietary insurance company","a mutual insurance company"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"A captive insurer is owned by a parent firm (or group of firms) and exists mainly to insure that parent's own loss exposures. A mutual company (option D) is owned by its many policyholders, and a reinsurance company (option A) insures other insurers rather than one parent group."}},{"itemId":"368d8333-569d-57d6-9c4f-b8c3eb6f93b4","questionId":"32c8849d-ceee-5256-b849-1d70751c1094","sourceKey":"bank:INS101:INS-1050","payload":{"prompt":"The _______ definition of insurance defines insurance as a co-operative device to spread the loss caused by a particular risk over a number of persons who are exposed to it and agree to insure themselves against the risk.","options":["contractual","functional","legal","statutory"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"The functional definition looks at what insurance does: it spreads the loss of a few over the many people exposed to the same risk. The contractual definition (A), by contrast, describes insurance as an agreement where one party promises to pay the other for a loss in return for a premium, and options C and D focus on law rather than on what insurance does."}},{"itemId":"5c52f347-7045-5e94-9ba0-43f0733d7199","questionId":"a35edbe1-07e7-5b38-bd68-6749a6719820","sourceKey":"bank:INS101:INS-1072","payload":{"prompt":"All of the following are disadvantages of using insurance EXCEPT","options":["There is an opportunity cost because premiums must be paid in advance.","Considerable time and effort must be spent selecting and negotiating coverages.","It results in considerable fluctuations in earnings after a loss occurs.","Attitudes toward loss control may become lax."],"correctOption":2,"section":"Scope and functions of insurance","explanation":"Insurance actually smooths out earnings, because the insurer pays for a large loss that would otherwise cause a big drop in profit. Options A, B and D are genuine drawbacks: premiums are paid upfront, choosing cover takes effort, and insured people may become careless about preventing losses."}},{"itemId":"df11c172-9918-58bf-9a31-07a8157254ab","questionId":"9e956b57-a31b-5054-b6e7-75f12a82a9d8","sourceKey":"bank:INS101:INS-1080","payload":{"prompt":"The insurance technique is based on the principle of","options":["Pooling system.","Compensating others.","Helping others.","Indemnity"],"correctOption":0,"section":"Scope and functions of insurance","explanation":"Insurance works by pooling: many people pay small premiums into a common fund, and the fund pays for the losses of the unlucky few. Indemnity (D) is tempting, but it is a legal principle about the amount paid, and it does not even apply to life assurance, while pooling underlies all insurance."}},{"itemId":"40df2d81-31e1-51a7-865d-afc26c999495","questionId":"feca83c4-4f0b-50d1-b840-7ea3ff607f38","sourceKey":"bank:INS101:INS-1138","payload":{"prompt":"Insurance cannot stop a risk from happening, but it provides for","options":["an increase in the chance of the risk","the prevention of the risk","the complete removal of the risk","compensation for the financial loss caused by the risk"],"correctOption":3,"section":"Scope and functions of insurance","explanation":"Insurance does not prevent fires, accidents or floods; what it does is pay for the financial loss when they happen. The options about preventing or removing the risk describe loss prevention, not insurance."}},{"itemId":"e5da8c50-9228-59a8-86c8-15b66b1d15d8","questionId":"69c8dae0-6abf-50a1-b335-172c5176482b","sourceKey":"bank:INS101:INS-1173","payload":{"prompt":"Which social device spreads the losses of a few people over many, so that society reduces the burden of certain risks?","options":["Premium","Policy","Contract of sale","Insurance"],"correctOption":3,"section":"Scope and functions of insurance","explanation":"Insurance pools the contributions of many people so that the few who suffer a loss can be compensated, which is why it is called a social device. Option A is the payment each person makes into the pool, and B is the document that shows the terms. Neither is the arrangement itself."}},{"itemId":"a844320c-ad1d-58d6-8fcc-d2d4f3c54722","questionId":"1632bb57-3360-537a-826b-85e2a19809bd","sourceKey":"bank:INS101:INS-1188","payload":{"prompt":"For a risk to be insured, the occurrence of the loss must be","options":["Certain","Deliberately caused","Uncertain","Already known to have happened"],"correctOption":2,"section":"Scope and functions of insurance","explanation":"Insurance works only when nobody knows whether or when a loss will happen; that uncertainty is what the insurer accepts in return for the premium. Option A is wrong because a certain loss is not a risk at all. Options B and D describe losses that would make the contract a fraud or pointless."}},{"itemId":"ac5ac184-fd68-5ef3-b07e-c746e34db989","questionId":"de344fa7-dc75-5ab9-8e91-27d9d305d057","sourceKey":"bank:INS101:INS-1226","payload":{"prompt":"Which insurance provides financial support to farmers when their harvest fails because of drought or flood?","options":["Livestock insurance","Burglary insurance","Fire insurance","Crop insurance"],"correctOption":3,"section":"Scope and functions of insurance","explanation":"Crop insurance compensates farmers when crops are damaged or fail because of perils like drought, flood or pests, which matters a lot in an agricultural country like Nigeria. Option A covers animals rather than crops. Option B covers theft by forced entry, and C covers fire damage to property."}},{"itemId":"f57220c4-158e-5863-90e0-064d579d3571","questionId":"0a36cad2-21c7-5069-9a41-c7c425f5f4ff","sourceKey":"bank:INS101:INS-1229","payload":{"prompt":"Property insurance would NOT normally cover which of the following?","options":["Burglary at the owner's shop","Sickness of the owner","Fire damage to the owner's building","Loss of goods in transit"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"Property insurance protects physical things such as buildings, stock and goods, so an illness affecting a person is outside it and belongs to health or personal accident cover. Options A, C and D are all losses of or damage to property, which property insurance is designed to cover."}},{"itemId":"4566e0a4-04ad-5958-8dfa-86a686384fa5","questionId":"da7cf89a-990d-538d-a144-de7578c31a42","sourceKey":"bank:INS101:INS-1242","payload":{"prompt":"A package policy that protects against several separate perils under one contract is called a","options":["Single-peril policy","Endorsement","Cover note","Multi-peril policy"],"correctOption":3,"section":"Scope and functions of insurance","explanation":"A multi-peril policy bundles cover for different perils, such as fire, burglary and liability, into one package. Option A covers only one named peril. Options B and C are insurance documents, not types of policy."}},{"itemId":"a8f4f0ad-c322-5898-b868-4817a1f50606","questionId":"7fb69700-ff6e-52ee-a2f8-dbe44be3e377","sourceKey":"bank:INS101:INS-1246","payload":{"prompt":"Risks faced by individuals and families, such as death, illness or accidental injury, are covered under","options":["Property insurance","Personal insurance","Liability insurance","Reinsurance"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"Personal insurance covers risks to people themselves, including life, health and personal accident. Option A covers physical things, and C covers legal responsibility to others. Option D is insurance bought by insurers, not by families."}},{"itemId":"d062b76a-1258-5ee7-bd15-927c9559c745","questionId":"a3ab812c-2957-5a1c-8a25-a159d4040692","sourceKey":"bank:INS101:INS-1254","payload":{"prompt":"A policy that covers a wide range of risks in one contract instead of a few named perils is often called a","options":["Excess policy","Floating policy","Declaration policy","Comprehensive policy"],"correctOption":3,"section":"Scope and functions of insurance","explanation":"A comprehensive policy gives broad all-round cover, for example a comprehensive motor policy covers damage to your own car as well as third party liability. Option A only pays above a set amount. Options B and C are ways of covering changing stock or shipments, not broad cover."}},{"itemId":"c065c803-9129-53f8-b34e-002ebb37af6a","questionId":"c2edabc9-423a-560a-aaf4-6dc87c0b60bf","sourceKey":"bank:INS101:INS-1275","payload":{"prompt":"Which of the following is NOT a social cost of insurance?","options":["Expenses of running insurance companies","Increased cost of capital","Fraudulent claims","Inflated (exaggerated) claims"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"Insurance actually lowers the cost of capital, because lenders and investors are more willing to fund businesses whose assets are insured, so this is a benefit, not a cost. Option A uses up resources, while C and D push up premiums for honest policyholders, so they are genuine social costs."}},{"itemId":"394e5582-b9de-5552-b8d8-55ee5d88c5d2","questionId":"e26b8342-5370-503f-95bb-b5bb816c0260","sourceKey":"bank:INS101:INS-1276","payload":{"prompt":"A tool manufacturer fears its wholesalers may fail to pay what they owe. Which insurance would protect it?","options":["Fidelity guarantee insurance","Credit insurance","Public liability insurance","Fire insurance"],"correctOption":1,"section":"Scope and functions of insurance","explanation":"Credit insurance pays the business if customers fail to settle their debts because of insolvency or default. Option A covers theft or fraud by the firm's own employees. Option C covers legal liability for injury or damage to others, and D covers fire damage to property."}},{"itemId":"81a5acc0-9e70-5db8-a930-ecad428bc2bb","questionId":"3ccb1400-68df-5917-bb6e-051e5d9dd93a","sourceKey":"bank:INS101:INS-0011","payload":{"prompt":"Fire insurance didn't come to stay until after the great fire of London which occurred in what year","options":["1667","1862","1666","1656"],"correctOption":2,"section":"Historical development of insurance","explanation":"The Great Fire of London broke out in 1666, burned for four days and destroyed more than 13,000 houses, and the scale of that loss is what made fire insurance take root. Option A, 1667, is a tempting slip because plans for rebuilding the city were drawn up the following year, but the fire itself happened in 1666. Options B and D are simply the wrong years."}},{"itemId":"cf903399-f3f2-58a1-8411-8455b5055df5","questionId":"38a762eb-b891-5681-b670-391cdf43750e","sourceKey":"bank:INS101:INS-0014","payload":{"prompt":"Where was the first method of transferring and distributing risk practiced?","options":["Italy","London","Athens","China and Babylon"],"correctOption":3,"section":"Historical development of insurance","explanation":"The earliest known methods of transferring and spreading risk were practised by Chinese and Babylonian traders, for example by spreading goods across many boats so one sinking would not ruin a trader. Italy (A) and London (B) became important much later in the history of marine insurance, and Athens (C) is not linked with the very first methods."}},{"itemId":"eeb9daac-7198-59d5-bf3b-c121f3b8d6ad","questionId":"38ae6ffc-6c3a-5985-9e80-6a83828cd203","sourceKey":"bank:INS101:INS-0016","payload":{"prompt":"_________ is the term for lightening the load by tossing merchandise overboard to save the ship.","options":["General Average","Off-loading","Jettison","Moderating"],"correctOption":2,"section":"Historical development of insurance","explanation":"Jettison means deliberately throwing cargo overboard to lighten a ship and save it in an emergency. Option A, general average, is the principle that all parties to the voyage share the cost of that sacrifice, so it is related but it is not the name of the act itself."}},{"itemId":"eed20c3e-00c1-54cc-8abd-b0fad9e81e55","questionId":"6fa17624-9254-5d34-88ea-ef9a57d5b0f9","sourceKey":"bank:INS101:INS-0017","payload":{"prompt":"Which of the following contract used where the ship is the security for the loan?","options":["Bottomry contract","Buttomry contract","Respondentia contract","Respondent contract"],"correctOption":0,"section":"Historical development of insurance","explanation":"Under a bottomry contract, money was lent to a shipowner with the ship itself pledged as security, and the loan did not have to be repaid if the ship was lost. Option C, respondentia, was the similar arrangement where the cargo, not the ship, was the security. Options B and D are misspellings, not real contracts."}},{"itemId":"98259d7a-e15e-57ca-8d1d-7d414a690b3e","questionId":"eda1e4c2-ef6f-590d-9bf5-c30cc221639e","sourceKey":"bank:INS101:INS-0062","payload":{"prompt":"Marine insurance practices in earlier times were traceable to the merchants of Hanseatic League of which country?","options":["Germany","England","United states of America","India"],"correctOption":0,"section":"Historical development of insurance","explanation":"The Hanseatic League was a trading alliance of merchant towns in northern Germany, and its merchants used early marine insurance practices. Option B, England, became a marine insurance centre later through Lloyd's. Options C and D have no link to the Hanseatic League."}},{"itemId":"e8e9995a-4b4e-58cb-8468-6d571222a36c","questionId":"cf3ddfb5-1027-5054-8aef-98210d7d4ad0","sourceKey":"bank:INS101:INS-0063","payload":{"prompt":"The type of loan for insurance for maritime business in those days found in the code of Hammurabi was developed by whom?","options":["The Greek","The Chinese","The Babylonians","The Arabians"],"correctOption":2,"section":"Historical development of insurance","explanation":"The Code of Hammurabi comes from ancient Babylon, and it set out rules for maritime loans that the borrower did not have to repay if the venture was lost. Option A, the Greeks, later used similar bottomry loans, but the Code of Hammurabi is Babylonian."}},{"itemId":"d3007144-556d-5aba-b036-2923e07b8173","questionId":"9a5dd2f2-b5ab-52a0-85b0-a3e921b9ac55","sourceKey":"bank:INS101:INS-0069","payload":{"prompt":"What is the name of the author of the first printed book on insurance?","options":["Prince de Gaule","Jerome de Viga","Pedro de Santarem","Erico de Santana"],"correctOption":2,"section":"Historical development of insurance","explanation":"Pedro de Santarem, a Portuguese jurist, wrote the first printed book on insurance, a treatise on marine insurance published in 1552. The names in options A, B and D are not connected with this work."}},{"itemId":"f73f9a40-1d1f-58fa-ba20-fd82d70ab045","questionId":"6d518e3b-e753-5758-bc58-f41adbba19b7","sourceKey":"bank:INS101:INS-0085","payload":{"prompt":"Before modern insurance was established in the late 17th century, \"friendly societies\" in which people donated amounts of money to a general sum that could be used for emergencies existed in which land?","options":["France","United states of America","England","Russia"],"correctOption":2,"section":"Historical development of insurance","explanation":"Friendly societies, where members paid into a common fund that could help them in emergencies, existed in England before modern insurance took shape in the late 17th century. Options A, B and D are not the country these early friendly societies are linked with."}},{"itemId":"d7a0aed1-b8d8-54d7-a06a-2432980a8065","questionId":"253828ee-60f4-59f3-90cc-f72f1eff41f9","sourceKey":"bank:INS101:INS-0092","payload":{"prompt":"In those days where cargo was involved in the security for loan in maritime trade, which of the following terms applied?","options":["Respondential","bottomry","causa proxima","caveat emptor"],"correctOption":0,"section":"Historical development of insurance","explanation":"Under respondentia, a loan for a voyage was secured on the cargo rather than the ship. Option B, bottomry, was the similar loan with the ship itself as security. Options C and D are legal phrases meaning proximate cause and buyer beware, which have nothing to do with maritime loans."}},{"itemId":"f14c159e-5f5a-5da1-ab6f-6e061da41a80","questionId":"62c09e6d-8d7a-563c-9326-291465a444b9","sourceKey":"bank:INS101:INS-0095","payload":{"prompt":"The Chinese and Babylonian traders operated in the first methods of transferring or distributing risks in monetary economy during the periods?","options":["2nd and 1st millennia BC respectively","3rd and 2nd millennia BC respectively","4th and 3rd millennia BC respectively","5th and 4th millennia BC respectively"],"correctOption":1,"section":"Historical development of insurance","explanation":"Chinese traders were spreading risk in the 3rd millennium BC, for example by sharing goods over many boats, and Babylonian traders developed risk-transfer arrangements in the 2nd millennium BC. So B gives the right periods in the right order. Options A, C and D shift the dates by a millennium or more."}},{"itemId":"9f1e82ea-7ddd-583c-944f-98a9eb332d3e","questionId":"465d50cb-1bdd-5289-aead-60b03d3f4783","sourceKey":"bank:INS101:INS-0097","payload":{"prompt":"What could easily pass as an early form of political insurance was the presentation of gifts from the various ethnic groups to","options":["The philosophers in ancient Greece","the pharaohs of ancient Egypt","Dukes of Edinburgh","Archaemenian monarchs in ancient Persia"],"correctOption":3,"section":"Historical development of insurance","explanation":"The Achaemenian monarchs of ancient Persia received gifts from the various ethnic groups under them, and this has been described as an early form of political insurance, since the givers expected protection in return. Options A, B and C are not linked with this practice."}},{"itemId":"4114db68-627e-52a1-bd69-dba91c80c7ef","questionId":"a454b48f-d9af-5ed6-95ee-626fa460a94b","sourceKey":"bank:INS101:INS-0101","payload":{"prompt":"The principle of general average was said to originate from which people?","options":["Rhodians","Babylonians","Egyptians","Italians"],"correctOption":0,"section":"Historical development of insurance","explanation":"General average is traced to the Rhodians, whose sea law said that when cargo was thrown overboard to save a ship, everyone who benefited would share the loss. Options B, C and D are other ancient peoples not linked to the origin of this rule."}},{"itemId":"8414c59d-fb47-5dbf-9eb7-c6b44c35d9f1","questionId":"0df81f6b-62cc-58ec-956f-c056840ec6f3","sourceKey":"bank:INS101:INS-0107","payload":{"prompt":"The name associated with the development of fire insurance is called ______","options":["Heubner Black","Dr. Bickelhaupt cline","Mark Greene","Nicholas Barbon"],"correctOption":3,"section":"Historical development of insurance","explanation":"Nicholas Barbon set up one of the first fire insurance offices in London after the Great Fire of 1666, and he is widely seen as the founder of modern fire insurance. Options A, B and C are names of other insurance writers and not founders of fire insurance."}},{"itemId":"c4162873-1420-5fbc-bdf4-c65ef3569597","questionId":"7cc71ae2-de94-56bf-9c4e-0624322ed170","sourceKey":"bank:INS101:INS-0112","payload":{"prompt":"The term \"Lombardy\" is a big name in insurance associated with what country?","options":["England","Italy","Germany","France"],"correctOption":1,"section":"Historical development of insurance","explanation":"Lombardy is a region of northern Italy, and Lombard merchants played a big part in spreading early marine insurance through Europe; Lombard Street in London is named after them. That is why the name is often wrongly linked with England (A), even though it comes from Italy."}},{"itemId":"ea2c2d73-632e-549d-8e4f-3633df4d6ddb","questionId":"3f377d82-609c-57f0-bcec-713286f6712d","sourceKey":"bank:INS101:INS-0158","payload":{"prompt":"The first set of people that mooted the idea of insurance are","options":["The British Merchants","The British Adventures","The Lombards of Italy","Only A & B"],"correctOption":2,"section":"Historical development of insurance","explanation":"The Lombard merchants of northern Italy are credited with developing marine insurance and carrying the idea to London, where Lombard Street is named after them. The British merchants and adventurers (A and B) took up the practice later, so D is also wrong."}},{"itemId":"c0da4db4-b98d-5fd0-a900-f89f6960c2b0","questionId":"242c6480-25bc-52e6-91f9-a4b2b8aff4c4","sourceKey":"bank:INS101:INS-0179","payload":{"prompt":"The first Life Assurance was written on the life of a merchant in what year?","options":["1583","1584","1683","1684"],"correctOption":0,"section":"Historical development of insurance","explanation":"The first recorded life assurance policy was issued in London in 1583 on the life of William Gibbons, for a period of twelve months. Option B, 1584, is tempting because that is when he died and the claim arose. 1683 and 1684 (C and D) are a century too late."}},{"itemId":"2601ff9c-cba9-5ead-95d9-bcda814e6090","questionId":"5f5d6088-d6c6-5a90-8b8d-c96a2825618a","sourceKey":"bank:INS101:INS-0180","payload":{"prompt":"Mr. William Gibbons was Assured for the sum of","options":["384 pounds","200 pounds","383 pounds","386 pounds"],"correctOption":2,"section":"Historical development of insurance","explanation":"William Gibbons was assured for 383 pounds, 6 shillings and 8 pence on the first recorded life policy, which is closest to 383 pounds. Options A and D are close figures meant to catch careless guessing, and B is far too low."}},{"itemId":"ffb11c35-2af5-5534-b788-a56bcdb298d6","questionId":"c4f5c8d2-3d63-58e2-afc1-8745fb434eed","sourceKey":"bank:INS101:INS-0197","payload":{"prompt":"The Marine Insurance was introduced to the UK by?","options":["UAC Insurance","United Nigeria Insurance Company","Northern Assurance","The Great Traders of Northern Italy"],"correctOption":3,"section":"Historical development of insurance","explanation":"Marine insurance reached England through the great trading merchants of northern Italy, the Lombards, who settled in London. UAC Insurance (A), United Nigeria Insurance Company (B) and Northern Assurance (C) are much later companies, two of them Nigerian, so they could not have introduced marine insurance to the UK."}},{"itemId":"6b0db2a1-6171-581d-8833-f1d66a839cf7","questionId":"212e6c51-eb83-5d80-99ff-e0a49d87b422","sourceKey":"bank:INS101:INS-0198","payload":{"prompt":"The Bottomry and Respondential Bonds involves ______","options":["Money given to sailors for sale keeping on the cargos","Loans to ship-owners/merchants to finance their voyage","Bonds being giving by the government","Payment for goods and services of merchants"],"correctOption":1,"section":"Historical development of insurance","explanation":"Bottomry and respondentia bonds were early loans to shipowners (secured on the ship) and merchants (secured on the cargo) to finance a voyage, repayable only if the voyage succeeded. That built-in risk-sharing made them a forerunner of marine insurance. They were not payments to sailors (A), government bonds (C) or payment for goods (D)."}},{"itemId":"af9bfc7c-8b54-5c5c-98af-e0c19c2f8791","questionId":"0a4fde66-99bf-5167-9740-a9346a88a303","sourceKey":"bank:INS101:INS-0199","payload":{"prompt":"When was the Chambers of Assurance Established?","options":["1575","1930","1953","1601"],"correctOption":0,"section":"Historical development of insurance","explanation":"A Chamber of Assurance was set up in London in 1575 to register marine insurance policies. Option D, 1601, is tempting because that is when an Act set up a special court for marine insurance disputes, while 1930 and 1953 (B and C) are far too late."}},{"itemId":"45c51a2c-afa0-5eae-b323-c440f998fc89","questionId":"47d26d78-fe64-54c9-a207-29d81a2069c7","sourceKey":"bank:INS101:INS-0283","payload":{"prompt":"The Great Fire of London in ______ in which more than 13,000 houses were lost, gave a boost to insurance and the first fire insurance company, called the Fire Office, was started in ________","options":["1966 and 1690","1866 and 1760","1666 and 1680","None"],"correctOption":2,"section":"Historical development of insurance","explanation":"The Great Fire of London was in 1666, and the first fire insurance company, the Fire Office, was started by Nicholas Barbon around 1680. Options A and B get the year of the fire wrong."}},{"itemId":"c2ae955c-3dcc-5c66-8b14-43dee9a56c79","questionId":"f4847430-2ba5-507a-bdd9-527eeeea6d04","sourceKey":"bank:INS101:INS-0292","payload":{"prompt":"Which of the following contract is used where the cargo is the security for the loan?","options":["Bottomry contract","Buttomry contract","Respondentia contract","Respondent contract"],"correctOption":2,"section":"Historical development of insurance","explanation":"Respondentia is an old marine loan in which the cargo is pledged as security, so the loan is lost if the cargo is lost. Option A, bottomry, is the matching loan where the ship itself is the security. Options B and D are just misspellings or distortions of these terms."}},{"itemId":"d63c93a9-4378-5240-9114-933298280460","questionId":"7a94a7b2-113b-52e4-bd96-930979c9e18c","sourceKey":"bank:INS101:INS-0396","payload":{"prompt":"The earliest form of insurance in ancient societies involved:","options":["Cash-based transactions","Collective support pacts","State-enforced rules","Equity markets"],"correctOption":1,"section":"Historical development of insurance","explanation":"The earliest insurance took the form of mutual support agreements, where members of a group helped one another when a loss struck. Options A, C and D describe later developments such as money-based contracts, state regulation and share markets."}},{"itemId":"e75b3588-de56-5469-b04f-9ea5807decfb","questionId":"75501e21-7314-56ef-87ab-767ffa09b3e7","sourceKey":"bank:INS101:INS-0397","payload":{"prompt":"Chinese merchants in the 3rd millennium BC practiced risk distribution by:","options":["Insuring cargo on one ship","Spreading goods over many ships","Steering clear of rivers","Signing formal contracts"],"correctOption":1,"section":"Historical development of insurance","explanation":"Ancient Chinese merchants spread their goods across many boats, so that one boat sinking would only destroy a small part of each merchant's cargo. Option A is the opposite, since putting everything on one ship concentrates the risk. Option D is wrong because this was an informal practice, not a formal contract."}},{"itemId":"1bf623bc-9602-5b9c-a202-4cf3ce1cb874","questionId":"a859a267-9f87-5e2e-86ce-e0e61be492e2","sourceKey":"bank:INS101:INS-0398","payload":{"prompt":"The Code of Hammurabi (c. 1750 BC) introduced:","options":["Life coverage policies","Debt relief for lost shipments","Fire damage protection","Health care plans"],"correctOption":1,"section":"Historical development of insurance","explanation":"The Code of Hammurabi allowed traders who took loans for shipments to have the debt cancelled if the goods were lost or stolen, an early form of risk transfer. Options A, C and D describe kinds of insurance that came much later."}},{"itemId":"852145d8-5f1d-53ee-bbfc-47b8f46e99cc","questionId":"5dae3288-9069-53a1-8b58-e6260ae5e5cd","sourceKey":"bank:INS101:INS-0399","payload":{"prompt":"The 'general average' concept, developed by the inhabitants of Rhodes, involved:","options":["Sharing losses across traders","Dodging all sea hazards","Covering just one trader's goods","Nullifying trade risks"],"correctOption":0,"section":"Historical development of insurance","explanation":"General average is the rule that when cargo is thrown overboard to save a ship, all parties to the voyage share the loss in proportion. Option C is the opposite, since the loss is shared rather than borne by one trader. Options B and D are wrong because the rule shares losses but does not remove sea risks."}},{"itemId":"b058177b-1d92-5228-a374-b3e626694295","questionId":"c5bd7326-169f-5477-955d-c7ec404adb01","sourceKey":"bank:INS101:INS-0400","payload":{"prompt":"The first known insurance contract was created in:","options":["London post-1666 fire","Genoa in 1347 for trade","Ancient China, 3000 BC","Rome, 600 BC era"],"correctOption":1,"section":"Historical development of insurance","explanation":"The oldest known insurance contract was written in Genoa in 1347, for a shipment of goods. Option A refers to fire insurance, which grew after 1666. Options C and D refer to earlier risk-sharing practices, not formal insurance contracts."}},{"itemId":"2aab3662-825e-5be8-949d-b5b1f91c62d8","questionId":"3884a910-7815-506b-916b-d744d43063ea","sourceKey":"bank:INS101:INS-0401","payload":{"prompt":"The Great Fire of London in 1666 led to the development of:","options":["Life assurance plans","Property damage coverage","Maritime risk policies","Medical expense insurance"],"correctOption":1,"section":"Historical development of insurance","explanation":"The Great Fire of London in 1666 destroyed much of the city and led directly to the development of fire insurance for buildings. Option C is wrong because marine insurance existed long before 1666. Options A and D are other classes that developed separately."}},{"itemId":"f7f1e44a-e605-5e15-b28c-65d02c179d32","questionId":"9b3734bf-9c43-5d09-b458-f4687124f671","sourceKey":"bank:INS101:INS-0402","payload":{"prompt":"The first fire insurance company, the \"Insurance Office for Houses,\" was established by:","options":["Edward Lloyd of coffee fame","Nicholas Barbon, a pioneer","Benjamin Franklin in America","William Talbot in shipping"],"correctOption":1,"section":"Historical development of insurance","explanation":"Nicholas Barbon set up the Insurance Office for Houses after the Great Fire of London. Option A is wrong because Edward Lloyd's coffee house gave rise to the marine market at Lloyd's. Option C is wrong because Benjamin Franklin founded an American fire insurer much later."}},{"itemId":"ecf63a1f-f2da-577e-b749-427bd2afc103","questionId":"0dfbc30c-ea17-540c-9864-919ec3c6d40e","sourceKey":"bank:INS101:INS-0403","payload":{"prompt":"Lloyd's of London, established in the late 17th century, initially focused on:","options":["Fire damage protection","Marine trade insurance","Life expectancy policies","Accident compensation"],"correctOption":1,"section":"Historical development of insurance","explanation":"Lloyd's grew out of Edward Lloyd's coffee house, where merchants and shipowners met to arrange cover for ships and cargoes. Options A, C and D are classes that Lloyd's took on later or that developed elsewhere."}},{"itemId":"db444487-ed91-5576-ad43-4cbb14b49c1b","questionId":"9ee3a5fa-39bd-52d6-822b-05400903d9ce","sourceKey":"bank:INS101:INS-0404","payload":{"prompt":"The first life insurance company, Amicable Society for a Perpetual Assurance Office, was founded in:","options":["1706 in Britain","1666 after the fire","1848 for railways","1752 for equity"],"correctOption":0,"section":"Historical development of insurance","explanation":"The Amicable Society for a Perpetual Assurance Office was founded in Britain in 1706. Option B, 1666, is the year of the Great Fire of London. Option C, 1848, matches the founding of the first accident insurer for rail travellers."}},{"itemId":"29b3789d-651a-5a81-832b-422f0cf1604c","questionId":"eb19dd2b-45e8-5048-aabb-f12dd3dc9824","sourceKey":"bank:INS101:INS-0405","payload":{"prompt":"The Society for Equitable Assurances on Lives and Survivorship, founded in 1762, introduced:","options":["Premiums based on age","Uniform rates for all","Fire risk coverage","Shipping insurance"],"correctOption":0,"section":"Historical development of insurance","explanation":"The Equitable Society introduced premiums based on the age of the life assured, using mortality tables. Option B is what older schemes had done, charging everyone the same. Options C and D are other classes of insurance."}},{"itemId":"877b2030-d20a-5753-8a01-7725e442a27d","questionId":"000b2ca8-3a50-5f58-9817-bb98e1761fc2","sourceKey":"bank:INS101:INS-0406","payload":{"prompt":"The first accident insurance company, Railway Passengers Assurance Company, was founded in:","options":["1706 for early life","1848 for rail travel","1666 post-fire","1752 for equity"],"correctOption":1,"section":"Historical development of insurance","explanation":"The Railway Passengers Assurance Company was set up in 1848 to protect people travelling by rail against accidents, which made it the first accident insurer. Option C, 1666, is the year of the Great Fire of London, which spurred fire insurance rather than accident cover, and options A and D do not fit this company."}},{"itemId":"a99bd9e1-c2ad-5cf7-aa63-b1ef1e75ffb9","questionId":"a17f64e8-e27b-512d-8372-fcca251d7fc1","sourceKey":"bank:INS101:INS-0411","payload":{"prompt":"The Hand in Hand Fire & Life Insurance Society, founded in 1696, was notable for:","options":["Running its own firefighting unit","Specializing in marine risks","Offering health plans","Avoiding fire safety"],"correctOption":0,"section":"Historical development of insurance","explanation":"Like other early fire offices, the Hand in Hand Society kept its own firefighting team to put out fires at the buildings it insured. Option B is wrong because it was a fire office, not a marine insurer. Option D is the opposite of its practice."}},{"itemId":"e8b75657-e652-5d8e-85ce-ab61c95bdeb1","questionId":"7c682872-3c13-5a0d-ae64-e4ccab6f1bca","sourceKey":"bank:INS101:INS-0444","payload":{"prompt":"The National Insurance Act 1911 in Britain introduced:","options":["Fire damage coverage","Sickness and jobless insurance","Maritime risk protection","Property loss policies"],"correctOption":1,"section":"Historical development of insurance","explanation":"Britain's National Insurance Act 1911 created state schemes giving workers health (sickness) insurance and unemployment insurance, funded by contributions. Fire, marine and property cover (options A, C and D) were already provided by private insurers long before 1911."}},{"itemId":"72b4aab6-88f1-575b-a380-0f51414ae497","questionId":"e057acad-8a77-5701-b7bc-dab43ad2c489","sourceKey":"bank:INS101:INS-0445","payload":{"prompt":"Otto von Bismarck in Germany introduced:","options":["Fire risk policies","Pensions and accident coverage","Shipping insurance","Life assurance plans"],"correctOption":1,"section":"Historical development of insurance","explanation":"In the 1880s Bismarck's Germany introduced the first national social insurance schemes, including sickness insurance, accident insurance for workers and old-age and disability pensions. Fire, shipping and life assurance (options A, C and D) were private commercial covers, not his social programmes."}},{"itemId":"4be3b4ea-64c1-5b3f-8f2b-dcb3cff383bf","questionId":"6ba1cd3b-2179-57e8-a952-0aab3296a764","sourceKey":"bank:INS101:INS-0446","payload":{"prompt":"The Social Security Act of 1935 in the United States:","options":["Launched compulsory insurance","Outlawed all insurance","Targeted only fire risks","Ignored welfare needs"],"correctOption":0,"section":"Historical development of insurance","explanation":"The US Social Security Act of 1935 set up compulsory social insurance schemes, mainly old-age benefits and unemployment insurance funded by contributions. It did not ban insurance (option B), was not limited to fire (option C), and its whole purpose was welfare (so option D is wrong)."}},{"itemId":"03565fff-de37-58c0-9cda-c8d88018e233","questionId":"ca08ef72-a3aa-535d-8551-19af49bd091a","sourceKey":"bank:INS101:INS-0447","payload":{"prompt":"The Beveridge Report in Britain influenced:","options":["Modern welfare state growth","Cuts to insurance programs","Health coverage elimination","Jobless aid reduction"],"correctOption":0,"section":"Historical development of insurance","explanation":"The Beveridge Report of 1942 recommended a comprehensive social insurance system and laid the foundation for Britain's modern welfare state after the Second World War. Options B, C and D all suggest cutting welfare, which is the opposite of what the report proposed."}},{"itemId":"5afe1505-5494-5cdd-b691-198371105e3b","questionId":"8afd328f-77d7-5017-8783-a3bc0600bcc8","sourceKey":"bank:INS101:INS-0457","payload":{"prompt":"The VA Home Loan programs in the U.S. after World War II included:","options":["Lender protection insurance","Universal free housing","Only fire coverage","Maritime risk plans"],"correctOption":0,"section":"Historical development of insurance","explanation":"Under the US VA home loan programme after World War II, the government guaranteed part of veterans' housing loans, protecting lenders against loss if a borrower defaulted. It did not give free housing to everyone (option B), and it had nothing to do with fire or marine cover (options C and D)."}},{"itemId":"551e67e4-bff3-568d-affb-04fcd0ca314b","questionId":"8cabdc63-efa9-57fc-864a-271978be1ad3","sourceKey":"bank:INS101:INS-0460","payload":{"prompt":"The GI life insurance policy program in the U.S. was designed to:","options":["Lessen military loss impacts","Offer fire protection","Lower unemployment rates","Evade welfare systems"],"correctOption":0,"section":"Historical development of insurance","explanation":"The GI (servicemen's) life insurance programme gave American soldiers affordable life cover so that their families would be protected financially if they died in service. It was not fire insurance (option B), not an unemployment measure (option C), and was itself part of a welfare approach (so option D is wrong)."}},{"itemId":"9040927c-f5d6-5b77-959b-5cf5ba21e26b","questionId":"6085dc77-fc81-53ec-b76a-4da9d658d232","sourceKey":"bank:INS101:INS-0864","payload":{"prompt":"Which of the following individuals founded the Philadelphia Contributionship, an early American fire insurance company, in 1752?","options":["Benjamin Franklin","Isaac Newton","Leonardo da Vinci","Albert Einstein"],"correctOption":0,"section":"Historical development of insurance","explanation":"Benjamin Franklin founded the Philadelphia Contributionship in 1752, and it refused to insure all-wooden houses because of their high fire risk. Newton, da Vinci and Einstein (options B, C and D) are famous for science and art, not for insurance."}},{"itemId":"7ca750f8-8995-51ed-910d-68efe774f26c","questionId":"8a547fd4-a301-5854-bbd0-56d2f7bc21c5","sourceKey":"bank:INS101:INS-1041","payload":{"prompt":"What could pass as an early form of political insurance was the presentation of gifts by the various ethnic groups to","options":["the Achaemenian monarchs of ancient Persia","the Pharaohs of ancient Egypt","the emperors of ancient Rome","the kings of ancient Babylon"],"correctOption":0,"section":"Historical development of insurance","explanation":"In ancient Persia, the Achaemenian monarchs received gifts from the various ethnic groups, and these were recorded so that the givers could expect help from the monarch in times of trouble, a bit like insurance. The other options name real ancient rulers, but this gift-for-protection practice is linked with Persia."}},{"itemId":"182a982f-cdb3-51d2-8641-a3653e4c68b9","questionId":"184ecd02-974c-5d25-a6f7-7fe399118556","sourceKey":"bank:INS101:INS-1045","payload":{"prompt":"The principle of general average is said to have originated from which people?","options":["the Rhodians","the Egyptians","the Babylonians","the Chinese"],"correctOption":0,"section":"Historical development of insurance","explanation":"General average comes from the sea law of the island of Rhodes: when cargo is thrown overboard to save a ship, everyone who benefits shares the loss. The Chinese and Babylonians are linked with even older ways of spreading risk, such as dividing goods across many boats or loans cancelled on loss, but not with general average."}},{"itemId":"9dbb6364-8796-5895-9bef-c1d7f08897ad","questionId":"cabca321-ee9c-52ee-8332-7497de3938d9","sourceKey":"bank:INS101:INS-1047","payload":{"prompt":"Early marine insurance practices were traceable to the merchants of the Hanseatic League, which was based mainly in which present-day country?","options":["Germany","Greece","Spain","Italy"],"correctOption":0,"section":"Historical development of insurance","explanation":"The Hanseatic League was a trading association of merchant towns of northern Germany, such as Hamburg and Lubeck, whose merchants used early forms of marine insurance. Italy (D) is tempting because Lombard merchants were also important in early marine insurance, but they were not part of the Hanseatic League."}},{"itemId":"8abdffb7-615a-5f0c-b51d-dd41ad6a17e4","questionId":"da3be4b6-ef8c-5842-9e7c-be1aec278294","sourceKey":"bank:INS101:INS-1051","payload":{"prompt":"Chinese and Babylonian traders practised the earliest methods of transferring or distributing risk in a monetary economy during which periods respectively?","options":["3rd and 2nd millennia BC","1st millennium BC and 1st century AD","1st and 2nd centuries AD","5th and 6th centuries AD"],"correctOption":0,"section":"Historical development of insurance","explanation":"Chinese merchants spread their goods across many boats in the 3rd millennium BC, and Babylonian traders used loans that were cancelled if goods were lost in the 2nd millennium BC. Options B, C and D place these practices far too late, long after they had begun."}},{"itemId":"28675955-5fa4-5db0-a3b2-bdfa07667211","questionId":"8b19a6c8-ad92-51e3-b90c-3605014064db","sourceKey":"bank:INS101:INS-1060","payload":{"prompt":"The name often associated with the development of fire insurance is","options":["Lord Mansfield","Edward Lloyd","Adam Smith","Nicholas Barbon"],"correctOption":3,"section":"Historical development of insurance","explanation":"After the Great Fire of London in 1666, Nicholas Barbon set up one of the first fire insurance offices, so his name is linked with the growth of fire insurance. B is associated with the coffee house that grew into the Lloyd's marine market, not fire insurance."}},{"itemId":"618f172b-8d6d-5822-be0d-a2edcd20fe27","questionId":"79aee112-fa3f-523b-884e-5f53fd0faf15","sourceKey":"bank:INS101:INS-1145","payload":{"prompt":"The earliest known written insurance contract, made in Europe in 1347, covered which class of insurance?","options":["Marine insurance","Life assurance","Motor insurance","Fire insurance"],"correctOption":0,"section":"Historical development of insurance","explanation":"Insurance began with sea trade: merchants and shipowners wanted protection for ships and cargo on risky voyages, so the earliest known contracts were marine. Option C cannot be right because motor vehicles did not exist until centuries later. Fire insurance (D) only became organised after the Great Fire of London in 1666, and life assurance (B) developed later too."}},{"itemId":"0b92100b-b764-5a02-9ff2-a1bbf61749a2","questionId":"79d4d5d3-81e0-546b-905e-6220b299c973","sourceKey":"bank:INS101:INS-1146","payload":{"prompt":"After the Great Fire of London, Nicholas Barbon started one of the first organised fire insurance businesses. What was it called?","options":["The Fire Office","Lloyd's of London","The Royal Exchange","The Old Equitable"],"correctOption":0,"section":"Historical development of insurance","explanation":"Nicholas Barbon's business, set up around 1680-1681, is commonly called the Fire Office and was also known as the Insurance Office for Houses; it insured buildings after the 1666 fire showed how much could be lost. Option B, Lloyd's, grew out of a coffee house where marine risks were underwritten, and option D was a life assurance society, not a fire office."}},{"itemId":"9f8be2c2-d58c-5932-aadf-7121599cdd8d","questionId":"ddc1a760-75e0-5b67-a2d3-ccd78cebfbce","sourceKey":"bank:INS101:INS-1147","payload":{"prompt":"The Society for the Equitable Assurance of Lives and Survivorships, founded in London in 1762 and seen as a pioneer of modern life assurance, was popularly known as","options":["The Fire Office","The Old Equitable","Lloyd's","The Hand in Hand"],"correctOption":1,"section":"Historical development of insurance","explanation":"The society was nicknamed the Old Equitable, and it is remembered for charging life premiums based on age and mortality tables. Option A was Nicholas Barbon's fire insurance business. Option C, Lloyd's, is a marketplace famous for marine underwriting, not this life office."}},{"itemId":"85faf46b-2739-53b9-b153-4632d008e64c","questionId":"79f04f41-bc5d-56b0-90f5-dd48550abca0","sourceKey":"bank:INS101:INS-1213","payload":{"prompt":"Organised fire insurance developed after the Great Fire of London in","options":["1866","1686","1666","1720"],"correctOption":2,"section":"Historical development of insurance","explanation":"The Great Fire of London in 1666 destroyed much of the city and showed people the need for protection against fire, so fire insurance grew quickly after it. Options A, B and D are later dates and do not match the fire."}},{"itemId":"48a690be-b547-5779-8771-de199b59fd41","questionId":"3c6d4126-f5c4-552e-8e1e-cff8e75b2ba9","sourceKey":"bank:INS101:INS-0077","payload":{"prompt":"The principal peril insured against under fire insurance is ______","options":["Fire itself","lightning","flood","thunderbolt"],"correctOption":0,"section":"Fire and marine insurance","explanation":"The main peril under a fire policy is fire itself, meaning actual ignition of the property. Lightning (B) and thunderbolt (D) are additional perils that a standard fire policy also covers, while flood (C) is not part of standard fire cover at all."}},{"itemId":"824f911e-7b29-57d1-8829-81a0981cdae6","questionId":"8e0ba388-5cd5-51bf-af01-fc080ab956b4","sourceKey":"bank:INS101:INS-0084","payload":{"prompt":"A ______ intended to cover a number of consignments setting out the general conditions of the insurance but no particular of the goods to be covered.","options":["Valued policy","floating policy","open policy","voyage policy"],"correctOption":1,"section":"Fire and marine insurance","explanation":"A floating policy describes the insurance in general terms and leaves the details of each shipment to be declared later, so one policy can cover a number of consignments. Option C, an open policy or open cover, is a similar arrangement, but it is usually an agreement to issue policies rather than this policy itself. Option A, a valued policy, fixes an agreed value, and option D, a voyage policy, covers one particular voyage."}},{"itemId":"c8759b08-c6b0-5bd2-93c9-9a18e114faff","questionId":"9ee0b820-ff40-5a99-b3f8-5e1a1ebae99a","sourceKey":"bank:INS101:INS-0105","payload":{"prompt":"A fire insurance policy which covers other incidental losses which commercial firms are exposed to as a result of disruptions of business is called______","options":["Combined policy","sprinkler linkage policy","consequential loss policy","special peril policy"],"correctOption":2,"section":"Fire and marine insurance","explanation":"A consequential loss (business interruption) policy covers the loss of profits and extra costs a business suffers when insured damage disrupts its operations. Option A, a combined policy, groups several covers together. Option D, special perils, adds extra perils to the material damage cover rather than covering trading losses."}},{"itemId":"d432e12d-a316-5913-b629-14c6ad3af715","questionId":"f6c2349c-219e-52ec-a90e-e112761b98fd","sourceKey":"bank:INS101:INS-0108","payload":{"prompt":"Apart from actual ignition, standard fire policy also covers damages caused by: (i) lightning (ii) explosion of any kind (iii) spontaneous combustion, self-heating and fermentation (iv) subterranean fire (v) explosion resulting from domestic usage of gas","options":["i","i and v only","iii and iv only","i and ii only"],"correctOption":1,"section":"Fire and marine insurance","explanation":"Besides fire itself, a standard fire policy covers lightning and explosion of gas or boilers used for domestic purposes, so B is correct. Explosion of any kind (ii) is too wide, because most other explosions need extra cover. Spontaneous combustion and subterranean fire (iii and iv) are excluded unless special perils are added, so C is wrong."}},{"itemId":"27db2799-8d27-5fab-b2b7-d8f93756d4ba","questionId":"d070dcce-aae2-59d8-a3fe-5f1cbbe69dd6","sourceKey":"bank:INS101:INS-0110","payload":{"prompt":"The policy that covers the subject matter from terminus a quo to terminus ad quem is a","options":["valued policy","floating policy","voyage policy","time policy"],"correctOption":2,"section":"Fire and marine insurance","explanation":"A voyage policy covers the subject matter from a starting point (terminus a quo) to a destination (terminus ad quem), regardless of the time taken. Option D, a time policy, covers a fixed period of time instead. Option B, a floating policy, covers many shipments declared later."}},{"itemId":"b00406f5-2388-5e9c-9a80-37f7803bcdb2","questionId":"bc38a9c2-ef64-55dd-8b66-567aea9c75a5","sourceKey":"bank:INS101:INS-0165","payload":{"prompt":"Loss or damage caused by fire spreading from its natural confine is covered","options":["False, because only lightning damage is covered","True","False","False, because fire is covered only when it starts inside its grate"],"correctOption":1,"section":"Fire and marine insurance","explanation":"A fire policy covers hostile fire, meaning fire that has escaped from where it is meant to be, such as a grate or a stove. Option D reverses this rule, since a fire burning in its proper place is not an insured fire, and option A is wrong because fire itself is the main peril."}},{"itemId":"6df2080d-4493-5961-b932-91306ecd16aa","questionId":"0335e638-f71d-5395-853c-59a622fa571c","sourceKey":"bank:INS101:INS-0202","payload":{"prompt":"All the followings are perils covered under marine insurance except","options":["Collision","Fire","Theft","None of the above"],"correctOption":3,"section":"Fire and marine insurance","explanation":"Collision, fire and theft are all perils a marine policy can cover, so none of the three is an exception. That is why 'none of the above' (D) is correct, and choosing A, B or C would wrongly remove a peril that marine insurance covers."}},{"itemId":"de825231-8a0b-5985-8c7c-36f45f187f6e","questionId":"f91fd5ff-00ed-5ca9-a7d3-f6bbbb956ef1","sourceKey":"bank:INS101:INS-0203","payload":{"prompt":"There is an Actual loss when the subject matter insured is ______?","options":["Sold","Bought","Destroyed","Delivered"],"correctOption":2,"section":"Fire and marine insurance","explanation":"An actual total loss happens when the subject matter is destroyed or so damaged that it is no longer the thing that was insured. Selling (A), buying (B) or delivering (D) the goods are normal trading events, not losses."}},{"itemId":"70c39ad9-5e63-5833-8828-303f85917f2f","questionId":"74bf2c69-cca9-538a-88fc-13a35885a720","sourceKey":"bank:INS101:INS-0204","payload":{"prompt":"RDC means","options":["Running Down Clause","Royal Dockyard Cargo","Runtime Dark Commission","Royal Dockyard Committee"],"correctOption":0,"section":"Fire and marine insurance","explanation":"RDC stands for the Running Down Clause in a marine hull policy, which covers the shipowner's liability for damage caused when his ship collides with another vessel. The other options (B, C and D) are made-up expansions that do not exist in marine insurance."}},{"itemId":"54499549-5dd0-5421-9dcc-1f0940908db1","questionId":"9df2ae30-adb8-59fd-9ac6-3b5e18ea9994","sourceKey":"bank:INS101:INS-0205","payload":{"prompt":"______ refers to the cost of transporting the good?","options":["Freight","Collision","Tax","Revenue"],"correctOption":0,"section":"Fire and marine insurance","explanation":"Freight is the charge paid for carrying goods, and it is an insurable interest in marine insurance alongside hull and cargo. Collision (B) is a peril, while tax (C) and revenue (D) have nothing to do with the cost of carriage."}},{"itemId":"3d93a82c-4b2f-5dc2-9919-592744a39850","questionId":"16ad790b-6095-5ab4-94ed-bd260a765158","sourceKey":"bank:INS101:INS-0206","payload":{"prompt":"The main purpose of fire insurance is to provide compensation to an insured person in the event of ______ to property insured","options":["Fire Damage","Ship Wreckage","Death","Accident"],"correctOption":0,"section":"Fire and marine insurance","explanation":"Fire insurance exists to compensate the insured when insured property suffers fire damage. Shipwreck (B) belongs to marine insurance, death (C) to life assurance and accident (D) to accident insurance."}},{"itemId":"7fde3aaf-bb80-5b1c-9214-0c33fe4e8152","questionId":"2068ebba-7e7c-5040-b81d-a8f8b92ab421","sourceKey":"bank:INS101:INS-0207","payload":{"prompt":"In the early development of Fire Insurance ______ is a symbol used to indicate building that is insured","options":["Private Fire Brigades","Fire Marks","Fire Insurance duty","Public Address system"],"correctOption":1,"section":"Fire and marine insurance","explanation":"Fire marks were metal plates fixed to insured buildings to show which fire office had insured them, so that office's fire brigade would put out the fire. Private fire brigades (A) were the firefighters themselves, and fire insurance duty (C) was a tax, not a symbol."}},{"itemId":"f8e79005-9e5a-531b-956d-c4c208fc483c","questionId":"c4cb3a60-cf8e-5af0-bd92-c4e62ca0915f","sourceKey":"bank:INS101:INS-0209","payload":{"prompt":"A ______ is a fire fighting equipment that earns substantial discount for an insured when installed in the insured's premises","options":["Fire Brigades","Fire System","Thunderbolt","Sprinkler system"],"correctOption":3,"section":"Fire and marine insurance","explanation":"A sprinkler system puts out or controls a fire automatically, so insurers give a substantial premium discount where one is installed. Fire brigades (A) are people, not equipment in the insured's premises, and a thunderbolt (C) is lightning, which is a peril."}},{"itemId":"d92edce9-7baa-54b5-9f50-0ff40307cabb","questionId":"3f135be0-95c9-57f9-9d76-1e1c0bad31dd","sourceKey":"bank:INS101:INS-0212","payload":{"prompt":"The extent of damage sustained through fire incidents is termed ______?","options":["Fire Brigade","Fire surveyors","Fire Waste","Fire Marks"],"correctOption":2,"section":"Fire and marine insurance","explanation":"Fire waste is the term for the damage and destruction caused by fires, often measured as the loss to the nation's resources. Fire brigades (A) fight fires, fire surveyors (B) inspect risks and fire marks (D) were plates showing a building was insured."}},{"itemId":"4a6f027b-995e-54f2-8fe8-414a6c69b02b","questionId":"69a631d0-8465-5f09-8238-355f9be8a8ee","sourceKey":"bank:INS101:INS-0213","payload":{"prompt":"______ are experts in fire insurance inspections?","options":["Fire surveyors","Fire brigade","Fire waste","Fire Marks"],"correctOption":0,"section":"Fire and marine insurance","explanation":"Fire surveyors are the specialists who inspect buildings and processes to judge the fire risk before an insurer accepts it. Fire brigades (B) fight fires rather than inspect for insurers, fire waste (C) is the loss fire causes, and fire marks (D) were old plates on insured buildings."}},{"itemId":"d225c242-b8b1-5a14-800c-4878c2543f38","questionId":"b2d9bd7f-bc62-5a38-9de9-30d7252b6580","sourceKey":"bank:INS101:INS-0276","payload":{"prompt":"Which of the following is correct?","options":["Under fire insurance policy, its own spontaneous fermentation (ignition) or heating or its undergoing any process involving the application of heat is covered as well as explosion of any type","Lightning is one of the special perils covered under fire insurance","Fire insurance policy covers losses incidental to fire outbreaks eg damage caused by breaking into the building, fire brigade damage","None of the above"],"correctOption":2,"section":"Fire and marine insurance","explanation":"A fire policy also pays for damage that happens as part of dealing with the fire, such as damage by the fire brigade or from breaking into the building to fight it. Option A is wrong because spontaneous fermentation or heating is excluded and only certain explosions are covered. Option B is wrong because lightning is a standard peril of a fire policy, not a special peril."}},{"itemId":"3da24000-d2d6-5d39-8a42-bd60be07b7ad","questionId":"b17835fc-db3b-57e6-9d9a-caab0d2a3f39","sourceKey":"bank:INS101:INS-0407","payload":{"prompt":"Fire insurance often includes coverage for:","options":["Loan default losses","Fire-related destruction","Healthcare costs","Job loss benefits"],"correctOption":1,"section":"Fire and marine insurance","explanation":"Fire insurance pays for loss or damage to property caused by fire, up to the sum insured. Option A, loan default, is a credit risk that a fire policy does not touch. Options C and D belong to health and unemployment cover."}},{"itemId":"0370c796-1bf9-50e5-876a-37fb281dfe03","questionId":"bc89fe32-23cd-5a62-aaac-d9b4e225465f","sourceKey":"bank:INS101:INS-0408","payload":{"prompt":"Marine insurance typically covers:","options":["Shipwreck and the losses","Structural building damage","Worker injury claims","Medical treatment costs"],"correctOption":0,"section":"Fire and marine insurance","explanation":"Marine insurance covers ships, cargo and freight against sea perils such as shipwreck. Option B belongs to fire or property insurance. Options C and D belong to employers' liability and health cover."}},{"itemId":"cb3b872a-a81f-5890-9dd6-32485c3ea9e4","questionId":"4150812d-65f9-5339-8986-97ff61ed7585","sourceKey":"bank:INS101:INS-0845","payload":{"prompt":"CTL as used in insurance means","options":["Contributory total loss","Constructive total loss","Construction totally lost","Contractors' total loss"],"correctOption":1,"section":"Fire and marine insurance","explanation":"CTL stands for constructive total loss, used mainly in marine insurance when the subject matter is not completely destroyed but saving or repairing it would cost more than it is worth. Option A mixes it up with contribution, and options C and D are not insurance terms."}},{"itemId":"45c73f50-35f6-5e5e-8ba3-21be725eb6aa","questionId":"cd9aab5e-0f30-5e61-ab93-87f0a11482fc","sourceKey":"bank:INS101:INS-1044","payload":{"prompt":"Apart from actual fire, the standard fire policy also covers damage caused by: (i) Lightning (ii) Explosion of any kind (iii) Spontaneous combustion, self-heating and fermentation (iv) Subterranean fire (v) Explosion of gas used for domestic purposes","options":["i, ii and v only","i and v only","i, ii, iii, iv and v","i, iii and iv only"],"correctOption":1,"section":"Fire and marine insurance","explanation":"The standard fire policy covers fire, lightning, and explosion of boilers or gas used only for domestic purposes. Explosion of any kind (ii) is too wide, and spontaneous combustion (iii) and subterranean fire (iv) are specifically excluded, so any option including them is wrong."}},{"itemId":"24a09ed4-f03a-5e27-b160-1b5b1eb7b0a4","questionId":"fe8d016e-985f-5a86-8213-0c69378316a6","sourceKey":"bank:INS101:INS-1110","payload":{"prompt":"In marine insurance, the abbreviation \"GA\" stands for","options":["General Assurance","General Average","General Adjustment","Guaranteed Average"],"correctOption":1,"section":"Fire and marine insurance","explanation":"General average is a loss deliberately made to save a ship and its cargo in danger, such as throwing goods overboard, which all the parties who benefit then share. The other expansions sound similar but are not recognised marine insurance terms."}},{"itemId":"50f8010e-01d3-5030-9152-1ce75a12dd07","questionId":"bbc5bc37-6b56-5c5d-8215-02b2f4d00f25","sourceKey":"bank:INS101:INS-1130","payload":{"prompt":"Time policies are mainly associated with which class of insurance?","options":["Motor insurance","Personal accident insurance","Marine hull insurance","Fire insurance"],"correctOption":2,"section":"Fire and marine insurance","explanation":"A time policy covers a ship for a fixed period, often 12 months, which is the normal way ships' hulls are insured. Fire and motor policies also run for a year, but the term 'time policy' is a marine term, used in contrast with a voyage policy."}},{"itemId":"944b3692-28ab-5b4d-a0b4-19c8baf7ec6b","questionId":"2b618479-d2e3-5d42-ac47-7668bfaa3a4a","sourceKey":"bank:INS101:INS-1135","payload":{"prompt":"In marine insurance, the abbreviation \"FPA\" stands for","options":["Fire Perils Added","Fixed Premium Assured","Free of Particular Average","Freight Payable Assured"],"correctOption":2,"section":"Fire and marine insurance","explanation":"Free of particular average means the insurer does not pay for partial losses (particular average) except in specified cases, such as when the ship is stranded, sunk or burnt. The other expansions are not marine insurance terms."}},{"itemId":"6eedd4b3-63be-5e72-9912-921027e5c778","questionId":"c14b43ac-f030-5ca8-8f63-e394361746a1","sourceKey":"bank:INS101:INS-1142","payload":{"prompt":"Which of the following terms is NOT associated with marine insurance?","options":["Salvage","Sue and labour","Jettison","Hit and run"],"correctOption":3,"section":"Fire and marine insurance","explanation":"Hit and run is a motor term, describing a road accident where the driver at fault escapes. Jettison, sue and labour, and salvage are all marine ideas: throwing cargo overboard, the duty to act to reduce loss at sea, and property or reward from saving a ship."}},{"itemId":"dc133c70-773d-55cf-9927-faa9dcd1385e","questionId":"f24eea34-635c-57e7-b958-2c40c1f9d54b","sourceKey":"bank:INS101:INS-1189","payload":{"prompt":"Marine insurance may cover loss or damage to","options":["The ship only","The ship, the cargo and any other subject of the marine adventure","The cargo only","The shipowner's private house on land"],"correctOption":1,"section":"Fire and marine insurance","explanation":"Marine insurance covers the subjects of a marine adventure, mainly the hull, the cargo and the freight earned, so option B is the full answer. Options A and C each name only part of what can be covered, and a private house on land (option D) is property for fire or householder insurance, not marine."}},{"itemId":"86ddd1db-336d-5aec-a0d3-1c173cd80cc5","questionId":"2edf1a8e-46db-5171-87e3-64d31a23a9fb","sourceKey":"bank:INS101:INS-1191","payload":{"prompt":"A marine insurance policy may be issued either for a fixed period, usually a year, or for a particular","options":["Voyage","Claim","Port authority","Crew member"],"correctOption":0,"section":"Fire and marine insurance","explanation":"Marine policies are either time policies, which run for a set period, or voyage policies, which cover a journey from one port to another. Options B, C and D are not ways of setting how long marine cover lasts."}},{"itemId":"d1b8a1d4-8d83-58bf-a20b-d452d2650aab","questionId":"aaf3fcf5-510f-5ea0-9263-7f721abb2e6b","sourceKey":"bank:INS101:INS-1200","payload":{"prompt":"Which class of insurance is most closely linked with overseas trade?","options":["Life insurance","Marine insurance","Fire insurance","Motor insurance"],"correctOption":1,"section":"Fire and marine insurance","explanation":"Marine insurance protects ships, cargo and freight on sea voyages, which is how most overseas trade moves, for example goods coming through Apapa port. Options A, C and D cover lives, buildings and vehicles, not international shipments."}},{"itemId":"301335bd-d0f6-5f96-abfe-e110170c1c40","questionId":"52017291-6cca-5ac0-8c01-00ea4cf8e01d","sourceKey":"bank:INS101:INS-1202","payload":{"prompt":"Which of the following is NOT a subject matter of marine insurance?","options":["The hull of a ship","Cargo on board a ship","A building insured against fire","Freight earned for carrying goods"],"correctOption":2,"section":"Fire and marine insurance","explanation":"A building on land insured against fire falls under fire insurance, not marine. Options A, B and D are the three classic subjects of marine insurance: the ship itself, the goods it carries, and the freight charge earned by the carrier."}},{"itemId":"7660ed65-f6ca-5541-9266-5c520b2901c0","questionId":"21ae79b0-5dcf-5de1-9dc9-e01ab9343431","sourceKey":"bank:INS101:INS-1203","payload":{"prompt":"In marine insurance, the body or frame of a ship together with its machinery is called the","options":["Cargo","Hull","Freight","Voyage"],"correctOption":1,"section":"Fire and marine insurance","explanation":"Hull means the ship itself, including its structure, engines and machinery. Option A is the goods carried, C is the charge for carrying them, and D is the journey, so none of them is the vessel."}},{"itemId":"fb4e5bec-d5dc-5e60-a1c9-7c71b70b2a68","questionId":"3a4dcc7c-e7d2-5c84-9d82-bc3dd3835c0a","sourceKey":"bank:INS101:INS-1204","payload":{"prompt":"In marine insurance, the goods or commodities carried in a ship are called","options":["Hull","Cargo","Freight","Ballast"],"correctOption":1,"section":"Fire and marine insurance","explanation":"Cargo is the goods a ship carries, such as containers of imports arriving in Lagos. Option A is the ship itself, and C is the payment for carrying the goods. Option D is weight added to keep the ship stable, not goods being traded."}},{"itemId":"ab854bbd-f78e-5747-93e7-9130cd9ad373","questionId":"cba0f3d2-67bb-5eb7-bb41-dd9a111e5071","sourceKey":"bank:INS101:INS-1205","payload":{"prompt":"In marine insurance, the charge paid for transporting goods by sea is called","options":["Hull","Cargo","Freight","Premium"],"correctOption":2,"section":"Fire and marine insurance","explanation":"Freight is the payment earned by the shipowner for carrying goods, and it can be insured because it may be lost if the voyage fails. Option A is the ship and B is the goods. Option D is what the insured pays the insurer, not the transport charge."}},{"itemId":"0464a050-45ab-5f20-9769-7e9c31bf36c6","questionId":"332bff24-c425-5681-9cf7-75444f84bdc2","sourceKey":"bank:INS101:INS-1209","payload":{"prompt":"Which marine policy covers the risks to a ship while it is lying in port?","options":["Voyage policy","Cargo policy","Floating policy","Port risk policy"],"correctOption":3,"section":"Fire and marine insurance","explanation":"A port risk policy protects a vessel while it is anchored or berthed in a harbour rather than sailing. Option A covers a ship during a journey between ports. Option B is about goods rather than the ship, and C covers many shipments under one sum insured."}},{"itemId":"2889364c-a9ac-5b1f-badc-30ee3eb70603","questionId":"30e3c546-ee0a-5052-88d5-0ca0ce258604","sourceKey":"bank:INS101:INS-1210","payload":{"prompt":"A marine cargo policy taken out to cover one particular shipment is known as a","options":["Floating policy","Specific (voyage) policy","Open cover","Blanket policy"],"correctOption":1,"section":"Fire and marine insurance","explanation":"A specific policy covers a single named shipment, so a trader buys one each time goods are sent. Options A and C are designed for traders who make many shipments and want continuous cover. Option D covers many items or locations under one sum insured, not a single consignment."}},{"itemId":"071001e9-56b5-556c-aae2-2186ed290e02","questionId":"f3682f85-0bb9-5d30-b731-23ca5a9f7491","sourceKey":"bank:INS101:INS-1212","payload":{"prompt":"Throwing part of a ship's cargo overboard to lighten the vessel in an emergency is called","options":["Barratry","Salvage","Abandonment","Jettison"],"correctOption":3,"section":"Fire and marine insurance","explanation":"Jettison is deliberately throwing cargo overboard to save the ship and the rest of the cargo in an emergency. Option A is wrongful conduct by the master or crew against the owner. Option B is a reward for saving property at sea, and C is handing over damaged property to the insurer."}},{"itemId":"d4dbe138-f32c-572a-8baa-2281970ce79f","questionId":"9f62cb1d-bc12-59c4-9fa5-3b9c8ca69919","sourceKey":"bank:INS101:INS-1215","payload":{"prompt":"Which fire insurance policy covers both the fixed assets and the current assets (like stock) of an insured business under one sum insured?","options":["Declaration policy","Excess policy","Transit policy","Blanket policy"],"correctOption":3,"section":"Fire and marine insurance","explanation":"A blanket policy covers many types of property, such as buildings, machinery and stock, under a single sum insured. A declaration policy (A) is for stock whose value goes up and down, an excess policy (B) covers amounts above a basic policy, and a transit policy (C) covers goods while they are being moved."}},{"itemId":"4ac62aeb-7ce2-5ade-b2e0-c6ff78800de6","questionId":"86fe5875-cf12-5b01-89ce-98dbb278dc5c","sourceKey":"bank:INS101:INS-1237","payload":{"prompt":"A fire policy for a trader whose stock values rise and fall, under which the trader reports stock values regularly and the premium is adjusted, is called a","options":["Valued policy","Blanket policy","Declaration policy","Consequential loss policy"],"correctOption":2,"section":"Fire and marine insurance","explanation":"A declaration policy is designed for fluctuating stocks: the trader declares the stock value at agreed intervals and the final premium is based on those declarations. Option A fixes an agreed value in advance. Option B covers many assets under one sum insured, and D covers lost profits after a fire."}},{"itemId":"9f244692-61bd-5dd1-911d-d32d62bec12c","questionId":"d56b4d84-77d9-5f56-913e-0ee3cb990e09","sourceKey":"bank:INS101:INS-1248","payload":{"prompt":"The policy that covers loss of profit after a fire stops a business from trading normally is known as a consequential loss policy. It is linked to which class of insurance?","options":["Marine insurance","Fire insurance","Life assurance","Motor insurance"],"correctOption":1,"section":"Fire and marine insurance","explanation":"A consequential loss (business interruption) policy pays for profits lost while a business recovers from fire damage, so it works alongside a fire policy. Options A, C and D protect ships and cargo, lives and vehicles, and do not provide this type of profit cover."}},{"itemId":"0c9c702d-c31c-5a2e-a0a0-895b61213544","questionId":"2f2f91dc-ea82-588a-bac5-091965481c4e","sourceKey":"bank:INS101:INS-1260","payload":{"prompt":"Which international set of rules is used for sharing general average losses in marine insurance?","options":["The Hague Rules","The Basel Accords","The Geneva Conventions","The York-Antwerp Rules"],"correctOption":3,"section":"Fire and marine insurance","explanation":"The York-Antwerp Rules set out how general average losses, such as cargo jettisoned to save a ship, are shared between all parties to a voyage. Option A deals with carriers' liability under bills of lading, not general average. Options B and C relate to banking and the laws of war."}},{"itemId":"c73222d9-1603-5a39-b432-1d39b8f08984","questionId":"2662a4b8-6f54-5145-863e-e85c5d8af7d7","sourceKey":"bank:INS101:I101N1-001","payload":{"prompt":"In Hall's (1989) grouping of the special perils that can be added to a fire policy for an extra premium, riot and civil commotion together with malicious damage fall under which group?","options":["Perils of nature","Social perils","Chemical perils","Miscellaneous perils"],"correctOption":1,"section":"Fire and marine insurance","explanation":"Hall (1989) places riot and civil commotion and malicious damage in the social group, because they come from human behaviour in society. Chemical perils are explosion and spontaneous fermentation or heating, while perils of nature cover things like earthquake, flood and storm."}},{"itemId":"3d4a33b2-e2cb-5537-aa07-cb242a53ebc0","questionId":"5e633e47-77dc-5d2f-b44b-57e46c6913f4","sourceKey":"bank:INS101:I101N1-002","payload":{"prompt":"A Lagos exporter is choosing between Institute Cargo Clauses (B) and (C). Which of the following perils is covered under ICC (B) but NOT under ICC (C)?","options":["General average sacrifice","Washing overboard","Jettison","Collision with any external object other than water"],"correctOption":1,"section":"Fire and marine insurance","explanation":"ICC (B) adds lightning, volcanic eruption or earthquake, washing overboard and losses during loading and unloading to the basic named perils of ICC (C). Jettison, general average sacrifice and collision are already in ICC (C), so they are not extra B-only perils."}},{"itemId":"8ee5d3e5-1c45-5982-a551-314fda3c4bdb","questionId":"b1a8c456-d112-5b7d-b860-ffcb43bb13e0","sourceKey":"bank:INS101:INS-0009","payload":{"prompt":"The policy cover for the insured's legal liability towards others as a result of the use of his vehicle is called","options":["Acts Only","Comprehensive Policy","Third Party Only","Third Party, fire & theft"],"correctOption":2,"section":"Motor insurance","explanation":"A Third Party Only motor policy covers the insured's legal liability to other people for death, injury or damage to their property arising from the use of his vehicle. Option A, Acts Only, also deals with liability to others, but it is limited to the bare minimum the law requires, so C is the best answer. Options B and D include third party cover but also protect the insured's own vehicle, so they are wider than what the question describes."}},{"itemId":"35bbc7b6-23f0-51d2-ace3-18786e29c6ed","questionId":"88dd40a7-c87a-5b99-b696-7fab289dfd33","sourceKey":"bank:INS101:INS-0188","payload":{"prompt":"The liberation of the use of motor car came with the passing of locomotive on high ways act of","options":["1897","1896","1889","1885"],"correctOption":1,"section":"Motor insurance","explanation":"The Locomotives on Highways Act 1896 freed the motor car in Britain by raising the speed limit and removing the need for a person to walk in front of it, which opened the way for motoring and later motor insurance. The other years (A, C and D) are not the dates of that Act."}},{"itemId":"9cf4be0c-4a25-50da-895a-e2f8137d528d","questionId":"8874cbb2-34a9-550e-9bc1-1161aad1f2bb","sourceKey":"bank:INS101:INS-0191","payload":{"prompt":"The Road Traffic Act 1930 was amended in what year?","options":["1934","1935","1834","1835"],"correctOption":0,"section":"Motor insurance","explanation":"The Road Traffic Act 1930, which made third party motor insurance compulsory in Britain, was amended by the Road Traffic Act of 1934. Options C and D are a century too early, before motor cars existed, and B is one year off."}},{"itemId":"5794abb3-711b-5e4d-b4f7-d47e5dfd6216","questionId":"5c8ac90c-da1c-5c0e-b3bc-cae80e06c31f","sourceKey":"bank:INS101:INS-0194","payload":{"prompt":"Green card is issue in what continent?","options":["Africa","Europe","Asia","Australia"],"correctOption":1,"section":"Motor insurance","explanation":"The green card is an international motor insurance certificate used mainly in Europe, proving that a vehicle has the compulsory third-party cover required in the countries it is driven into. Africa (A) uses its own schemes such as the ECOWAS Brown Card, and the green card is not an Asian (C) or Australian (D) system."}},{"itemId":"b3a51baf-81e4-51e3-82d6-5f6399edcf18","questionId":"965fbadf-50e8-56b6-a8ae-5492facce5b6","sourceKey":"bank:INS101:INS-0195","payload":{"prompt":"Scope of motor insurance are all except?","options":["private cars","commercial vehicles","motorcycle","none of the above"],"correctOption":3,"section":"Motor insurance","explanation":"Motor insurance covers private cars, commercial vehicles and motorcycles alike, so none of the three listed is outside its scope. That makes 'none of the above' the right choice, and choosing A, B or C would wrongly leave out a vehicle type that motor insurers regularly cover."}},{"itemId":"6f82816b-72a9-5bc8-b880-a3281cda76ba","questionId":"180fd35b-2232-5ce8-9398-d7ba673ed456","sourceKey":"bank:INS101:INS-1132","payload":{"prompt":"Which of the following types of insurance is compulsory for vehicle owners in Nigeria?","options":["Personal accident insurance","Professional indemnity insurance","Motor own damage insurance","Motor third party liability insurance"],"correctOption":3,"section":"Motor insurance","explanation":"Nigerian law requires every vehicle on the road to have at least third party cover, which pays for injury to other people or damage to their property. Own damage cover for your own car is optional, which is why comprehensive motor insurance is a choice rather than a legal requirement."}},{"itemId":"9b084131-f9c0-57cd-96b7-e70094c2dc13","questionId":"0d1b8ee0-c93b-5f01-95ea-95771c4f83e4","sourceKey":"bank:INS101:INS-1186","payload":{"prompt":"Motor insurance can provide cover for","options":["Private cars only","Commercial vehicles only","All of private cars, commercial vehicles and motorcycles","Motorcycles only"],"correctOption":2,"section":"Motor insurance","explanation":"Motor insurance applies to any mechanically propelled vehicle used on the road, whether it is a private car, a commercial bus or truck, or a motorcycle. Options A, B and D each name only one type of vehicle, so each is too narrow."}},{"itemId":"4527180d-c838-5edf-8d11-b98d77ead77c","questionId":"49b10eef-9697-5469-a425-390555d03dab","sourceKey":"bank:INS101:I101N1-003","payload":{"prompt":"The liberation of the use of the motor car came in 1896 with the passing of which Act?","options":["The Workmen's Compensation Act","The Road Traffic Act","The Marine Insurance Act","The Locomotives on Highways Act"],"correctOption":3,"section":"Motor insurance","explanation":"The Locomotives on Highways Act 1896 freed the motor car for use on public roads, which opened the way for motor insurance. The Road Traffic Act is not the 1896 Act that freed the motor car, and the other two Acts deal with marine and employment matters."}},{"itemId":"6ae891ac-7a80-5a04-9f42-2a290f3629f4","questionId":"cb95137f-6f7d-5d4f-ae19-27676c76c0ec","sourceKey":"bank:INS101:I101N1-004","payload":{"prompt":"Which of the following is NOT one of the usual four types of motor insurance cover?","options":["Third party fire and theft","Act only","Hull and machinery","Comprehensive"],"correctOption":2,"section":"Motor insurance","explanation":"The usual four motor covers are Act only, Third party only, Third party fire and theft, and Comprehensive. Hull and machinery is a marine policy for ships and vessels, so it has no place among motor covers."}},{"itemId":"21ca970d-9a45-5354-8e03-bad684d4180d","questionId":"5ce2ddc1-5ea2-507e-bf29-789781849354","sourceKey":"bank:INS101:I101N1-005","payload":{"prompt":"Loss caused by wear and tear of the insured vehicle is excluded under which of the following motor policies?","options":["Third party fire and theft only","Comprehensive only","Third party only","All of the above"],"correctOption":3,"section":"Motor insurance","explanation":"Wear and tear is a gradual, expected loss rather than an accident, so it is excluded under every motor policy, including the widest one. Picking Comprehensive only is tempting because it is the broadest cover, but even comprehensive cover does not pay for wear and tear."}},{"itemId":"7a8d956d-8cb0-5a9b-a74a-e95d433d6e54","questionId":"0537970c-1d2b-50de-a0e7-827d6c291254","sourceKey":"bank:INS101:I101N1-007","payload":{"prompt":"An okada rider in Yaba wants only the minimum motor cover the law requires before he can use his motorcycle on the road. Which cover must he hold?","options":["Personal accident cover","Third party liability cover","Goods in transit cover","Comprehensive cover"],"correctOption":1,"section":"Motor insurance","explanation":"Motor third-party liability is the compulsory cover for vehicle owners in Nigeria, and it pays for his legal liability to other people from using his vehicle. Comprehensive cover is wider and optional, so it is more than the legal minimum."}},{"itemId":"8f5e6011-1f9d-5193-b1e6-d9aa65896f35","questionId":"f3522f90-8c1e-53e0-8c5a-4e38cb2fa432","sourceKey":"bank:INS101:I101N1-008","payload":{"prompt":"Which of the following would NOT be insured under a motor insurance policy?","options":["A private saloon car","An ocean-going fishing trawler","A motorcycle","A commercial delivery van"],"correctOption":1,"section":"Motor insurance","explanation":"Motor insurance covers private cars, commercial vehicles and motorcycles that use the road. A fishing trawler is an ocean-going vessel, which is insured under a marine hull and machinery policy instead."}},{"itemId":"a2f4ea9b-0be0-5dd0-aa7a-9730a87a52ba","questionId":"33ed1e58-c4dc-567a-9f4b-a9ba34fddf19","sourceKey":"bank:INS101:I101N1-009","payload":{"prompt":"A transport company in Oshodi wants to insure its fleet of commercial buses against accidents on the road. Which class of insurance does this belong to?","options":["Fire insurance","Marine hull insurance","Motor insurance","Goods in transit insurance"],"correctOption":2,"section":"Motor insurance","explanation":"Commercial vehicles such as buses fall within the scope of motor insurance, alongside private cars and motorcycles. Goods in transit insurance protects the goods carried by vehicles, not the vehicles themselves, so it does not fit here."}},{"itemId":"3de76125-9a46-5f34-865d-6ca7d96328d3","questionId":"faa0a104-5617-54ae-9a15-51fb3dfd73b3","sourceKey":"bank:INS101:INS-0004","payload":{"prompt":"Group life assurance has a coverage that can be provided for a number of persons under one contract called","options":["General policy","Group policy","Master policy","One policy"],"correctOption":2,"section":"Life assurance","explanation":"Group life cover is issued as a single master policy held by the employer or group organiser, with each covered member usually receiving a certificate of insurance. Option B sounds right in everyday speech, but the technical name of the single contract is the master policy. Options A and D are not insurance terms."}},{"itemId":"ed01df2f-ac70-5a31-913e-6d7e4634aef4","questionId":"0d58868e-3db1-5b53-800b-cdba603bd41e","sourceKey":"bank:INS101:INS-0012","payload":{"prompt":"Life assurance has some unique characteristics that makes it different from other types of insurance and they include all of the following, except","options":["The event insured against is an eventual certainty.","Life assurance is a contract of indemnity","There is no possibility of partial loss in life assurance","The chance of loss under life assurance contract is greater in the second year than in the first year"],"correctOption":1,"section":"Life assurance","explanation":"Life assurance is not a contract of indemnity, because no one can put a money value on a human life; the insurer pays the agreed sum instead. Options A, C and D are genuine features: death is certain, there is no partial loss of life, and the risk of death rises as the life assured gets older. Option C is tempting, but it is a true feature, so it is not the exception."}},{"itemId":"c75e94e3-21b0-5c8b-8423-cf8484b45c70","questionId":"62e0d4f9-8d18-5f7e-8248-71a6c4d8e692","sourceKey":"bank:INS101:INS-0013","payload":{"prompt":"__________provides for the payment of the face amount at the end of a specified term or upon earlier death","options":["Wholelife Insurance","Endowment Insurance","Term Insurance","None of the above"],"correctOption":1,"section":"Life assurance","explanation":"An endowment policy pays the sum assured at the end of a fixed term if the life assured survives, or earlier if they die within the term. Option A, whole life, pays only on death whenever it happens. Option C, term insurance, pays only if death occurs within the term and pays nothing on survival."}},{"itemId":"4d68ab07-72fa-5c45-83ea-0c419a1791c0","questionId":"b6cd8fad-2a98-5587-951b-28b6227ad867","sourceKey":"bank:INS101:INS-0075","payload":{"prompt":"Which of the following has a feature of a non-constant and varying benefits with a level premium?","options":["Level term insurance","decreasing and increasing term insurance","renewable/convertible insurance","none of the above"],"correctOption":1,"section":"Life assurance","explanation":"With decreasing or increasing term insurance, the sum assured goes down or up over the term while the premium usually stays level. Option A, level term, keeps both the sum assured and the premium constant. Option C refers to the right to renew or convert a policy, not to a changing benefit."}},{"itemId":"1e213b9f-e627-5602-a4d8-2f02df0bacfa","questionId":"b9c14a5a-cbb0-5b9f-b475-73ee48f82433","sourceKey":"bank:INS101:INS-0076","payload":{"prompt":"______ policy is without submitting evidence of insurability (health) and the premium for the further period is increased to reflect the increased age of the life insured.","options":["Level term insurance","renewable term","convertible term insurance","a and c"],"correctOption":1,"section":"Life assurance","explanation":"Renewable term insurance lets the policyholder renew the cover at the end of the term without new evidence of health, but the premium is raised to reflect the higher age. Option C, convertible term, allows switching to a permanent policy instead. Option A, level term, simply expires at the end of the term."}},{"itemId":"b9ea3553-8568-5937-89f5-a0c6cc553456","questionId":"1d8258de-ed8e-555d-abab-135c77e31e75","sourceKey":"bank:INS101:INS-0083","payload":{"prompt":"Under this policy, the insurer promises to pay the insured after a period, whether or not the insured survives until the end of the period.","options":["Whole life assurance","variable universal life assurance","endowment life assurance","term assurance"],"correctOption":2,"section":"Life assurance","explanation":"An endowment policy pays out at the end of a set period if the life assured survives, or earlier on death, so a payment is certain either way. Option A, whole life, pays only on death. Option D, term assurance, pays only if death happens within the term and nothing on survival."}},{"itemId":"bd2d7ca3-90f0-56b4-9e4d-94a148ddc025","questionId":"1360d2fd-3e38-558a-8282-6d79cf817820","sourceKey":"bank:INS101:INS-0096","payload":{"prompt":"The fundamental feature of the ______ is that the face amount is paid on death, whenever that occurs, and not before. Such policies therefore may be in existence for many years, even several decades.","options":["Renewable and convertible","endowment insurance","term insurance","none of the above"],"correctOption":3,"section":"Life assurance","explanation":"The policy described pays the face amount on death whenever it happens and can last for decades, which is whole life assurance. Whole life is not listed, so D is correct. Option B, endowment, also pays on survival to the end of the term, and option C, term insurance, pays only if death happens within a fixed period."}},{"itemId":"72868be6-a700-59b5-9943-c46d121091e3","questionId":"23b11bbd-3e17-525f-a5e3-b383d6dc4021","sourceKey":"bank:INS101:INS-0098","payload":{"prompt":"The class of life assurance that is issued to an employer for the benefit of the employee is called.","options":["Group life assurance","individual life assurance","term assurance","variable life assurance"],"correctOption":0,"section":"Life assurance","explanation":"Group life assurance is taken out by an employer under one master policy to cover employees, usually paying a benefit to their dependants on death. Option B, individual life assurance, covers one person under a separate policy. Option D, variable life, is a type of policy whose benefits depend on investment performance."}},{"itemId":"afd41aca-a922-52d5-bb8b-1e7327d5e146","questionId":"0ecb6dde-247a-52ae-a97c-e1c851526c4c","sourceKey":"bank:INS101:INS-0163","payload":{"prompt":"Which of these is strictly an investment policy?","options":["term assurance","whole life","whole life with premium payment stopping at age 65","endowment"],"correctOption":3,"section":"Life assurance","explanation":"An endowment policy pays the sum assured at the end of a fixed term even if the life assured survives, so it works mainly as a savings and investment plan. Term assurance (A) is pure protection with no payout if you survive the term, and whole life policies (B and C) pay only on death."}},{"itemId":"df6587c8-f878-5ad6-a7bd-1e917a0488b6","questionId":"1f9b90df-7aa8-5c1e-b409-a1b33fe94bf5","sourceKey":"bank:INS101:INS-0178","payload":{"prompt":"The development of life Assurance is closely linked with ______ insurance","options":["Fire insurance","Motor insurance","Accident insurance","Marine insurance"],"correctOption":3,"section":"Life assurance","explanation":"Early life assurance grew out of marine insurance, as marine underwriters began covering the lives of ship captains and merchants who travelled with their cargo. Fire (A), motor (B) and accident (C) insurance developed separately and later."}},{"itemId":"0504d77f-e9e3-5395-bcd5-0dad71b27fce","questionId":"07f1078a-8ba1-5e8e-aba1-39404ead0d72","sourceKey":"bank:INS101:INS-0409","payload":{"prompt":"Liability insurance protects against:","options":["Insured's own asset damage","Claims for harm to others","Personal health expenses","Income disruption"],"correctOption":1,"section":"Life assurance","explanation":"Liability insurance protects the insured against legal claims from other people for injury or damage he causes them. Option A is covered by property insurance. Options C and D are covered by health and income protection policies."}},{"itemId":"a1650fa2-7b80-5d8c-8cc9-ee58f05ea520","questionId":"4d758be1-ed98-5a6c-8a08-528438574ee4","sourceKey":"bank:INS101:INS-0844","payload":{"prompt":"Fidelity guarantee policies cover losses due to fraud by ____","options":["Employees","Customers","Borrowers","Suppliers"],"correctOption":0,"section":"Life assurance","explanation":"Fidelity guarantee insurance protects an employer against loss of money or goods caused by the fraud or dishonesty of its own employees. Options B, C and D are outsiders whose dishonesty is not covered under this class of insurance."}},{"itemId":"da68cee3-e177-516e-9b4b-48725c73df25","questionId":"0827a807-d7ef-5650-9f40-43ffaf75074a","sourceKey":"bank:INS101:INS-0861","payload":{"prompt":"Which of the following terms matches closest with 'asbestosis'?","options":["Products","Pension","Workmen's compensation","Long term policies"],"correctOption":2,"section":"Life assurance","explanation":"Asbestosis is a lung disease workers get from breathing in asbestos dust at work, so it is a classic occupational disease claim under workmen's compensation (employer's liability) insurance. Option A, products, relates to harm caused by goods sold to the public, and options B and D have nothing to do with injury at work."}},{"itemId":"e08d0241-a420-5aa3-8e2b-57cd525b5d17","questionId":"0a37a56a-66f9-5fd9-92c9-0e4db989437f","sourceKey":"bank:INS101:INS-1113","payload":{"prompt":"A life policy for which the policyholder pays the whole premium in one lump sum at the start is known as a","options":["single premium policy","money-back policy","half-yearly premium policy","annual premium policy"],"correctOption":0,"section":"Life assurance","explanation":"A single premium policy is paid for with one payment at the start, after which no further premiums are due. Annual (option D) and half-yearly (option C) premium policies both involve regular payments over the term of the policy."}},{"itemId":"b2eebdaf-f5ea-5754-bb28-183f66fb7fa0","questionId":"61671e42-405a-5156-a448-3cd2000b33e8","sourceKey":"bank:INS101:INS-1118","payload":{"prompt":"For a person of the same age and the same sum assured, the premium for an endowment policy compared with a whole life policy will be","options":["higher","the same","exactly half","lower"],"correctOption":0,"section":"Life assurance","explanation":"An endowment policy is certain to pay out within a fixed term, either on death or at maturity, while whole life pays only on death, which may be many years away. Because the insurer pays sooner and more surely under an endowment, its premium is higher."}},{"itemId":"cd468bf3-eab0-5a87-b803-39b9daf952aa","questionId":"5dfe30e8-b6d8-57e2-b71c-a7d2bd8b64c4","sourceKey":"bank:INS101:INS-1122","payload":{"prompt":"In life assurance, the abbreviation \"SV\" commonly stands for","options":["Selected Value","Survivor Value","Summary Valuation","Surrender Value"],"correctOption":3,"section":"Life assurance","explanation":"The surrender value is the cash the insurer pays when a policyholder ends a life policy early, before maturity or death. The other expansions are not recognised life assurance terms."}},{"itemId":"87740f0f-c217-57fd-9740-e43d82bf7b1c","questionId":"fd9cf7bc-1ced-58f4-bfea-51a478cf9758","sourceKey":"bank:INS101:INS-1185","payload":{"prompt":"Human life is the subject matter of which class of insurance contract?","options":["Fire insurance","Life assurance","Marine insurance","Motor insurance"],"correctOption":1,"section":"Life assurance","explanation":"Life assurance covers the risk of death or survival of a person, so the human life itself is the subject matter. Option A covers buildings and contents, C covers ships and cargo, and D covers vehicles and liability from using them."}},{"itemId":"c85aeaec-9194-57f1-8f02-fa259cd425ff","questionId":"e4a2ab36-d88c-54d8-a8ec-5adc832d2d79","sourceKey":"bank:INS101:INS-1194","payload":{"prompt":"Which of the following is a benefit of life insurance?","options":["Encouraging saving and investment only","Improving creditworthiness only","All of encouraging saving and investment, improving creditworthiness and possible tax relief","Possible tax relief only"],"correctOption":2,"section":"Life assurance","explanation":"Life insurance gives several benefits together: premiums build up savings that insurers invest, a policy can be used as security for a loan, and life premiums can qualify for tax relief. Options A, B and D each name only one of these benefits, so each is incomplete."}},{"itemId":"d6c1d21e-4e9e-5013-b83b-39f5a0b16247","questionId":"41c91aa5-4598-54e7-b502-37097b220f36","sourceKey":"bank:INS101:INS-1197","payload":{"prompt":"When a life policyholder voluntarily ends the contract before maturity and collects a cash value, this is called","options":["Maturity","Surrender","Lapse","Endorsement"],"correctOption":1,"section":"Life assurance","explanation":"Surrender is the policyholder choosing to cancel a life policy early and receive its surrender value. Option A is when the policy reaches its end date and pays out normally. Option C happens when premiums stop and the policy dies, not by a deliberate cash-in decision, and D is a written change to a policy."}},{"itemId":"381aade8-0798-520e-a7d4-1a763c939002","questionId":"bf73e2ce-3b90-56ef-b280-4c0769877fdd","sourceKey":"bank:INS101:INS-1235","payload":{"prompt":"A life policy that covers two or more people under one contract, such as a husband and wife, is called a","options":["Single life policy","Level premium policy","Annuity","Joint (multiple) life policy"],"correctOption":3,"section":"Life assurance","explanation":"A joint or multiple life policy insures more than one life under a single contract, usually paying when the first of them dies. Option A covers only one person. Option B describes how premiums are paid, not how many lives are covered, and C pays a regular income rather than covering several lives."}},{"itemId":"8de700fe-2aff-5fa0-9d30-061ffcac941b","questionId":"76533afa-991a-5ea9-aa33-207ca48d89cd","sourceKey":"bank:INS101:INS-1238","payload":{"prompt":"The word 'assurance' is traditionally used for which class of business?","options":["Fire business","Motor business","Life business","Marine business"],"correctOption":2,"section":"Life assurance","explanation":"Assurance is used for life business because death is certain to happen, so the policy assures a payment at some point. Options A, B and D cover events that may never occur, so they are called insurance."}},{"itemId":"6a640158-54b3-574b-a1cf-63dd0478dffc","questionId":"7cd0da36-55b3-5c63-839d-93cdb067e7be","sourceKey":"bank:INS101:INS-1262","payload":{"prompt":"Extra benefits added to a life policy, such as accident or critical illness cover, for an additional premium are called","options":["Loans","Endorsements","Exclusions","Riders"],"correctOption":3,"section":"Life assurance","explanation":"Riders are optional add-ons that extend the benefits of a basic life policy. Option A is borrowing against a policy, not extra cover. Option C removes cover rather than adding it, and B is a general written change to a policy."}},{"itemId":"1489ce75-fd78-5a05-a3cb-d73e053dddba","questionId":"f40f8685-bb48-524a-8bd1-bc5dc4671494","sourceKey":"bank:INS101:INS-1270","payload":{"prompt":"A person named to receive the benefit under an insurance contract, such as the sum assured on death, is called the","options":["Beneficiary","Annuitant","Insurer","Underwriter"],"correctOption":0,"section":"Life assurance","explanation":"The beneficiary is the person entitled to receive the policy money, often a spouse or child named in a life policy. Option B is someone who receives a regular annuity income. Options C and D are on the insurance company side and pay rather than receive benefits."}},{"itemId":"8edd7d25-e368-5023-a737-27782d1f8425","questionId":"e62384e8-e01e-5731-af5e-e80625f541b1","sourceKey":"bank:INS101:INS-1284","payload":{"prompt":"Life policies where part of the premium pays for life cover and the rest is invested in investment funds chosen by the policyholder are called","options":["Unit-linked policies","Double insurance","Endowment-free policies","Term-only policies"],"correctOption":0,"section":"Life assurance","explanation":"Unit-linked policies combine protection and investment: part of each premium buys life cover and the rest buys units in investment funds. Option B means insuring the same property with several insurers. Option D gives life cover only, with no investment part."}},{"itemId":"06b54b04-2540-5d28-9040-6c7991df445d","questionId":"0ba44e1f-8dca-5495-a640-20b114f64663","sourceKey":"bank:INS101:I101N1-010","payload":{"prompt":"A term assurance policy that the policyholder can switch into another type of policy is called a","options":["Convertible term policy","Decreasing term policy","Renewable term policy","Level term policy"],"correctOption":0,"section":"Life assurance","explanation":"A convertible term policy gives the right to change it into another policy. A renewable term policy is different: it lets cover continue for a further period without fresh evidence of health, but it does not change the type of policy."}},{"itemId":"e24090d8-a8bd-535c-a69e-c55cf0f05fa7","questionId":"b202c751-65c4-5149-81b0-19b5e535e5e9","sourceKey":"bank:INS101:I101N1-011","payload":{"prompt":"A term assurance under which the benefit stays the same throughout the term is known as","options":["Level term assurance","Decreasing term assurance","Convertible term assurance","Increasing term assurance"],"correctOption":0,"section":"Life assurance","explanation":"Level term assurance keeps a constant benefit for the whole term. Decreasing and increasing term policies have a varying benefit with a level premium, so the sum assured does not stay fixed."}},{"itemId":"565501af-6d50-5bb2-a82a-d8e5c6a42acc","questionId":"a8ac8c71-a52a-517a-9ce2-77220101fb42","sourceKey":"bank:INS101:I101N1-012","payload":{"prompt":"A mortgage redemption policy, which repays an outstanding home loan if the borrower dies, is a form of","options":["Endowment assurance","Level term assurance","Decreasing term assurance","Whole life assurance"],"correctOption":2,"section":"Life assurance","explanation":"As the loan is repaid, the amount still owed falls, so the cover falls with it, which is decreasing term assurance. Level term keeps the same benefit throughout, which would not match a shrinking loan balance."}},{"itemId":"ffe02a00-f406-5606-9aab-31f398a2c644","questionId":"76220741-22b5-58f8-b59c-ffdefb13cc7b","sourceKey":"bank:INS101:I101N1-013","payload":{"prompt":"Mrs. Adeyemi, a trader in Balogun market, wants life cover only for a temporary need, with the cover reducing over the period. Which policy is particularly suited to her?","options":["Decreasing term assurance","Unit-linked policy","Whole life assurance","Endowment assurance"],"correctOption":0,"section":"Life assurance","explanation":"Decreasing term assurance is particularly suited to temporary needs, giving cover for a set period with a reducing benefit. Endowment and whole life are long-term policies with a savings or lifetime element, so they are more than a temporary need requires."}},{"itemId":"8415688d-fe1f-5cdd-856a-9470ab2efb83","questionId":"c3aa7644-440e-5092-ba89-15a526451fd8","sourceKey":"bank:INS101:I101N1-014","payload":{"prompt":"Under which type of life policy is the face amount paid on the death of the life assured, whenever that death occurs?","options":["Annuity","Endowment assurance","Whole life assurance","Term assurance"],"correctOption":2,"section":"Life assurance","explanation":"Whole life assurance pays the face amount on death, whenever it happens, with no fixed end date. Term assurance pays only if death occurs within the set term, so a death after the term would not be paid."}},{"itemId":"89d53ea8-ff83-5fca-b9e5-2705105033d5","questionId":"0618a6f3-3638-5605-a1cd-1416a5184293","sourceKey":"bank:INS101:I101N1-015","payload":{"prompt":"One feature that makes life assurance different from other classes of insurance is that the event insured against is","options":["A purely partial loss","A fundamental risk","An eventual certainty","A speculative risk"],"correctOption":2,"section":"Life assurance","explanation":"Everyone will die at some point, so the insured event in life assurance is certain to happen; only its timing is uncertain. A partial loss is the opposite of what happens in life assurance, where there is no partial loss."}},{"itemId":"e3fbbe39-907e-59f7-99c8-57cf0e42989b","questionId":"16b1deda-f564-5709-93a8-ef5ab00b277a","sourceKey":"bank:INS101:I101N1-016","payload":{"prompt":"Which statement about the chance of loss in life assurance is correct?","options":["The chance of loss rises each year as the life assured gets older","The chance of loss stays the same every year","The chance of loss is zero once premiums are paid","The chance of loss falls each year after the policy starts"],"correctOption":0,"section":"Life assurance","explanation":"The risk of death increases with age, so the chance of a claim in life assurance rises each year. Saying it stays the same every year ignores the effect of ageing, which is exactly why life assurance is treated differently."}},{"itemId":"b82239f7-d34c-511f-8620-2a7b76489389","questionId":"9ce27bff-e8f9-56aa-adab-23e94ba5c68f","sourceKey":"bank:INS101:I101N1-017","payload":{"prompt":"Why is there no partial loss in life assurance, unlike in fire or motor insurance?","options":["The life assured can recover part of the loss from a third party","Death is a total event, so the full sum assured becomes payable","The insurer always pays half the sum assured","Life policies are contracts of indemnity"],"correctOption":1,"section":"Life assurance","explanation":"A life cannot be partly lost, so when death occurs the whole sum assured is paid; there is no partial loss. Calling life policies contracts of indemnity is wrong, because life assurance is not a contract of indemnity."}},{"itemId":"bf189062-c3d7-50ce-b1fa-b251ae788ec2","questionId":"b2d4bde9-8b78-57fe-b99f-dcbff1babe5c","sourceKey":"bank:INS101:I101N1-018","payload":{"prompt":"Where the risk insured is loss of life, the person seeking protection is usually called the","options":["Beneficiary","Assured","Underwriter","Insurer"],"correctOption":1,"section":"Life assurance","explanation":"For life risks, the insured is called the assured, which matches the use of the word assurance for life business. The beneficiary is the person named to receive the benefit, who is not necessarily the person seeking protection."}},{"itemId":"6504b78d-2d5d-510c-9dcc-e7cecab146f8","questionId":"dde0a3ac-4aa6-5e98-b1fc-80bffb03b522","sourceKey":"bank:INS101:I101N1-019","payload":{"prompt":"One condition of an insurable risk is that the loss must be determinable and measurable, definite as to cause, time, place and amount. Which of these meets this condition easily?","options":["Rare artwork","A family heirloom","The goodwill of a new business","Life insurance"],"correctOption":3,"section":"Life assurance","explanation":"A death is definite as to cause, time, place and amount, so life insurance meets the determinable loss condition easily. Rare artwork is the classic example that does not, because its value is hard to measure."}},{"itemId":"0ba7e488-10e9-5bc5-8444-589b81ce5da6","questionId":"307f134b-a69a-5524-8eda-dd523ee523f5","sourceKey":"bank:INS101:I101N1-020","payload":{"prompt":"Who wrote the first life table in 1693, a key step in the development of life assurance?","options":["Edward Rowe Mores","William Talbot","James Dodson","Edmund Halley"],"correctOption":3,"section":"Life assurance","explanation":"Edmund Halley wrote the first life table in 1693. James Dodson was the man refused by the Amicable because of his age, while William Talbot co-founded the Amicable Society in 1706."}},{"itemId":"9feeaeb2-ee52-5a29-a167-3d69ebd34762","questionId":"67c0433e-aa89-5e37-b4bc-73bf6555e19b","sourceKey":"bank:INS101:I101N1-021","payload":{"prompt":"The Society for Equitable Assurances on Lives and Survivorship (1762) gave its chief official a title that is still used in insurance today. What was the title?","options":["Registrar","Loss adjuster","Actuary","Underwriter"],"correctOption":2,"section":"Life assurance","explanation":"The Equitable, founded in 1762, called its chief official the actuary, a title now used for the expert who works out risks and rates. An underwriter is the person who accepts or declines risks, which is a different role."}},{"itemId":"17ec6c31-7feb-5f50-a3bb-dbca01ddaa69","questionId":"f3c417df-be24-543d-a940-ae510db5d5bd","sourceKey":"bank:INS101:I101N1-022","payload":{"prompt":"Mr. Okafor takes out a life policy that will pay him the sum assured if he is still alive at the end of 20 years, or pay his family earlier if he dies before then. Which policy is this?","options":["Endowment assurance","Convertible term assurance","Whole life assurance","Level term assurance"],"correctOption":0,"section":"Life assurance","explanation":"An endowment pays the face amount at the end of a set term or on earlier death, so it pays whether or not he survives. Whole life pays only on death, so Mr. Okafor would never receive the money himself while alive."}},{"itemId":"df359b59-d49d-510c-b843-e49d7d6adc5c","questionId":"19976dee-2877-5ca5-8cab-ad39d322f3e9","sourceKey":"bank:INS101:I101N1-023","payload":{"prompt":"The holder of a term assurance in Lagos wants to continue cover for a further period without undergoing another medical examination, accepting a higher premium for his older age. Which policy allows this?","options":["Convertible term policy","Renewable term policy","Level term policy","Endowment policy"],"correctOption":1,"section":"Life assurance","explanation":"A renewable term policy is renewed without fresh evidence of insurability, with the premium rising to reflect age. A convertible term policy lets the holder switch to another type of policy, which is not what he wants here."}},{"itemId":"6cc87fae-f858-55c4-80e0-561214d4da7c","questionId":"e0115b2f-1e8e-55d0-9624-d37b205277aa","sourceKey":"bank:INS101:I101N1-024","payload":{"prompt":"A firm in Ikeja arranges life cover for all its employees under one contract with an insurer. The single contract covering the whole group is called a","options":["Floating policy","Certificate of insurance","Proposal form","Master policy"],"correctOption":3,"section":"Life assurance","explanation":"Group life assurance is written under a master policy, one contract that covers many employees. A floating policy is a marine cargo policy for regular shippers, not a group life contract."}},{"itemId":"761d0784-3514-594f-bfa6-9bbd5b2884a1","questionId":"9b461225-101c-5a84-a190-a69c8eef1a31","sourceKey":"bank:INS101:INS-0297","payload":{"prompt":"In insurance, \"defective products\" is an example of which loss exposure?","options":["Property loss exposure","Human resource loss exposure","Crime loss exposure","Liability loss exposure"],"correctOption":3,"section":"Liability and accident insurance","explanation":"A firm that sells defective products can be sued by people injured by them, so the exposure is to legal liability to others. Option A, property loss exposure, concerns damage to the firm's own assets. Options B and C cover loss of key people and losses from theft or fraud, which is not what product defects create."}},{"itemId":"015d87c8-99c1-5469-ab69-e6030422cfcd","questionId":"c9d3f70a-640d-5f30-8ec4-4b994330d5f3","sourceKey":"bank:INS101:INS-0343","payload":{"prompt":"A contractual indemnity policy provides protection against the legal liability of an employer in relation to bodily injury or disease sustained by any person under his/her employment or apprenticeship.","options":["True","True, but only for apprentices","False","True, but only for diseases, not injuries"],"correctOption":2,"section":"Liability and accident insurance","explanation":"Cover for an employer's legal liability for injury or disease suffered by employees or apprentices at work is employer's liability insurance, not a contractual indemnity policy. A contractual liability cover deals with liability taken on under a contract. Options B and D, which accept the statement in part, are wrong for the same reason."}},{"itemId":"6bea3dfd-034b-5281-9e50-a265db801bdf","questionId":"25c23b96-2b4a-558b-a8e2-7532a500bd02","sourceKey":"bank:INS101:INS-0410","payload":{"prompt":"Group social and pension insurance provides:","options":["Individual medical plans","Retirement and welfare benefits","Property risk safeguards","Sea voyage protections"],"correctOption":1,"section":"Liability and accident insurance","explanation":"Group, social and pension insurance provide benefits such as pensions and welfare payments for members of a group, often employees. Option A is wrong because these schemes cover groups, not single persons. Options C and D belong to property and marine insurance."}},{"itemId":"9221fd12-e31f-5555-baec-53f57c5e3158","questionId":"05196780-c4ea-5053-91a5-2f9402a8b4a4","sourceKey":"bank:INS101:INS-0478","payload":{"prompt":"Insurers offer group insurance to","options":["A group formed for other purposes other than insurance","A group formed solely for the purpose of obtaining group insurance.","All of the above.","None of the above"],"correctOption":0,"section":"Liability and accident insurance","explanation":"Group insurance is offered to groups that exist for some other purpose, such as employees of a company or members of an association. Insurers avoid groups formed just to buy insurance (option B), because such groups attract mainly people expecting to claim, which is adverse selection."}},{"itemId":"1f11e4bc-104f-507c-b420-2cd59d27cd73","questionId":"d84da6eb-27db-53a5-aaab-7b6816684838","sourceKey":"bank:INS101:INS-1137","payload":{"prompt":"Which of the following would most typically buy professional indemnity insurance?","options":["A car owner insuring a private car","A homeowner insuring the building","A practising surgeon","A supermarket insuring its stock"],"correctOption":2,"section":"Liability and accident insurance","explanation":"Professional indemnity insurance protects professionals against claims that their negligent advice or service caused loss or injury, and a surgeon faces exactly that kind of claim. A supermarket would insure its stock under property cover, and a car owner needs motor insurance rather than professional indemnity."}},{"itemId":"11f737b0-68d4-524a-b234-09297dfb9d3b","questionId":"99de4759-b502-5be5-a5e7-e357f7302954","sourceKey":"bank:INS101:INS-1228","payload":{"prompt":"An unexpected and unplanned mishap that nobody intended is called","options":["A premium","A hazard","An endorsement","An accident"],"correctOption":3,"section":"Liability and accident insurance","explanation":"An accident is a sudden, unforeseen event that was not designed or expected, such as a car crash. Option B is a condition that makes a loss more likely, not the event itself. Option A is the price of insurance, and C is a change to a policy."}},{"itemId":"45e2d9f5-1feb-5277-ab10-31e9eac3f9cc","questionId":"c8ad9512-480b-580d-bbd7-3203ab3c1a95","sourceKey":"bank:INS101:INS-1273","payload":{"prompt":"Which insurance protects against loss from accidental bodily injury?","options":["Personal accident insurance","Property insurance","Marine insurance","Fire insurance"],"correctOption":0,"section":"Liability and accident insurance","explanation":"Personal accident insurance pays benefits when the insured is injured, disabled or killed by an accident. Options B, C and D protect physical property such as buildings, goods and ships rather than the human body."}},{"itemId":"eeb123da-84ff-59f2-a0c6-0e879f8f542c","questionId":"af04ef25-d286-5955-beb3-aea9ff718b0e","sourceKey":"bank:INS101:I101N1-025","payload":{"prompt":"If an insured is found legally liable, a liability policy will typically pay","options":["Only the damages awarded","Only the legal fees","Both the legal fees and the damages awarded","Only fines imposed by a court"],"correctOption":2,"section":"Liability and accident insurance","explanation":"Liability insurance covers legal fees plus damages if the insured is found liable. Paying only the legal fees or only the damages would leave half of the insured's liability exposure uncovered."}},{"itemId":"345a9e3f-b6df-5e10-8381-de5702d8ee3f","questionId":"a67e575c-bb00-5091-9f4d-df7c2a9c16ca","sourceKey":"bank:INS101:I101N1-026","payload":{"prompt":"Which of the following is generally NOT covered under liability insurance?","options":["Legal fees in defending a claim","Damages for injury to third parties","Wilful acts of the insured","Damages for damage to third-party property"],"correctOption":2,"section":"Liability and accident insurance","explanation":"Liability insurance does not cover wilful acts or contractual liability, because cover is for accidental legal liability. Legal fees and damages for third-party injury or property damage are exactly what the policy is designed to pay."}},{"itemId":"04812c04-7fe3-5a66-bded-1e7ea8078261","questionId":"e929407a-bf7c-5bf0-990c-1ee432a5908c","sourceKey":"bank:INS101:I101N1-027","payload":{"prompt":"How many main classes of liability insurance are usually identified?","options":["Four","Three","Five","Seven"],"correctOption":2,"section":"Liability and accident insurance","explanation":"The five main classes are public, products, professional indemnity, employers' and directors' and officers' liability. Four is tempting if one class is forgotten, but all five are separate classes."}},{"itemId":"cda3bb33-23be-5a49-ba75-9d275e032fb1","questionId":"12d8e769-aea0-54e2-95a5-b1848d29b2bc","sourceKey":"bank:INS101:I101N1-028","payload":{"prompt":"Which of the following is NOT one of the five main classes of liability insurance?","options":["Products liability insurance","Public liability insurance","Directors' and officers' liability insurance","Fidelity guarantee insurance"],"correctOption":3,"section":"Liability and accident insurance","explanation":"The five main liability classes are public, products, professional indemnity, employers' and directors' and officers'. Fidelity guarantee is a different kind of cover and is not one of these five liability classes."}},{"itemId":"f261f15f-02a3-599a-83c8-342aa4897ae5","questionId":"d5b51eb6-d241-5517-b815-a890d5a29a9a","sourceKey":"bank:INS101:I101N1-029","payload":{"prompt":"A customer slips on a wet floor in a supermarket in Surulere and sues the business for her injuries. Which insurance covers the supermarket's legal liability?","options":["Public liability insurance","Employers' liability insurance","Products liability insurance","Personal accident insurance"],"correctOption":0,"section":"Liability and accident insurance","explanation":"Public liability covers legal claims for injury to third parties or damage to their property arising from the business, and a customer is a third party. Employers' liability is only for injury to the business's own employees, so it does not apply to a customer."}},{"itemId":"eecac974-874a-59d2-9bae-5f34f2cbe144","questionId":"96505624-b262-54c3-93df-b1f722cefbcd","sourceKey":"bank:INS101:I101N1-030","payload":{"prompt":"A table-water company in Ikeja sells a contaminated batch that makes several consumers ill. Which insurance covers its liability to the consumers?","options":["Public liability insurance","Employers' liability insurance","Products liability insurance","Professional indemnity insurance"],"correctOption":2,"section":"Liability and accident insurance","explanation":"Products liability covers injury or damage caused to third parties by a defective product, which is what happened here. Public liability is about injury arising from the business premises or activities generally, not specifically from a defective product sold."}},{"itemId":"5bf93df2-2916-5a70-b05b-b8d51bae627e","questionId":"136b446a-9905-5909-975a-067ecda33028","sourceKey":"bank:INS101:I101N1-031","payload":{"prompt":"Products liability insurance carries two major exclusions. One of them is","options":["Services rendered under the influence of intoxicants or narcotics","Legal costs of defending a defective product claim","Damage to a buyer's property caused by a faulty product","Injury to a consumer caused by a defective product"],"correctOption":0,"section":"Liability and accident insurance","explanation":"Products liability excludes services rendered under the influence of intoxicants or narcotics, as well as criminal acts or breach of law. Injury and damage caused by a defective product are what the policy is meant to cover, so they are not exclusions."}},{"itemId":"ce56e585-f9a9-5acc-ac20-79ddf95d0bec","questionId":"e8f312ac-1107-5249-8a18-b247d057b4b6","sourceKey":"bank:INS101:I101N1-032","payload":{"prompt":"To succeed in a claim covered by professional indemnity insurance, what must the claimant show?","options":["That the professional was an employee under a contract of service","That the professional made a profit from the client","That the professional failed to use the reasonable care and skill expected of the occupation","That the professional's product was defective"],"correctOption":2,"section":"Liability and accident insurance","explanation":"Professional indemnity responds when the claimant shows a failure to use the reasonable care and skill expected of that occupation. A defective product points to products liability, which is a different class."}},{"itemId":"7067c79b-cc87-5cd5-a43e-61791dad1ace","questionId":"1425d470-d823-58ea-b0c0-2d523d1a2fc7","sourceKey":"bank:INS101:I101N1-033","payload":{"prompt":"An architect in Victoria Island is sued by a client because a building he designed developed cracks due to his negligent design. Which policy covers him?","options":["Directors' and officers' liability insurance","Public liability insurance","Products liability insurance","Professional indemnity insurance"],"correctOption":3,"section":"Liability and accident insurance","explanation":"Professional indemnity covers professionals such as architects, doctors, lawyers and engineers for advice, negligence or recklessness in their work. Products liability is for defective products sold, not for faulty professional advice or design."}},{"itemId":"f5ceb45a-4d37-5137-aca7-9bb3c4d5ae7f","questionId":"b0833182-fc7c-588a-9ca1-aea57c8d1a4b","sourceKey":"bank:INS101:I101N1-034","payload":{"prompt":"Professional indemnity insurance will NOT respond to which of these claims?","options":["Claims for failure to use reasonable care and skill","Claims by clients against a lawyer for recklessness","Claims for negligent professional advice","Claims made before inception that were not included in the policy"],"correctOption":3,"section":"Liability and accident insurance","explanation":"Professional indemnity excludes claims made before inception that were not included, and claims better covered elsewhere, such as employers' liability. Claims for negligent advice or lack of reasonable care are the core of what the policy covers."}},{"itemId":"b2181e2b-c1a1-5988-8d05-d24b514fba14","questionId":"3b5bd41d-226b-5a67-a72b-7f5dfa94f234","sourceKey":"bank:INS101:I101N1-035","payload":{"prompt":"Shareholders of a Lagos bank sue its directors over a decision made in the course of duty that breached Nigerian regulations. Which policy protects the directors?","options":["Employers' liability insurance","Professional indemnity insurance","Directors' and officers' liability insurance","Public liability insurance"],"correctOption":2,"section":"Liability and accident insurance","explanation":"D&O insurance covers directors and key officers sued over decisions made in duty that breach Nigerian laws and regulations, including claims by shareholders. Professional indemnity is for professionals such as doctors and lawyers advising clients, not company directors acting for the board."}},{"itemId":"e8c2f861-9655-53a9-ad1d-9c504b27636a","questionId":"87570f67-d004-5d85-8342-aa0fbd76edb9","sourceKey":"bank:INS101:I101N1-036","payload":{"prompt":"A D&O policy bought for the directors of a firm in Ikeja will NOT pay for","options":["Fines and punitive measures","Claims brought by shareholders","Indemnity to the officer's estate on insolvency","Costs of prosecution, examinations and inquiries"],"correctOption":0,"section":"Liability and accident insurance","explanation":"D&O policies exclude fines and punitive measures, along with intentional, shady or criminal acts. Claims by shareholders and the costs of inquiries are things the policy covers, so they cannot be the exclusion."}},{"itemId":"2d01e75d-6e61-588b-a1b4-d9863a1821b0","questionId":"5bdb8441-50f8-599a-bd13-635c9f3a1455","sourceKey":"bank:INS101:I101N1-037","payload":{"prompt":"Which item falls within the cover given by a directors' and officers' (D&O) liability policy?","options":["Pollution","Events before inception","Death, disease or injury to persons","Costs of prosecution, examinations and inquiries"],"correctOption":3,"section":"Liability and accident insurance","explanation":"D&O cover includes the costs of prosecution, examinations and inquiries, as well as claims by shareholders. Pollution, injury to persons and events before inception are all listed exclusions of the policy."}},{"itemId":"7c40edcc-8183-51ce-8f92-24b3d6b3bfd0","questionId":"9b4f6e4a-6334-5b11-b9e6-41756ba09303","sourceKey":"bank:INS101:I101N1-038","payload":{"prompt":"A machine operator at a factory in Agbara is injured while working. Which policy covers the amount the factory must legally pay him?","options":["Public liability insurance","Products liability insurance","Professional indemnity insurance","Employers' liability insurance"],"correctOption":3,"section":"Liability and accident insurance","explanation":"Employers' liability covers what the employer must legally pay for employees' injury, illness, disease or death in the course of the business. Public liability is for injury to third parties such as customers and visitors, not the firm's own workers."}},{"itemId":"0c5248dd-e566-5b25-bc77-74d4d4c0c09e","questionId":"15b38bd4-3e46-5d1b-80ba-34372484f33d","sourceKey":"bank:INS101:I101N1-039","payload":{"prompt":"For employers' liability insurance, an \"employee\" basically means a person working under a contract of","options":["Indemnity","Agency","Sale of goods","Service or apprenticeship"],"correctOption":3,"section":"Liability and accident insurance","explanation":"An employee is someone under a contract of service or apprenticeship, and the meaning is extended to include persons such as an intern or a person hired for a job. A contract of indemnity is the insurance contract itself, not the employment relationship."}},{"itemId":"ae955f82-473e-5edd-9658-aec052c70dae","questionId":"1c4d805a-38c9-55f9-b103-fce8306ccfa4","sourceKey":"bank:INS101:I101N1-041","payload":{"prompt":"Which Nigerian law is cited as governing compensation under employers' liability insurance?","options":["Insurance Decree No. 59 of 1976","Insurance (Miscellaneous Provisions) Act 1964","National Insurance Commission Act 1997","Workmen's Compensation Decree No. 17 of 1987"],"correctOption":3,"section":"Liability and accident insurance","explanation":"Compensation for injured workers is cited under the Workmen's Compensation Decree No. 17 of 1987. Insurance Decree No. 59 of 1976 dealt with regulating insurers and their minimum capital, not workers' compensation."}},{"itemId":"a301bdb6-83a9-5fc5-8f26-7bd5c5ea617e","questionId":"14d3a7ec-aeba-52f2-9c3f-af5af1015f65","sourceKey":"bank:INS101:I101N1-042","payload":{"prompt":"Under the Workmen's Compensation Decree No. 17 of 1987, compensation for the death of an employee is","options":["54 months' earnings","42 months' earnings","100 months' earnings","24 months' earnings"],"correctOption":1,"section":"Liability and accident insurance","explanation":"Death compensation is 42 months' earnings. The 54 months figure is for permanent disability, which is the easiest one to mix up with death."}},{"itemId":"8a83373f-d91e-5058-ad1c-7c0140a31a47","questionId":"29c92f5a-1ee1-50a9-a466-1a363e99b209","sourceKey":"bank:INS101:I101N1-043","payload":{"prompt":"How many months' earnings are payable for permanent disability under the Workmen's Compensation Decree No. 17 of 1987?","options":["104 months' earnings","42 months' earnings","54 months' earnings","36 months' earnings"],"correctOption":2,"section":"Liability and accident insurance","explanation":"Permanent disability attracts 54 months' earnings. The 42 months figure applies to death, not permanent disability."}},{"itemId":"b2879d61-b7e8-5703-b573-84ca550dff4f","questionId":"1282daa4-1489-52c6-93ca-24cd83e78f45","sourceKey":"bank:INS101:I101N1-044","payload":{"prompt":"An employee earning N50,000 a month dies in an accident at work. Using the Workmen's Compensation scale of 42 months' earnings for death, how much compensation is payable?","options":["N2,520,000","N2,100,000","N2,700,000","N600,000"],"correctOption":1,"section":"Liability and accident insurance","explanation":"Death compensation is 42 months' earnings, so 42 x N50,000 = N2,100,000. Using the permanent disability figure of 54 months instead would give N2,700,000, which is the wrong scale for death."}},{"itemId":"3e704ebe-bd70-55ff-a9bb-86fc10470767","questionId":"ae972f89-6bd9-5de0-ac16-9d058c83aa5a","sourceKey":"bank:INS101:I101N1-045","payload":{"prompt":"A cement factory worker who earned N40,000 monthly is left permanently disabled after a workplace accident. At 54 months' earnings, what is he paid?","options":["N480,000","N1,680,000","N2,160,000","N2,400,000"],"correctOption":2,"section":"Liability and accident insurance","explanation":"Permanent disability attracts 54 months' earnings, so 54 x N40,000 = N2,160,000. Using the death figure of 42 months would give N1,680,000, which applies the wrong scale."}},{"itemId":"e04e4b6a-50c3-5ea5-87e5-6bc61b24c099","questionId":"acf390b9-7062-50c3-9124-885811dfd75d","sourceKey":"bank:INS101:I101N1-046","payload":{"prompt":"Under the Workmen's Compensation scale for temporary total disability, what percentage of basic pay is paid for the first 6 months?","options":["25%","75%","100%","50%"],"correctOption":2,"section":"Liability and accident insurance","explanation":"Temporary total disability is paid at 100% of basic pay for the first 6 months, then 50% for the next 3 months and 25% for the next 15 months. 50% is the rate for the second stage, not the first 6 months."}},{"itemId":"7ca26c5a-9633-5a72-9952-505c45156b29","questionId":"3236bcaf-2eee-54f3-ad72-4d3bb226b880","sourceKey":"bank:INS101:I101N1-047","payload":{"prompt":"A worker earning N60,000 a month is temporarily totally disabled for 9 months. Under the scale of 100% of basic pay for the first 6 months and 50% for the next 3 months, what is his total compensation?","options":["N540,000","N360,000","N450,000","N405,000"],"correctOption":2,"section":"Liability and accident insurance","explanation":"The first 6 months are paid in full: 6 x N60,000 = N360,000. The next 3 months are at 50%: 3 x N30,000 = N90,000, giving N450,000 in total. Paying all 9 months at 100% would give N540,000, ignoring the drop to 50%."}},{"itemId":"6fbd9317-3129-52a2-8829-f6f9b65b036a","questionId":"7f11e525-f7c5-5e85-b30c-a4a42f78bfb5","sourceKey":"bank:INS101:I101N1-048","payload":{"prompt":"Under the Workmen's Compensation scale for temporary total disability, after the first 9 months the worker receives 25% of basic pay for up to how many further months?","options":["6 months","12 months","3 months","15 months"],"correctOption":3,"section":"Liability and accident insurance","explanation":"The scale pays 100% for the first 6 months, 50% for the next 3 months, and 25% for the next 15 months. Three months is the length of the 50% stage, not the 25% stage."}},{"itemId":"ad398fad-303e-5840-bd26-66a4ae6adbe1","questionId":"2d9abdad-58f1-5b69-817f-67a7f5d82dda","sourceKey":"bank:INS101:I101N1-049","payload":{"prompt":"An employers' liability policy will NOT pay for an employee's injury arising from","options":["A fall in the company's warehouse during work","A machine accident at work","The employer's breach of a statutory health and safety duty","War, invasion or civil war"],"correctOption":3,"section":"Liability and accident insurance","explanation":"Employers' liability excludes war, invasion, civil war, mutiny, insurrection and similar events. Claims from breach of statutory duty, such as health and safety rules, are actually covered, and so are ordinary accidents in the course of work."}},{"itemId":"1fb812d0-ae93-5e51-bd01-0e11bb406b10","questionId":"8ff31c59-e899-5827-9638-e971a0ab69c3","sourceKey":"bank:INS101:I101N1-050","payload":{"prompt":"In personal accident insurance, which of the following does NOT count as a \"bodily injury\" on its own?","options":["A head injury in a road crash","Shock or grief","A broken arm from a fall","Burns from an accidental fire"],"correctOption":1,"section":"Liability and accident insurance","explanation":"For personal accident cover, shock or grief alone does not count as bodily injury. A broken arm, burns or a head injury are physical injuries to the body, so they do count."}},{"itemId":"6331ef92-c82b-5ae4-92ae-9be2a599542a","questionId":"466d5382-33e9-521e-8495-4b9f1c06c910","sourceKey":"bank:INS101:I101N1-051","payload":{"prompt":"In personal accident insurance, the requirement that the accident must be the direct cause of the injury, with no other intervening force, is described by the key term","options":["Bodily injury","Independent","Proximate cause","External, violent and visible means"],"correctOption":1,"section":"Liability and accident insurance","explanation":"\"Independent\" means the accident must be the direct cause of the injury, with no other intervening force. \"External, violent and visible means\" describes how the accident happens, not the absence of another intervening cause."}},{"itemId":"e5149fcd-9e54-525b-878f-8cf77b9a9b40","questionId":"b6a68f27-c863-59c3-9b1d-f942fd36937c","sourceKey":"bank:INS101:I101N1-052","payload":{"prompt":"Under the personal accident requirement that injury be caused by \"external, violent and visible means\", which statement is correct?","options":["The cause of the accident need not be external","Only injuries that can be seen on the skin are covered","The injury itself need not be visible, so internal injury is covered if the cause is covered","Internal injuries are always excluded"],"correctOption":2,"section":"Liability and accident insurance","explanation":"The phrase refers to the cause of the accident, not the injury, so an internal injury is covered if its cause is covered. Saying only visible skin injuries are covered misreads the word \"visible\" as applying to the injury."}},{"itemId":"475995af-2759-5822-973d-7d9b50e9d25e","questionId":"7932915d-c79b-596c-81dd-a9c316577e69","sourceKey":"bank:INS101:I101N1-053","payload":{"prompt":"Under personal accident insurance, the temporary total disablement benefit is a periodic payment for up to","options":["26 weeks","104 weeks","156 weeks","52 weeks"],"correctOption":1,"section":"Liability and accident insurance","explanation":"Temporary total disablement is paid periodically for up to 104 weeks, which is about two years. Fifty-two weeks is only one year, which is shorter than the limit."}},{"itemId":"7195b22b-9d41-5393-b928-81156ec15908","questionId":"d3816cc9-33e1-5df4-868c-35a769c9da68","sourceKey":"bank:INS101:I101N1-054","payload":{"prompt":"Under personal accident insurance, the benefit paid for permanent disablement usually takes the form of","options":["A periodic payment for up to 104 weeks","A fixed lump sum","A pension for the rest of the insured's life","Reimbursement of hospital bills only"],"correctOption":1,"section":"Liability and accident insurance","explanation":"Permanent disablement is paid as a fixed lump sum. The periodic payment for up to 104 weeks is the temporary total disablement benefit, not the permanent one."}},{"itemId":"7b11a785-d292-5a51-8d71-b987904bea13","questionId":"e9546b56-7353-5738-a020-f2c4973b2422","sourceKey":"bank:INS101:I101N1-055","payload":{"prompt":"A personal accident policy will NOT pay where the insured's injury results from","options":["A road accident on the way to work","A slip on a wet floor at the workplace","An accidental fall at home","Drug abuse or drunkenness"],"correctOption":3,"section":"Liability and accident insurance","explanation":"Personal accident policies exclude drug abuse or drunkenness, as well as mental illness, nuclear war, and illness and wear and tear. Injuries from genuine accidents, such as a road crash or a fall at home, are exactly what the policy covers."}},{"itemId":"1356d140-0d85-5721-9b1a-2e5a0b78d6d7","questionId":"bd33a9ed-4512-5088-b745-474722f8896a","sourceKey":"bank:INS101:I101N1-056","payload":{"prompt":"Mr. Bello's car is damaged and he breaks his leg in a road accident in Ikorodu. Which loss will his personal accident policy NOT pay for?","options":["Income while he is unable to work","The damage to his car","His medical and hospital expenses","A lump sum if he is permanently disabled"],"correctOption":1,"section":"Liability and accident insurance","explanation":"Personal accident insurance covers bodily injury and its costs, not loss of or damage to property in the accident. Medical expenses, income while unable to work and permanent disablement are all personal accident benefits."}},{"itemId":"0f57bded-c47d-532a-aaa9-fadeee97f614","questionId":"186a798b-81b7-5ab9-801f-367c663c386e","sourceKey":"bank:INS101:I101N1-057","payload":{"prompt":"Which of the following is a benefit of personal accident insurance compared with disability insurance?","options":["Payment only after a long waiting period","Higher co-payments and deductibles","Cover for loss of or damage to property","Near-instant payment with no waiting period"],"correctOption":3,"section":"Liability and accident insurance","explanation":"Personal accident cover pays almost immediately, with no waiting period like disability insurance, and has no co-pay or deductibles. Saying it involves higher co-payments and deductibles is the opposite of its actual benefit."}},{"itemId":"d805ce67-8091-540d-95de-b215fa439c6f","questionId":"1c79e583-b69e-5851-9ab5-727a9f611ce3","sourceKey":"bank:INS101:INS-0029","payload":{"prompt":"Rate of contribution stipulated by Pension Reform Act 2014 is","options":["7.5% from the employer and employee","8% for the employee and 10% for the employer.","5% from the employee and 15% by the employer.","18% by the employee only."],"correctOption":1,"section":"Group, social and pension insurance","explanation":"Under the Pension Reform Act 2014, the minimum contribution is 8% of monthly emoluments from the employee and 10% from the employer, making 18% in total. Option A reflects the older 7.5% each rate under the 2004 Act. Option D wrongly puts the whole 18% on the employee."}},{"itemId":"5159047f-3dc1-5655-ab8e-71d3e6936f9f","questionId":"8f55280b-f637-5d8f-a749-2ee1f6a5fd0b","sourceKey":"bank:INS101:INS-0182","payload":{"prompt":"The form of pension providing an income for a fixed period or for life is what?","options":["Annuity","Short term Assurance","Underwriters","Mutual Assure Association"],"correctOption":0,"section":"Group, social and pension insurance","explanation":"An annuity is a contract that pays a regular income for a fixed period or for the rest of the annuitant's life, which is why it is used to provide pensions. Short term assurance (B) pays only on death within a short period, while underwriters (C) and mutual associations (D) are people and organisations, not types of pension."}},{"itemId":"928c70b5-ad46-53f7-a56b-56b5fcabcfc9","questionId":"ecccd983-8e90-59b5-83bf-60f247d9cb5e","sourceKey":"bank:INS101:INS-0241","payload":{"prompt":"Individual evidence of insurability is required in group insurance","options":["True, because every member must pass a medical examination","False","True","True, because each member must submit an individual proposal form"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"In group insurance the insurer underwrites the group as a whole, so individual members normally do not have to prove their insurability. Options A and D describe individual insurance, where each person is underwritten separately."}},{"itemId":"e63be679-9d46-50ae-aa5f-14ba5d300123","questionId":"4706d3d5-a100-5c95-a7cd-95e9817b7e6c","sourceKey":"bank:INS101:INS-0242","payload":{"prompt":"Group insurance usually costs less in comparison to individual insurance","options":["False, because group members each pay their own commission","True","False, because group cover always costs more per person","False"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"Group insurance is usually cheaper per person because there is one master policy, one premium collection and lower administration and selling costs. Options C and A are wrong because group cover is normally cheaper and does not involve separate commissions for each member."}},{"itemId":"dbf50300-f19a-5293-b502-362be81cbca7","questionId":"b6a4ee07-9ef7-5b78-a324-e78ec9ce119a","sourceKey":"bank:INS101:INS-0243","payload":{"prompt":"An example of social insurance is National Health Insurance Scheme","options":["False, because NHIS is a private life assurance scheme","False","True","False, because NHIS covers motor accidents only"],"correctOption":2,"section":"Group, social and pension insurance","explanation":"The National Health Insurance Scheme is a government health insurance scheme set up by law, which is what makes it social insurance. Option A is wrong because it is not a private life policy, and option D is wrong because it covers health care, not motor accidents."}},{"itemId":"e3d5ab77-d8fc-5b18-afc9-e28d279562a1","questionId":"f929cc3a-02b8-57bc-a160-8a98cfd55898","sourceKey":"bank:INS101:INS-0247","payload":{"prompt":"An underwriting principle in group insurance is simple and efficient administration","options":["False, because group insurance must be administered member by member","True","False","False, because administration has no bearing on group underwriting"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"Simple and efficient administration is a standard underwriting principle in group insurance, which keeps costs low through one master policy and payroll deductions. Options A and D are wrong because group cover depends on low, simple administration to stay cheap."}},{"itemId":"d77e1221-9455-55ff-8034-d0f6dce38d35","questionId":"7ee11e7e-13ba-5c55-92e5-dffc917dd3e6","sourceKey":"bank:INS101:INS-0252","payload":{"prompt":"Social insurance programmes are a form of private insurance","options":["True, because joining social insurance is purely voluntary","True, because social insurance is run by private insurers for profit","True","False"],"correctOption":3,"section":"Group, social and pension insurance","explanation":"Social insurance programmes are set up by law and run or supervised by government, and membership is usually compulsory, so they are not private insurance. Options B and A describe private, voluntary insurance instead."}},{"itemId":"d60d5d12-ebeb-54b8-beb0-ad27f383f90a","questionId":"1b3d53c7-db91-5db4-9389-8a41ba12c1d2","sourceKey":"bank:INS101:INS-0253","payload":{"prompt":"A basic characteristic of social insurance is that it is a compulsory program","options":["False, because social insurance is always voluntary","False","False, because social insurance is sold only by private insurers","True"],"correctOption":3,"section":"Group, social and pension insurance","explanation":"Social insurance programmes are usually compulsory for the people they cover, which is a basic feature that separates them from private insurance. Options A and C are wrong because these programmes are compulsory and government-backed."}},{"itemId":"2d3770dd-b1cf-51ef-a0e3-2aee2e2971fd","questionId":"2aa532e9-6801-5fc6-8ded-0c77db816f19","sourceKey":"bank:INS101:INS-0254","payload":{"prompt":"Social insurance programs are necessary because some risks are difficult to insure privately","options":["False, because every risk can be insured privately","False, because social insurance only covers property","False","True"],"correctOption":3,"section":"Group, social and pension insurance","explanation":"Some risks, such as large-scale unemployment or old-age poverty, are hard for private insurers to cover, so government steps in with social insurance. Option A is wrong because not all risks are privately insurable, and option B is wrong because social insurance mainly protects people and their incomes."}},{"itemId":"c9d6411d-a338-5d9e-8050-d28b93619fe2","questionId":"490d92da-4c21-5ee2-80d0-f51eb7922178","sourceKey":"bank:INS101:INS-0262","payload":{"prompt":"A problem which insurers should be concerned about in group insurance policy is","options":["ponzi scheme","means test","utmost good faith","adverse selection"],"correctOption":3,"section":"Group, social and pension insurance","explanation":"Adverse selection is the tendency for people with a higher than average chance of loss to seek cover, and in group insurance it arises if only the less healthy members join. A ponzi scheme (A) is a fraud, a means test (B) belongs to welfare programmes, and utmost good faith (C) is a contract principle, not the special group problem."}},{"itemId":"fd204c72-de39-583f-b588-71cfc30665c9","questionId":"d8b2ecac-3c72-572d-ab4f-a9eee111e90f","sourceKey":"bank:INS101:INS-0269","payload":{"prompt":"Group insurance differs from individual insurance because","options":["it is more expensive","experience rating is used","individual insurability is required","premiums are paid individually"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"Large group policies are often experience rated, meaning the group's own claims record helps set its premium. Group cover is usually cheaper, not dearer (A), it does not require individual evidence of insurability (C), and the employer normally pays one master premium (D)."}},{"itemId":"1c3dbd68-0222-5623-b136-f694c55d9529","questionId":"52f393a2-9934-59f6-8455-299c678987f3","sourceKey":"bank:INS101:INS-0274","payload":{"prompt":"Social insurance program place primary emphasis on ______ rather than on equity in cost and benefits.","options":["adequacy of benefits","equality of persons","all of the above","none of the above"],"correctOption":0,"section":"Group, social and pension insurance","explanation":"Social insurance aims to give everyone a basic, adequate level of benefit, so it stresses social adequacy rather than an exact match between what each person pays and receives. Equality of persons (B) is not the guiding principle, which also rules out C."}},{"itemId":"1c6ca21f-633d-57a5-b252-0aadcbf18203","questionId":"fbcb4bba-6d21-54a4-bfec-8d294a2b950b","sourceKey":"bank:INS101:INS-0289","payload":{"prompt":"In a group insurance policy, the group policy premium can be paid by the:","options":["Employer","Employee","Both employer and employee","All of the above"],"correctOption":3,"section":"Group, social and pension insurance","explanation":"A group scheme can be non-contributory, where the employer pays all the premium, or contributory, where employer and employees share it, and some schemes are paid fully by members. Since A, B and C are all possible arrangements, 'All of the above' is the best answer. Option C alone is too narrow because it leaves out schemes paid by just one party."}},{"itemId":"5e5a92d4-86f2-5126-8bdf-871e25612211","questionId":"9d2ad6da-66ac-5719-8df1-47cb3259a34a","sourceKey":"bank:INS101:INS-0290","payload":{"prompt":"One of these is not an eligibility requirement for group insurance:","options":["Meet up a probationary period","Apply for cover in the eligibility time frame","Contribute to the cost of the group insurance premium","Be a full-time employee or member"],"correctOption":2,"section":"Group, social and pension insurance","explanation":"Group cover usually sets eligibility rules such as being a full-time employee or member, completing a probationary period and applying within the eligibility period. Contributing to the premium is not an eligibility condition, because many group schemes are paid fully by the employer. Options A, B and D are all typical eligibility requirements."}},{"itemId":"0d31e5bf-e593-52b8-8cfd-16742dadcc22","questionId":"ab823095-43a7-5ee4-bf3f-d26894ddb504","sourceKey":"bank:INS101:INS-0354","payload":{"prompt":"Under the Pension Reform Act 2014, the minimum pension contribution ratio (employer : employee) in Nigeria is","options":["10:20","7.5:7.5","5:10","None of the above"],"correctOption":3,"section":"Group, social and pension insurance","explanation":"Under the Pension Reform Act 2014, the employer must contribute at least 10% and the employee at least 8% of monthly emoluments, a 10:8 split that none of the options shows. Option B, 7.5:7.5, was the split under the older 2004 law, so it is the tempting trap. Options A and C do not match either law."}},{"itemId":"c5470a49-7040-5395-b60c-9ec247c38976","questionId":"6c8754cc-8692-5236-96fc-5f940f36697e","sourceKey":"bank:INS101:INS-0412","payload":{"prompt":"An insurance contract is a legal agreement between:","options":["Insured and regulators","Insurer and policyholder","Insurer and agent","Insured and lender"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"An insurance contract is a legal agreement between the insurer, who promises to pay for covered losses, and the policyholder, who pays the premium. Option C is wrong because an agent only acts for the insurer. Options A and D are not the parties to the policy."}},{"itemId":"9e6c19b1-1881-56d5-bdca-2205749631f3","questionId":"62a6fc5c-7dbc-5987-a748-1c4db4437962","sourceKey":"bank:INS101:INS-0413","payload":{"prompt":"The principle of utmost good faith in insurance requires:","options":["Insurer to withhold details","Full disclosure by both parties","Insured to skip payments","Insurer to raise rates"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"Utmost good faith requires both the insurer and the insured to disclose all material facts fully and honestly. Option A is the opposite of the duty. Options C and D have nothing to do with good faith."}},{"itemId":"ddce0f10-dbb5-5a7e-9676-039456c1fe66","questionId":"d6f34dc9-2098-50ac-849e-6716a37804f5","sourceKey":"bank:INS101:INS-0414","payload":{"prompt":"The premium in an insurance contract is:","options":["Payout from insurer to insured","Payment from insured to insurer","Loss compensation amount","Policy paperwork itself"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"The premium is the price the insured pays the insurer for cover. Options A and C describe claim payments, which flow the other way. Option D is the policy document."}},{"itemId":"86b02272-9de5-51e8-9b5a-46ea83e62415","questionId":"8860bbac-f266-53f5-bd13-ea429a743e39","sourceKey":"bank:INS101:INS-0417","payload":{"prompt":"The principle of subrogation allows the insurer to:","options":["Hike premium charges","Chase liable third parties","Refuse claim payments","Cut coverage scope"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"After paying a claim, the insurer can step into the insured's shoes and recover the amount from the third party who caused the loss. Option C is wrong because subrogation only arises after a claim has been paid. Options A and D have nothing to do with subrogation."}},{"itemId":"834b0140-b0ff-574b-9339-4f05fc281f11","questionId":"bf5050c3-f857-53ae-82ab-1e246d85cc0c","sourceKey":"bank:INS101:INS-0418","payload":{"prompt":"A void insurance contract is:","options":["Fully binding legally","Legally unenforceable","Renewed automatically","Always lucrative"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"A void contract has no legal effect, so neither party can enforce it in court. A contract can also become void after it was made, for example when performance becomes impossible or the law changes. Option A is the opposite, and options C and D do not describe a void contract."}},{"itemId":"37cc5c0d-c505-5635-bf36-8a621170e431","questionId":"a24fea76-27c9-5f8b-9719-bbe977c64375","sourceKey":"bank:INS101:INS-0419","payload":{"prompt":"The principle of proximate cause in insurance refers to:","options":["The farthest loss trigger","The dominant, effective cause of loss","The premium cost","The coverage term"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"The proximate cause is the dominant or effective cause that sets off the chain of events leading to the loss, and it need not be the last event in time. Option A is wrong because a remote cause is not what decides a claim, and options C and D have nothing to do with causation."}},{"itemId":"e5fb6e4c-e66b-5060-9e76-0a29e4b738f6","questionId":"b9d1d63d-6be0-5c63-b983-1f8fb959b8fd","sourceKey":"bank:INS101:INS-0420","payload":{"prompt":"An insurance policy document includes:","options":["Coverage terms and rules","Insured's private notes","Insurer's balance sheets","Insured's tax filings"],"correctOption":0,"section":"Group, social and pension insurance","explanation":"A policy document sets out the terms, conditions, cover and exclusions agreed between insurer and insured. Options B, C and D are private or financial records that are not part of the policy."}},{"itemId":"88585ed8-12d0-5470-84ba-e9c060474ec7","questionId":"8ba3b6f6-1b39-5e50-9c38-89ea80be5524","sourceKey":"bank:INS101:INS-0421","payload":{"prompt":"The principle of contribution applies when:","options":["Multiple insurers share a risk","Insured skips payments","Insurer boosts premiums","Insured voids the policy"],"correctOption":0,"section":"Group, social and pension insurance","explanation":"Contribution applies when two or more insurers cover the same interest against the same loss, so each pays its fair share. Options B, C and D describe unrelated situations."}},{"itemId":"99d71a66-01be-563a-b4d5-2d9562540dbc","questionId":"d33e36fd-7507-5431-a535-4c5aee2079dc","sourceKey":"bank:INS101:INS-0422","payload":{"prompt":"A deductible in an insurance contract is:","options":["Part of a loss the insured bears","Total premium cost","Loss payout sum","Policy duration"],"correctOption":0,"section":"Group, social and pension insurance","explanation":"A deductible is the first part of a loss that the insured must bear before the insurer pays the rest. Option B is the premium, which buys the cover, and option C is the claim payout. Option D is the period of cover."}},{"itemId":"bf8f6cf3-350c-5e59-abaf-c33ef071789f","questionId":"87c0f22f-b913-5b5c-ae3b-76b7d0f4c8eb","sourceKey":"bank:INS101:INS-0424","payload":{"prompt":"A unilateral contract in insurance means:","options":["Both sides commit equally","Only insurer commits","Only insured commits","Neither side commits"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"Insurance is called unilateral because only the insurer makes a legally enforceable promise, to pay for covered losses. The insured is not legally bound to keep paying premiums, so option A is wrong. Option C reverses the roles."}},{"itemId":"7499097d-de53-5db3-a644-d376ce4ef9a4","questionId":"c2fb6e3d-f97c-59c6-b5b6-8aa0a41d0a21","sourceKey":"bank:INS101:INS-0425","payload":{"prompt":"The principle of adhesion in insurance means:","options":["Insured negotiates all terms","Insurer drafts, insured accepts","Insured crafts the deal","Contract lacks validity"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"A contract of adhesion is drafted by the insurer and the insured simply accepts or rejects it as written. Options A and C are wrong because the insured does not usually negotiate or write the terms. Option D is wrong because such contracts are valid."}},{"itemId":"6b3ff954-2c98-536a-b7fa-ea9101c7dd7a","questionId":"234d2313-193f-54df-a701-9afbb87797dd","sourceKey":"bank:INS101:INS-0426","payload":{"prompt":"An exclusion in an insurance policy refers to:","options":["Covered risk scenarios","Uncovered risk scenarios","Premium payment size","Claim filing steps"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"An exclusion lists situations or losses that the policy does not cover, such as war or wear and tear. Option A describes the insuring clause. Options C and D are the premium and claims procedure."}},{"itemId":"f092ad03-2b86-583d-b7c1-da16d7b1e0eb","questionId":"03c9a398-8cda-59a6-958a-4cc05be43644","sourceKey":"bank:INS101:INS-0473","payload":{"prompt":"The following are ways in which contract can be classified except","options":["Enforceability","Creations","Agreements","Executions"],"correctOption":2,"section":"Group, social and pension insurance","explanation":"Contracts are commonly classified by their enforceability (valid, void, voidable, unenforceable), by how they are created (express, implied, quasi) and by their execution (executed, executory). 'Agreements' is not a basis of classification, because every contract is an agreement; options A, B and D are genuine bases."}},{"itemId":"1e38f391-4266-51bb-90f2-1959efbcd197","questionId":"444c13e0-526c-51a7-ae00-78320eec7a10","sourceKey":"bank:INS101:INS-0474","payload":{"prompt":"A contract made by words spoken or written is","options":["Implied contract","Written contract","Quasi contract","Express contract"],"correctOption":3,"section":"Group, social and pension insurance","explanation":"An express contract is one whose terms are stated in words, whether spoken or written. A written contract (option B) is only one kind of express contract, while an implied contract (option A) comes from conduct and a quasi contract (option C) is imposed by law."}},{"itemId":"eec2aac7-70ab-5164-b5bb-97f43fa2907a","questionId":"1c4d10c2-f2ba-52f4-b7ad-93463e71e9e2","sourceKey":"bank:INS101:INS-1015","payload":{"prompt":"Ad idem means","options":["the contract is voidable","one party may cancel at any time","the contract is void from the start","both parties understand the same thing in the same sense"],"correctOption":3,"section":"Group, social and pension insurance","explanation":"Consensus ad idem means a meeting of minds: both parties agree on the same thing in the same sense, which every valid contract, including insurance, needs. Option A describes a defect in a contract, not agreement, while C and B are also unrelated legal ideas."}},{"itemId":"22ac0bbf-bb82-58ea-981a-939536699f7e","questionId":"ffc56421-e39f-5ea6-8a09-c880596d18ff","sourceKey":"bank:INS101:INS-1054","payload":{"prompt":"Group life insurance provides coverage for a number of persons under one contract called a","options":["master policy","endorsement","proposal form","cover note"],"correctOption":0,"section":"Group, social and pension insurance","explanation":"In group life, the employer or group holds one master policy covering all members, and each member usually gets a certificate showing their cover. A cover note (option D) is a temporary document used mainly in general insurance, and an endorsement (option B) records a change to an existing policy."}},{"itemId":"d314c222-39d9-59e2-9ee2-91c6790f5a14","questionId":"55ed6eb4-f51f-5969-9d4e-f2b9b4a79b06","sourceKey":"bank:INS101:INS-1057","payload":{"prompt":"Which of the following statements is correct about group insurance?","options":["Each member receives a separate policy contract","It can only cover one person at a time","Each member must undergo a full medical examination","It usually costs less per person than individual policies"],"correctOption":3,"section":"Group, social and pension insurance","explanation":"Group insurance is cheaper per person because one policy covers many members, cutting administration and selling costs. It is wrong to say each member must have a full medical examination, as group cover usually needs little or no individual medical evidence, and members get certificates under one master policy rather than separate policies."}},{"itemId":"e5b9ba42-da89-5cf9-a645-151660173897","questionId":"4f549ab5-7f91-5159-9748-d10a4579e344","sourceKey":"bank:INS101:INS-1190","payload":{"prompt":"Which of the following is NOT one of the miscellaneous (general accident) classes of insurance sold by commercial insurers?","options":["Motor insurance","Third party liability insurance","Social insurance","Burglary insurance"],"correctOption":2,"section":"Group, social and pension insurance","explanation":"Social insurance is a government scheme, often compulsory, that protects workers and citizens, so it is not a commercial miscellaneous class. Options A, B and D are all everyday non-life covers that insurance companies sell under the miscellaneous or accident heading."}},{"itemId":"5a5f3bc7-e523-5236-94d5-a5a9d1977d4d","questionId":"b43627ae-756d-5e99-95fa-753c7b5099ef","sourceKey":"bank:INS101:I101N1-058","payload":{"prompt":"A pension plan that uses a fixed rule for the benefit, such as a formula based on salary and years of service, with contributions set by the actuary, is called a","options":["Defined benefit plan","Defined contribution plan","Single-member plan","Unfunded plan"],"correctOption":0,"section":"Group, social and pension insurance","explanation":"In a defined benefit plan the benefit is fixed by a rule, and contributions vary as set by the actuary. A defined contribution plan does the reverse: it fixes the contribution and the benefit depends on the member's account."}},{"itemId":"06628432-425c-5bdf-adcd-91bcf112391c","questionId":"8ce4f530-8d66-58c8-810f-47ec466ae80b","sourceKey":"bank:INS101:I101N1-059","payload":{"prompt":"In which type of pension plan does each member have an individual account, with contributions fixed as a percentage of salary?","options":["Pay-as-you-go plan","Defined contribution plan","Defined benefit plan","State plan"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"A defined contribution plan fixes the contribution, often a percentage of salary, and keeps an individual account for each member. A defined benefit plan fixes the benefit instead, with contributions varying."}},{"itemId":"d702f9e9-b939-55a8-adc1-2178085b871e","questionId":"dc52b9bd-9378-562d-b19c-8a131a417382","sourceKey":"bank:INS101:I101N1-060","payload":{"prompt":"A pension scheme in which current workers' contributions are used to pay current pensioners, with no pool of assets built up, is described as","options":["Funded","Single-member","Unfunded (pay-as-you-go)","Defined contribution"],"correctOption":2,"section":"Group, social and pension insurance","explanation":"An unfunded or pay-as-you-go scheme uses current contributions to pay current pensions, which is a transfer between generations with no asset pool. A funded scheme is the opposite, building up a fund over the member's service."}},{"itemId":"72ba4a86-db38-509b-9622-ed9170e55424","questionId":"3e306e8f-45e9-5806-8152-6786103264a2","sourceKey":"bank:INS101:I101N1-061","payload":{"prompt":"Social insurance pays benefits without checking whether the claimant is poor enough to need them. This characteristic is known as","options":["No means test","Floor of income","Individual equity","Full funding"],"correctOption":0,"section":"Group, social and pension insurance","explanation":"Social insurance has no means test, which is what sets it apart from public assistance. Individual equity is the private insurance idea that benefits track contributions, so it does not describe this feature."}},{"itemId":"8c4ca993-c864-52a8-a78b-343becc77473","questionId":"26510d51-76ca-596a-a863-e21d61c4dd36","sourceKey":"bank:INS101:I101N1-062","payload":{"prompt":"Which type of group insurance, a late entrant to the market, covers key officials in fields such as banking, medicine and law?","options":["Group keyman insurance","Group accident insurance","Group life insurance","Group health insurance"],"correctOption":0,"section":"Group, social and pension insurance","explanation":"Group keyman insurance is the late entrant designed for key officials in banking, medicine and law. Group health is the most common type of group insurance, not the late entrant for key officials."}},{"itemId":"68dfbe0a-409c-566e-a70f-93c535f51797","questionId":"ca3fbc1b-d052-5f3d-a043-a198ef9cbf92","sourceKey":"bank:INS101:I101N1-063","payload":{"prompt":"Which is the most common of the four main types of group insurance?","options":["Group health insurance","Group life insurance","Group accident insurance","Group keyman insurance"],"correctOption":0,"section":"Group, social and pension insurance","explanation":"Group health is the most common type of group insurance. Group keyman is the opposite case, a late entrant that covers only key officials."}},{"itemId":"501d9a37-b5a0-5304-8820-db568634cb73","questionId":"bb23f560-8280-50e3-a730-b155911e771a","sourceKey":"bank:INS101:I101N1-064","payload":{"prompt":"Making social insurance compulsory has three advantages. Which of the following is one of them?","options":["A means test can be applied to every claimant","Adverse selection is reduced","Benefits are tied exactly to each person's contributions","Larger contingency reserves are needed"],"correctOption":1,"section":"Group, social and pension insurance","explanation":"Compulsion reduces adverse selection, makes a floor of income easier to provide, and reduces random swings so smaller reserves are needed. Saying larger contingency reserves are needed is the reverse of the actual advantage."}},{"itemId":"12f95628-ccf5-51eb-a8d9-d04a96dc4830","questionId":"311a4d8a-9e19-5ec1-9b61-12e3ec062ee9","sourceKey":"bank:INS101:INS-0007","payload":{"prompt":"A contract that can be inferred from the conduct of a person or the circumstances of the particular case is a _________contract.","options":["Implied contract","Written contract","Quasi contract","Express contract"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"An implied contract is one whose existence is inferred from the parties' conduct or the circumstances, even though nothing was expressly said or written. Option D is the opposite, since an express contract states its terms in words. Option C, a quasi contract, is imposed by law rather than inferred from conduct."}},{"itemId":"7ddd7be1-b7f9-5395-8ca5-7e2b0843c28a","questionId":"682caf86-d799-552f-84e2-c2bbe65eac51","sourceKey":"bank:INS101:INS-0019","payload":{"prompt":"A contract where rights and obligations arise not by any agreement between the parties but by operation of law is a ________ contract.","options":["Quasi contract","Implied contract","Written contract","Express contract"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"A quasi contract is not based on any agreement; the law imposes rights and duties to prevent one party being unfairly enriched at another's expense. Option B, an implied contract, still rests on agreement shown by conduct. Options C and D are about how an agreed contract is recorded, in writing or in express words."}},{"itemId":"44a3ae2e-e1c8-5fd3-a4b1-afcbf4642ebf","questionId":"b1c8019b-149e-5b36-831f-786fa2ee7ebd","sourceKey":"bank:INS101:INS-0020","payload":{"prompt":"A contract where both parties to the contract have not performed their respective obligations under the contract is a __________contract.","options":["Executory contract","Partly executory contract","Executed contract","Partly executed contract"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"A contract is executory when neither party has yet carried out its obligations. Option C, executed, is the opposite, where performance is complete. Options B and D describe situations where at least one side has performed part of its obligations, which is not what the question describes."}},{"itemId":"35be90e5-72c0-51ec-ba6c-ef097e1f8293","questionId":"d11a9db4-7923-5b7d-ab2e-0649132e0bb1","sourceKey":"bank:INS101:INS-0021","payload":{"prompt":"A contract which is actually valid but cannot be enforced by court because of some technical defect is a __________contract.","options":["Voidable contract","Enforceable contract","Void contract","Unenforceable contract"],"correctOption":3,"section":"Insurance contract and its principles","explanation":"An unenforceable contract is valid in itself, but the courts will not enforce it because of a technical defect such as lack of required written evidence. Option C, a void contract, has no legal effect at all. Option A, a voidable contract, is valid until the innocent party chooses to set it aside."}},{"itemId":"bba9a774-47a5-566f-b322-e8855c2b8717","questionId":"57e849d8-4b54-5f4d-bcd1-52e2070e867b","sourceKey":"bank:INS101:INS-0022","payload":{"prompt":"An offer is made when the ___________make an offer and communicate such offer to the _______","options":["Offeree, Offeror","Offeror, Offeree","Offeree, Offeree","Offeror, Offeror"],"correctOption":1,"section":"Insurance contract and its principles","explanation":"The offeror is the person who makes the offer, and the offeree is the person it is made to. So an offer is made when the offeror communicates it to the offeree. Option A reverses the two roles, and options C and D repeat the same party twice."}},{"itemId":"07e18e19-e614-59c2-aa7c-8a3c32860e73","questionId":"66f53704-6e87-55ac-9ad9-46e4a1995bb4","sourceKey":"bank:INS101:INS-0024","payload":{"prompt":"An insurance contract contains all but which of the following parts","options":["Declarations","Insuring agreements","Definitions","Conclusions"],"correctOption":3,"section":"Insurance contract and its principles","explanation":"An insurance policy is usually made up of declarations, insuring agreements, definitions, exclusions and conditions, with miscellaneous provisions. There is no standard section called conclusions, so D is the odd one out. Options A, B and C are all genuine parts of a policy."}},{"itemId":"cf2ae8f7-d2ad-5e7e-9b0b-7ebf688276c1","questionId":"b03d6c6d-e449-5fb2-aa0b-49bb17d06398","sourceKey":"bank:INS101:INS-0030","payload":{"prompt":"Insurance contract, being a ________contract implies that the insurer is legally bound to perform its part of the agreement as long as the insured pays the premium, while the insured is not legally bound to pay premium","options":["Adhesion","Aleatory","Unilateral","Conditional"],"correctOption":2,"section":"Insurance contract and its principles","explanation":"An insurance contract is unilateral because only the insurer makes a legally enforceable promise; the insured cannot be sued for failing to pay a premium, but cover simply stops if it is not paid. Option D, conditional, means the insurer pays only if the insured meets policy conditions such as reporting the loss, which is a different feature. Options A and B describe adhesion and the chance element, not this one-sided promise."}},{"itemId":"b92cfd3e-20f1-54e6-9230-3293f5b481b7","questionId":"08439e90-2795-582e-80e3-b841519ab961","sourceKey":"bank:INS101:INS-0078","payload":{"prompt":"A ______ definition of insurance defines insurance as a cooperative device to spread the loss caused by a particular risk over a number of persons who are exposed it and agrees to insure themselves against the risk.","options":["Contractual","functional","probability","contingency"],"correctOption":1,"section":"Insurance contract and its principles","explanation":"A functional definition describes what insurance does: it is a co-operative device for spreading the losses of a few over many people exposed to the same risk. Option A, a contractual definition, describes insurance as an agreement where one party promises to indemnify the other. Options C and D are not the usual categories."}},{"itemId":"ee02be12-2fbc-531a-8849-a3257965284d","questionId":"5d01bd82-1bb1-5f08-91ca-22d7a19d81c3","sourceKey":"bank:INS101:INS-0104","payload":{"prompt":"A ______ definition of insurance means that a party agrees to indemnify the other party/his beneficiary in the event of a given contingency.","options":["Contractual","functional","probability","contingency"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"A contractual definition sees insurance as an agreement where one party, the insurer, promises to indemnify the other or their beneficiary if a stated event happens. Option B, a functional definition, describes insurance by what it does, spreading losses over many people. Options C and D are not the usual categories."}},{"itemId":"65f70c3a-141b-5bc3-83c8-f6ce5544527e","questionId":"11b8d3ee-bad3-5da8-9b63-99ff686f25ab","sourceKey":"bank:INS101:INS-0129","payload":{"prompt":"To effect an insurance contract, only one is not a requirement","options":["Rectification","Acceptance","Legality","Capacity to contract"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"A valid insurance contract needs offer and acceptance, consideration, capacity to contract and legality of object. Rectification is a court remedy for correcting a written contract that does not match what was agreed, so it is not a requirement. Options B, C and D are all essential elements."}},{"itemId":"65fb3cb5-f990-58a8-95c4-9c9d77a7285f","questionId":"ae41b0ea-2470-5cf6-b09f-128a0c449c73","sourceKey":"bank:INS101:INS-0131","payload":{"prompt":"Only one of the following does not have full capacity to enter into an insurance contract","options":["Insurer","Minors","Retired Person","None of the above."],"correctOption":1,"section":"Insurance contract and its principles","explanation":"Minors do not have full capacity to contract, so contracts they make are generally not binding on them. Option C, a retired person, is an adult with full capacity, and retiring does not change that. Option A, an insurer, is itself a party to insurance contracts and clearly has capacity."}},{"itemId":"8bba6b85-88ba-5bd2-b751-4c4a1502720b","questionId":"bb07ed9f-4cc3-54f4-b927-4c90f826b1ba","sourceKey":"bank:INS101:INS-0157","payload":{"prompt":"Some of the essentials of insurance contracts are Consideration, Unrevoked offer and Intention to create legal obligation","options":["True","False, because insurance contracts do not need an offer","False, because consideration is not needed in an insurance contract","False"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"Consideration, an offer that has not been withdrawn (then accepted) and an intention to create legal relations are basic elements of every valid contract, insurance included. Option C and option B are wrong because insurance contracts need both consideration (the premium) and an offer, usually made through the proposal form."}},{"itemId":"7c8c6e3d-cbfb-5c76-b3e1-95c680d5e647","questionId":"0dcbaf12-3a0a-542a-84e0-1c695bb7267e","sourceKey":"bank:INS101:INS-0159","payload":{"prompt":"All the following is barred from effecting an insurance policy except one","options":["Married women","Insane persons","Minors","None of the above"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"A married woman has full capacity to take out an insurance policy in her own name. Insane persons (B) and minors (C) are the classic examples of people whose capacity to contract is limited, so they are the ones barred, and D cannot be right because one option is clearly an exception."}},{"itemId":"ac0bcd7a-464b-507e-a90b-6e9cd840e811","questionId":"0f7f17f2-37f2-5a71-b067-13908f9e39cb","sourceKey":"bank:INS101:INS-0160","payload":{"prompt":"The third party in insurance contract is","options":["The insurer","The policy holder","Any person other than insurer and insured","A & B"],"correctOption":2,"section":"Insurance contract and its principles","explanation":"An insurance contract has two parties: the insurer and the insured, so a third party is anyone outside that contract, such as a pedestrian injured by an insured car. The insurer (A) and the policyholder (B) are the first and second parties, so D is wrong too."}},{"itemId":"4a235393-7e20-5352-a47b-193590763012","questionId":"8b824ff5-7fdd-5eb7-be47-5e9128f4d986","sourceKey":"bank:INS101:INS-0169","payload":{"prompt":"The premium paid under a contract of insurance is known as the","options":["assignment","consideration","contribution","indemnity"],"correctOption":1,"section":"Insurance contract and its principles","explanation":"Consideration is what each party gives under a contract: the insured pays the premium and the insurer promises to pay valid claims. Contribution (C) and indemnity (D) are insurance principles about claim settlement, and assignment (A) is the transfer of a policy to someone else."}},{"itemId":"bf0bd8bd-159b-5270-a415-bf036cc388f9","questionId":"d00af8de-5b1a-5fef-890a-b748d8bb8820","sourceKey":"bank:INS101:INS-0344","payload":{"prompt":"Only insane persons and minors have no right to insure.","options":["False","True","True, but only in life assurance","True, but only in marine insurance"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"The statement is false because capacity rules are not limited to insane persons and minors: a drunken person can also avoid a contract by proving he did not understand it and the other party knew. It is also not true that minors and insane persons have no right at all, since they are still bound for necessaries at a reasonable price. Options C and D are wrong because capacity applies to every class of insurance, not just life or marine."}},{"itemId":"4a0b0f5d-15e4-539e-8a82-365345df13ee","questionId":"5ffdf041-9845-5a84-984d-8a6a6c75a8b3","sourceKey":"bank:INS101:INS-0379","payload":{"prompt":"The principle of insurable interest means:","options":["The insured gains from the item's survival","The insured is indifferent to the item","The insured escalates the risk","The insured prevents all losses"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"Insurable interest means the insured benefits from the safety of the subject matter and would suffer financially if it were lost or damaged. Option B is the opposite, since someone with no stake has no insurable interest. Options C and D do not describe the principle at all."}},{"itemId":"cdee7203-af76-5c0f-a1ab-34f2bbb16ba1","questionId":"8d288c71-03d5-56af-b715-6b954d2ff6c0","sourceKey":"bank:INS101:INS-0429","payload":{"prompt":"The underwriting department of an insurance company:","options":["Gauges risks and prices policies","Disburses claim payments","Advertises insurance plans","Designs new offerings"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"The underwriting department assesses each risk, decides whether to accept it and sets the premium and terms. Option B is the job of the claims department. Options C and D belong to marketing and product development."}},{"itemId":"e193a923-56b0-5d29-86ad-3463ed59dce2","questionId":"124941c6-3cd0-53b1-8085-8121d415679a","sourceKey":"bank:INS101:INS-0430","payload":{"prompt":"The claims department of an insurance company is responsible for:","options":["Setting coverage rates","Handling and settling claims","Promoting policy sales","Assessing risk profiles"],"correctOption":1,"section":"Insurance contract and its principles","explanation":"The claims department receives claims, checks that the loss is covered and then settles or pays them. Option A describes rating, which is done by actuaries and underwriters, option C is the work of marketing, and option D is underwriting."}},{"itemId":"5d02c82a-1b9a-5fa9-9d04-be6bc103603f","questionId":"6aab8b17-0f1c-5e6d-98df-d190fd9317b2","sourceKey":"bank:INS101:INS-0431","payload":{"prompt":"An actuary in an insurance company:","options":["Markets insurance plans","Analyzes stats for risk pricing","Creates ad strategies","Oversees staff training"],"correctOption":1,"section":"Insurance contract and its principles","explanation":"An actuary uses statistics and probability to measure how likely losses are, and this is the basis for pricing risks and setting premium rates. Options A and C describe marketing and advertising work, while option D is a human resources or training function."}},{"itemId":"41d79782-661c-5e80-bc5c-a08b1763a5ba","questionId":"b3bad970-009d-5b8b-affa-91c5eacfdb9b","sourceKey":"bank:INS101:INS-0432","payload":{"prompt":"The organizational structure of an insurance company typically includes:","options":["A factory production unit","An underwriting division","A manufacturing wing","A mining operations unit"],"correctOption":1,"section":"Insurance contract and its principles","explanation":"Underwriting is a core division of every insurer, because it decides which risks to accept and on what terms. Insurers sell a service, not physical goods, so a factory unit, a manufacturing wing or a mining unit (options A, C and D) has no place in their structure."}},{"itemId":"a76715d2-e394-59eb-aeee-1baf6e7dbbe9","questionId":"d4c33eb1-070f-5e04-abc1-ec5da26e3c80","sourceKey":"bank:INS101:INS-0433","payload":{"prompt":"The operation of an insurance company involves:","options":["Gathering premiums, paying claims","Dodging all uncertainties","Cutting policy coverage","Ignoring client needs"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"At its simplest, an insurer collects premiums from many policyholders into a pool and uses that pool to pay the claims of the few who suffer losses. Insurance does not remove uncertainty (option B), and cutting cover or ignoring clients (options C and D) would defeat the purpose of the business."}},{"itemId":"d3f2559f-2261-54e6-bc21-109f123c9c8c","questionId":"7b466678-6a47-59b1-8f2b-d3eb71738682","sourceKey":"bank:INS101:INS-0434","payload":{"prompt":"The marketing department of an insurance company:","options":["Evaluates risk levels","Sells policies to the public","Processes claim requests","Determines premium rates"],"correctOption":1,"section":"Insurance contract and its principles","explanation":"The marketing department promotes and sells the insurer's policies to the public, through agents, brokers, branches and advertising. Evaluating risk (option A) and setting rates (option D) belong to underwriting and actuarial work, while processing claims (option C) is the job of the claims department."}},{"itemId":"9294ffec-c34a-5311-8583-cd979afe96e2","questionId":"dffcbac8-232d-57c7-8ae6-ac9552744900","sourceKey":"bank:INS101:INS-0435","payload":{"prompt":"A mutual insurance company is:","options":["Held by equity investors","Owned by its policyholders","Run by state authorities","Owned by one person"],"correctOption":1,"section":"Insurance contract and its principles","explanation":"A mutual insurance company has no shareholders; it is owned by its policyholders, who share in any surplus. Option A describes a proprietary or stock company, option C a state insurer, and option D a sole proprietorship."}},{"itemId":"c5604ccb-1a4c-5360-8b4a-68bcf46ba072","questionId":"e8f41748-cc3f-5f76-bede-375ef7ebbf35","sourceKey":"bank:INS101:INS-0436","payload":{"prompt":"The investment department of an insurance company:","options":["Invests funds for profit","Distributes policy plans","Reviews risk factors","Settles claim disputes"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"Insurers hold large funds from premiums before claims fall due, and the investment department invests these funds in assets such as government securities, shares and property to earn income. Options B, C and D describe marketing, underwriting and claims work respectively."}},{"itemId":"4e801aac-112f-5a36-ab21-fcc8fda28fd2","questionId":"9394b2fa-6aaa-5577-b2ee-cbb185e8d8fe","sourceKey":"bank:INS101:INS-0437","payload":{"prompt":"The role of a reinsurer in insurance is to:","options":["Sell direct to consumers","Back insurers against big losses","Promote insurance offerings","Evade all uncertainties"],"correctOption":1,"section":"Insurance contract and its principles","explanation":"A reinsurer is an insurer for insurance companies: it accepts part of the risks an insurer has written, protecting that insurer against very large or catastrophic losses. Reinsurers do not usually sell direct to the public (option A), and no insurer can avoid all uncertainty (option D)."}},{"itemId":"d70e4f21-d7f5-54de-92a2-9a827d9a648d","questionId":"7da34d23-530a-5e90-8f3d-196145522814","sourceKey":"bank:INS101:INS-0438","payload":{"prompt":"The operation of an insurance company includes:","options":["Risk review and policy issuance","Denying all payouts","Lowering premium costs","Bypassing legal rules"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"Day-to-day insurance operation involves assessing proposals (underwriting) and issuing policies to accepted risks. Denying all payouts (option B) or bypassing the law (option D) would destroy the business, and lowering premiums (option C) is not an operating function in itself."}},{"itemId":"67a1a79e-a7a3-565c-9b25-215163c7db02","questionId":"4f7cdc35-ddab-5593-839e-ae02e22fc870","sourceKey":"bank:INS101:INS-0439","payload":{"prompt":"A stock insurance company is:","options":["Controlled by policyholders","Owned by shareholders","Governed by the state","Run by its staff"],"correctOption":1,"section":"Insurance contract and its principles","explanation":"A stock (proprietary) insurance company is a limited company owned by shareholders who provide its capital and receive its profits as dividends. Option A describes a mutual company, and options C and D describe state-owned and staff-run bodies, which are different forms."}},{"itemId":"6674ca12-1ab9-5f73-9d8b-4845dfb9b55a","questionId":"130fd973-6321-581a-b036-6438224fee21","sourceKey":"bank:INS101:INS-0440","payload":{"prompt":"The financial management of an insurance company involves:","options":["Investing premiums for liquidity","Shunning all investments","Limiting claim payouts","Skipping fiscal planning"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"Financial management in an insurer means investing premium funds wisely while keeping enough liquid assets to pay claims as they fall due. An insurer that shunned investment (option B), cut claims unfairly (option C) or skipped planning (option D) would soon be in trouble."}},{"itemId":"1839f279-07b7-5e53-9a84-932fdd6a28a1","questionId":"0c57c155-4398-5407-8e8d-4720bb14c8f6","sourceKey":"bank:INS101:INS-0441","payload":{"prompt":"The role of an insurance agent is to:","options":["Analyze risk profiles","Offer policies to clients","Disburse claim funds","Fix premium prices"],"correctOption":1,"section":"Insurance contract and its principles","explanation":"An insurance agent represents the insurer and offers its policies to prospective clients, earning commission on the business brought in. Risk analysis (option A) and fixing premium rates (option D) are underwriting and actuarial functions, and paying claims (option C) is done by the claims department."}},{"itemId":"3d829d39-07d4-5720-b63e-6c90028e4f5c","questionId":"96d4420b-66f0-54e2-a5bc-bd2e9f54024e","sourceKey":"bank:INS101:INS-0442","payload":{"prompt":"The operation of an insurance company requires:","options":["Adherence to legal standards","Ignoring all risks","Reducing policy scope","Neglecting policyholders"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"Insurance is a heavily regulated business, so an insurer must operate within the law and the rules of the regulator, such as NAICOM in Nigeria. Ignoring risks, reducing cover or neglecting policyholders (options B, C and D) are the opposite of sound insurance practice."}},{"itemId":"0f8201a6-117a-548a-93fa-82f7d85a1580","questionId":"23493d7d-2e11-5962-b9bf-d6dca62b167b","sourceKey":"bank:INS101:INS-0443","payload":{"prompt":"The loss ratio of an insurance company measures:","options":["Claims paid vs. premiums earned","Premiums vs. investment gains","Staff vs. client numbers","Ad costs vs. policy sales"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"The loss ratio compares the claims (losses) an insurer pays or incurs with the premiums it has earned, showing how much of each naira of premium goes back out as claims. Option B mixes premium with investment income, and options C and D are not insurance performance ratios."}},{"itemId":"d072473c-0413-5d30-8dff-43680ecc9f17","questionId":"d558431d-f8d6-51a9-a816-8bd3bdbfda4c","sourceKey":"bank:INS101:INS-0877","payload":{"prompt":"Find out which of the given statements is incorrect","options":["Accounts department has to monitor cash flow from subordinate offices","Marketing department has to monitor business inflow","Actuarial department is responsible for settling death claims","Underwriting department has to assess risk and determine premium"],"correctOption":2,"section":"Insurance contract and its principles","explanation":"Settling death claims is the work of the claims department, while the actuarial department deals with statistics, premium rating, reserves and the valuation of liabilities. Options A, B and D describe the normal roles of the accounts, marketing and underwriting departments, so they are correct statements."}},{"itemId":"99c7d20f-52c3-5f4e-b66c-8e6f40626040","questionId":"f9705b33-2922-513b-a302-c66167c31126","sourceKey":"bank:INS101:INS-1006","payload":{"prompt":"The two types of insurance companies are","options":["limited and unlimited","proprietary and limited","proprietary and mutual","mutual and unlimited"],"correctOption":2,"section":"Insurance contract and its principles","explanation":"By ownership, insurers are proprietary companies, owned by shareholders who take the profits, or mutual companies, owned by their policyholders. Options A, B and D all use \"limited\" or \"unlimited\", which describe how far members are liable for debts, not a type of insurer."}},{"itemId":"b7e38001-071e-5d26-a4a7-db72b7f1aa17","questionId":"60c4b7e6-066c-541c-942a-51dd314a8dd3","sourceKey":"bank:INS101:INS-1179","payload":{"prompt":"Because the insurer has to pay only if some uncertain future event happens, an insurance contract is described as a","options":["Void contract","Quasi-contract","Contract of sale","Contingent contract"],"correctOption":3,"section":"Insurance contract and its principles","explanation":"A contingent contract is one where performance depends on an uncertain future event, and the insurer's duty to pay depends on a loss actually occurring. Option A is a contract that has no legal effect, which a valid insurance policy does have. Option C transfers ownership of goods, which is not what insurance does."}},{"itemId":"54524483-ad00-558b-bb5d-1ad5905d90fe","questionId":"37f88fa1-e2ff-56e6-ad07-5cecd316c825","sourceKey":"bank:INS101:INS-1211","payload":{"prompt":"Most general (non-life) insurance policies are issued for a period of","options":["Two years","One year","Five years","Ten years"],"correctOption":1,"section":"Insurance contract and its principles","explanation":"General insurance such as fire, motor and burglary is normally written for twelve months and then renewed, which lets the insurer review the risk and premium each year. Options A, C and D are longer terms more typical of life assurance than non-life cover."}},{"itemId":"3d5daad7-b582-552f-a23c-2b27a4f1f785","questionId":"0701abcf-6e83-5481-8bac-24ad964175ac","sourceKey":"bank:INS101:INS-1244","payload":{"prompt":"The scope of protection given under an insurance contract is known as its","options":["Contribution","Premium","Condition","Coverage"],"correctOption":3,"section":"Insurance contract and its principles","explanation":"Coverage describes what the policy protects against, which perils, property and amounts are included. Option A is about sharing a loss between insurers, and B is the price paid. Option C is a rule the insured must follow, not the extent of protection."}},{"itemId":"7b2710b5-9c10-516e-8553-15b9e5287798","questionId":"c5ed4e7b-0e49-58c3-bb01-9637245ecbe9","sourceKey":"bank:INS101:INS-1268","payload":{"prompt":"The period of time for which an insurance policy provides cover is called the","options":["Policy loan","Policy schedule","Grace period","Policy term"],"correctOption":3,"section":"Insurance contract and its principles","explanation":"The policy term is how long the cover lasts, from the start date to the expiry date. Option A is money borrowed against a policy. Option B is the page of policy details, and C is a short extra time allowed to pay a late premium."}},{"itemId":"e8857af5-c58d-5438-bf6d-d930c703be56","questionId":"ede08eb4-348e-5b84-bf48-3b11f26190df","sourceKey":"bank:INS101:I101N1-065","payload":{"prompt":"An applicant in Yaba proposes motor cover, but the insurer replies that it will accept only at a higher premium. In contract terms, the insurer's reply is a","options":["Counter-offer, which cancels the original offer","Acceptance of the original offer","Frustration of the contract","Consideration for the contract"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"Acceptance must be of all the terms; varying them, for example by asking a higher premium, is a counter-offer that cancels the original offer. Treating it as acceptance is wrong because the insurer has not agreed to the applicant's terms as proposed."}},{"itemId":"7ac90382-bbbc-5b33-b6e8-75fc55c894c6","questionId":"b31f8980-b75d-51a7-8346-194c560c62d9","sourceKey":"bank:INS101:I101N1-066","payload":{"prompt":"A contract is discharged because a supervening event, such as the destruction of the subject matter, makes performance impossible. This method of discharge is","options":["Frustration","Performance","Agreement","Breach"],"correctOption":0,"section":"Insurance contract and its principles","explanation":"Frustration happens when a supervening event, such as destruction of the subject matter, makes performance impossible. Breach is different, because it involves one party failing to perform, which lets the other party sue."}},{"itemId":"630e946f-db5b-5916-9280-65c0eb7068b8","questionId":"23e7195e-d17a-58c7-867d-764a250bdefa","sourceKey":"bank:INS101:INS-0001","payload":{"prompt":"Which of these is a disadvantage of functional organizational structure?","options":["Responsive to external changes","Accountability","Monotonous tendency","Related product"],"correctOption":2,"section":"Insurance company organisation and operation","explanation":"In a functional structure, staff are grouped by specialist function, so people tend to do the same narrow tasks over and over, which can make the work monotonous. Option A is not a disadvantage at all, since being responsive to external changes is a strength, and functional structures are usually slow to react. Option B, clear accountability, is normally listed as an advantage, and option D does not describe a weakness of this structure."}},{"itemId":"080a4d43-c776-5176-a710-8c7130c4af48","questionId":"83600aff-8642-5ec8-ae14-8992439d27ab","sourceKey":"bank:INS101:INS-0002","payload":{"prompt":"Which of these is not an advantage of functional organizational structure?","options":["Benefit of similar knowledge","Specialized knowledge","Knowledge limitation","Well defined hierarchy"],"correctOption":2,"section":"Insurance company organisation and operation","explanation":"Knowledge limitation is a weakness, not an advantage: staff in one functional department learn only their own specialty and see little of the wider business. Options A, B and D (shared knowledge within a department, specialised expertise and a clear hierarchy) are the usual benefits of grouping people by function."}},{"itemId":"53c1b10c-46f2-5870-a3eb-04475fd97d5e","questionId":"182e5e5a-aaef-5ada-9ed4-6eb1cd1fe4c6","sourceKey":"bank:INS101:INS-0018","payload":{"prompt":"What serves as the image of an insurer?","options":["Underwriting","Production","Investment","Claim settlement"],"correctOption":3,"section":"Insurance company organisation and operation","explanation":"Claim settlement is the point where the insurer actually keeps its promise, so how fairly and quickly claims are paid shapes how the public sees the company. Underwriting (A), production (B) and investment (C) are important operations too, but customers judge an insurer mainly by its claims service, which is why claims are called its shop window."}},{"itemId":"99fdbdac-5067-51c9-941d-e455e1aef208","questionId":"7d584014-65e9-5acf-b10b-f83aada38f4d","sourceKey":"bank:INS101:INS-0086","payload":{"prompt":"Which of these is not a classification of insurance companies by ownership?","options":["State-owned companies","composite companies","mutual companies","proprietary companies"],"correctOption":1,"section":"Insurance company organisation and operation","explanation":"By ownership, insurers are classed as state-owned, mutual or proprietary companies. Composite describes the range of business a company writes (several classes), not who owns it, so B is the exception. Options A, C and D are all ownership classes."}},{"itemId":"fc1ebc73-7c92-50ff-95cf-0485482010e9","questionId":"6ddfb479-7b50-5162-9f47-5b0d9317cb4d","sourceKey":"bank:INS101:INS-0218","payload":{"prompt":"There are two types of insurance companies namely","options":["Proprietary & Sole proprietorship companies","Proprietary & mutual companies","Friendly and captive insurance companies","Self insurance & proprietary companies"],"correctOption":1,"section":"Insurance company organisation and operation","explanation":"Insurance companies are usually either proprietary companies, owned by shareholders, or mutual companies, owned by their policyholders. A sole proprietorship (A) cannot be an insurance company, and captive or self-insurance arrangements (C, D) are special cases rather than the two main types."}},{"itemId":"a413355a-7d91-562c-bb24-c4ab4305d9af","questionId":"3fde3cbf-2bbf-5c35-8f83-2c1cd0160ee1","sourceKey":"bank:INS101:INS-0222","payload":{"prompt":"Mutual companies are companies owned by the policyholders","options":["False","False, because mutual companies are owned by the government","False, because mutual companies are owned by shareholders","True"],"correctOption":3,"section":"Insurance company organisation and operation","explanation":"A mutual company has no shareholders: it is owned by its policyholders, who share in any surplus. Option C describes a proprietary company, and option B is wrong because government ownership does not make a company mutual."}},{"itemId":"1e8d732b-d64d-5de5-8627-a4bdeeb0d477","questionId":"01e63ef7-7198-5d40-94ba-a8f33c093433","sourceKey":"bank:INS101:INS-0224","payload":{"prompt":"Friendly society is formed by ______","options":["registration","amalgamation","combination","computation"],"correctOption":0,"section":"Insurance company organisation and operation","explanation":"A friendly society comes into existence by being registered under the law that governs such societies. Amalgamation (B) and combination (C) describe merging bodies that already exist, and computation (D) simply means calculation, so none of them forms a friendly society."}},{"itemId":"2561e763-15b6-50bf-a2f2-e97a38428e28","questionId":"12b85a51-80f1-5b6e-8ee0-dd4b59a7a59d","sourceKey":"bank:INS101:INS-0229","payload":{"prompt":"______ are formed by registration under the Friendly Societies Act to transact industrial life assurance.","options":["friendly societies","proprietary societies","amicable society","solvency society"],"correctOption":0,"section":"Insurance company organisation and operation","explanation":"Friendly societies are mutual bodies formed by registration under the Friendly Societies Act, and many transact industrial life assurance for working people. A proprietary company (B) is owned by shareholders, and the amicable (C) and solvency (D) societies do not match this description."}},{"itemId":"213aab67-6117-579e-84ed-df6a046c2931","questionId":"00afd4f8-7758-541d-ba2b-83b4a84348d8","sourceKey":"bank:INS101:INS-1059","payload":{"prompt":"The insurance company that distributes its surplus profit to its shareholders is called","options":["a captive company","a mutual company","a Lloyd's syndicate","a proprietary company"],"correctOption":3,"section":"Insurance company organisation and operation","explanation":"A proprietary company is owned by shareholders who provide its capital and receive its profits as dividends. A mutual company (option B) has no shareholders; it is owned by its policyholders, who share any surplus through lower premiums or bonuses."}},{"itemId":"352b30c3-f376-5161-8d20-abd8800f5653","questionId":"3f4aaa30-9f0f-5b62-ab2e-3810bdd30329","sourceKey":"bank:INS101:I101N1-067","payload":{"prompt":"The system that sets out how activities such as rules, roles and responsibilities are directed toward an organisation's goals, and how information flows, is called","options":["Strategic plan","Organisational structure","Organisational culture","Insurance market"],"correctOption":1,"section":"Insurance company organisation and operation","explanation":"Organisational structure is the system setting out how rules, roles and responsibilities are directed toward goals and how information flows, usually drawn as a pyramid. Organisational culture is about shared values and behaviour, not the formal arrangement of roles."}},{"itemId":"c800b588-b59c-5465-b68d-4e278013d2dc","questionId":"967da9ad-47d4-5cc8-b07d-4f3c2bfe7f1e","sourceKey":"bank:INS101:I101N1-068","payload":{"prompt":"Which of the following is NOT one of the four key elements of organisational structure?","options":["Hierarchy of authority","Common purpose","Product diversification","Coordinated effort"],"correctOption":2,"section":"Insurance company organisation and operation","explanation":"The four key elements are common purpose, coordinated effort, specialisation and division of labour, and hierarchy of authority. Product diversification is a business strategy, not an element of structure."}},{"itemId":"62edfe40-3ff7-5c49-8757-8dec5086945b","questionId":"9e0b1111-6975-5f01-88bb-cc26947299b3","sourceKey":"bank:INS101:I101N1-069","payload":{"prompt":"Which element of organisational structure is described as arguably a manager's most important responsibility?","options":["Coordinated effort","Specialisation and division of labour","Hierarchy of authority","Common purpose"],"correctOption":0,"section":"Insurance company organisation and operation","explanation":"Coordinated effort is described as arguably a manager's most important responsibility. Common purpose is about the strategy and mission that managers communicate, which is a different element."}},{"itemId":"cc0b5d13-bc0c-5105-88a4-784bf74d9e8c","questionId":"93cc474d-a8a8-56be-95c6-ff10c4eaa28e","sourceKey":"bank:INS101:I101N1-070","payload":{"prompt":"The idea that a worker's skill improves with repetition and that narrow jobs are cheap to recruit and train for describes which element of structure?","options":["Specialisation and division of labour","Coordinated effort","Hierarchy of authority","Common purpose"],"correctOption":0,"section":"Insurance company organisation and operation","explanation":"Specialisation and division of labour rests on skill improving with repetition and narrow jobs being cheap to recruit and train for. Hierarchy of authority is about the chain of command, not how tasks are split."}},{"itemId":"e07cc05f-3483-5fc7-8f0b-7c28c9064e7a","questionId":"92e4119f-f2c8-5652-9fd2-85c1e8d2b361","sourceKey":"bank:INS101:I101N1-071","payload":{"prompt":"The element of organisational structure that shows the chain of command, that is, who reports to whom, is","options":["Hierarchy of authority","Division of labour","Coordinated effort","Common purpose"],"correctOption":0,"section":"Insurance company organisation and operation","explanation":"Hierarchy of authority sets out the chain of command and who reports to whom. Division of labour deals with splitting work into specialised tasks, not reporting lines."}},{"itemId":"bdcc85d0-0776-53a9-aba3-0f31915024b4","questionId":"6d7885c9-51df-55a7-b379-69eb7a82cedc","sourceKey":"bank:INS101:I101N1-072","payload":{"prompt":"The element of organisational structure covering the strategy, mission, values and objectives that managers communicate to staff is","options":["Common purpose","Coordinated effort","Hierarchy of authority","Specialisation"],"correctOption":0,"section":"Insurance company organisation and operation","explanation":"Common purpose covers strategy, mission, values and objectives, communicated by managers. Coordinated effort is about getting people to work together, which is a separate element."}},{"itemId":"894666ed-f7b7-5091-a188-66059fddcf21","questionId":"2b441dd3-4e23-5cdf-b2fa-a52b22319f9e","sourceKey":"bank:INS101:I101N1-073","payload":{"prompt":"An insurance company in Lagos finds that its marketing and sales units overlap and changes its structure to fix this. Which factor in designing a structure does this illustrate?","options":["Determination of the structure","Clear definition of objectives","Revision of the structure","Identification and grouping of activities"],"correctOption":2,"section":"Insurance company organisation and operation","explanation":"Revision of the structure means adjusting it when problems such as overlap between marketing and sales appear, which is why structures should be flexible. Determination of the structure is the earlier step of setting ranks and departments in the first place."}},{"itemId":"4bd713da-7a28-5d66-9050-324528a4a487","questionId":"e53f832e-e3d1-5018-a3b6-346551a41a3a","sourceKey":"bank:INS101:I101N1-074","payload":{"prompt":"Grouping an insurer's work into product design, underwriting, marketing, accounting and HR is an example of which factor in designing a structure?","options":["Clear definition of objectives","Identification and grouping of activities","Hierarchy of authority","Revision of the structure"],"correctOption":1,"section":"Insurance company organisation and operation","explanation":"Identification and grouping of activities means sorting the work into units such as underwriting, marketing and accounting. Revision of the structure comes later, when an existing structure is adjusted."}},{"itemId":"ead088bd-be6b-560f-8dbd-5c5af591f0c7","questionId":"7ebf4dc0-395b-559c-b5ee-8f0a5edbfe23","sourceKey":"bank:INS101:I101N1-075","payload":{"prompt":"Which of the following is the first of the four factors in designing an organisational structure?","options":["Revision of the structure","Clear definition of objectives","Determination of the structure","Identification and grouping of activities"],"correctOption":1,"section":"Insurance company organisation and operation","explanation":"Designing a structure starts with a clear definition of objectives, followed by identifying and grouping activities, determining the structure, and revising it. Revision of the structure is the last factor, not the first."}},{"itemId":"06a7b6e0-dcac-512a-9881-d0f1ac264531","questionId":"79d082e2-4872-5ee7-b8e0-1847c1577f75","sourceKey":"bank:INS101:I101N1-076","payload":{"prompt":"A structure in which staff are grouped by skill or function and each department is managed separately, and which most firms start with, is the","options":["Functional structure","Product structure","Divisional structure","Geographic structure"],"correctOption":0,"section":"Insurance company organisation and operation","explanation":"In a functional structure staff are grouped by skill or function and each department is managed separately; most firms start this way. A divisional structure gives each division all its own functions, which is the opposite approach."}},{"itemId":"beed979b-0ba1-5479-8d42-3e3193e2d111","questionId":"0eea9a03-d026-57c8-9551-b5d439fd1229","sourceKey":"bank:INS101:I101N1-077","payload":{"prompt":"Staff of an insurer in Ikeja that groups its people by skill into separate departments keep clashing over how performance is appraised and who gets promoted. This problem is a known weakness of which structure?","options":["Product structure","Geographic structure","Divisional structure","Functional structure"],"correctOption":3,"section":"Insurance company organisation and operation","explanation":"Possible conflict over appraisal or promotion is a disadvantage of the functional structure, where staff are grouped by skill or function. Product and geographic structures are forms of the divisional structure, whose own weaknesses include unhealthy competition and poor communication between divisions."}},{"itemId":"46bbc51a-b265-5782-aa02-e524da7cb04c","questionId":"e942a3df-958a-5baf-af70-60ba9c794dfa","sourceKey":"bank:INS101:I101N1-078","payload":{"prompt":"A structure in which each unit has all the resources and functions it needs, including its own finance, IT and marketing, is a","options":["Specialist structure","Functional structure","Divisional structure","Hierarchy of authority"],"correctOption":2,"section":"Insurance company organisation and operation","explanation":"A divisional structure gives each division its own finance, IT and marketing, so it can operate almost on its own. A functional structure groups staff by function across the whole firm instead."}},{"itemId":"156e2593-e4d0-55d1-9e9c-a8593cc2ce3e","questionId":"8264347a-d83b-5ebd-9e48-ba8047f09592","sourceKey":"bank:INS101:I101N1-079","payload":{"prompt":"An insurer sets up separate Lagos, Abuja and Port Harcourt divisions, each with its own finance, IT and marketing. This is a divisional structure based on","options":["Skill","Product","Function","Geography"],"correctOption":3,"section":"Insurance company organisation and operation","explanation":"Divisions can be by product or by geography, and dividing the business by regions such as Lagos, Abuja and Port Harcourt is geographic. Grouping by function or skill would be a functional structure, not divisional."}},{"itemId":"1d1faae0-c9c1-5747-ac59-83f7cc00f30c","questionId":"db8de0e5-93dc-5032-b6d0-d9d97fec755c","sourceKey":"bank:INS101:I101N1-080","payload":{"prompt":"Which advantage of a divisional structure means that each division's profit or loss can be clearly seen?","options":["Accountability","Teamwork","Leadership","Responsiveness to external changes"],"correctOption":0,"section":"Insurance company organisation and operation","explanation":"Accountability is the advantage that each division's profit or loss can be seen. Responsiveness is a separate advantage about reacting to external changes, not measuring results."}},{"itemId":"1898ce3b-ac38-50b3-b2a3-012437a1a017","questionId":"b7e4a76e-dc25-5aed-bbee-c37297996e7e","sourceKey":"bank:INS101:I101N1-081","payload":{"prompt":"Because every division keeps its own finance, IT and marketing units, a divisional structure tends to suffer from","options":["Monotonous tendency","Knowledge limitation","Lost economies of scale","Rigid structure"],"correctOption":2,"section":"Insurance company organisation and operation","explanation":"When each division duplicates functions such as finance and IT, the firm loses economies of scale, which is a disadvantage of the divisional structure. Monotonous tendency, knowledge limitation and a rigid structure are disadvantages of the functional structure instead."}},{"itemId":"22e3c97b-d3cd-5563-8d44-0ce32959e1f3","questionId":"12b9a4c6-487f-56b9-aa6e-4dd9d7c729f4","sourceKey":"bank:INS101:I101N1-082","payload":{"prompt":"Which of the following is NOT a disadvantage of a divisional structure?","options":["Related products are hard to integrate","Unhealthy competition between divisions","Poor communication between divisions","A well-defined hierarchy"],"correctOption":3,"section":"Insurance company organisation and operation","explanation":"A well-defined hierarchy is an advantage of the functional structure, not a disadvantage of the divisional one. Unhealthy competition, poor communication and difficulty integrating related products are real divisional disadvantages."}},{"itemId":"1de0de12-44d8-5ee7-a561-092a0c2b6af0","questionId":"d48d8090-ade6-5c1e-8015-29a02e4db30a","sourceKey":"bank:INS101:I101N1-083","payload":{"prompt":"Why is a divisional structure usually not suitable for a small insurance agency?","options":["It is not possible for small organisations and duplicates work","It removes all accountability","It gives too much specialised knowledge","It creates a monotonous tendency"],"correctOption":0,"section":"Insurance company organisation and operation","explanation":"A divisional structure needs each unit to have its own functions, which is not possible for small organisations and duplicates work. Monotonous tendency is a disadvantage of the functional structure, not the divisional one."}},{"itemId":"2e0b2e8c-62a9-5446-8c82-2dfea43d89d6","questionId":"bbc1de2e-16ad-5945-b7b3-3dc8630c290f","sourceKey":"bank:INS101:I101N1-084","payload":{"prompt":"NAICOM regulations require the board of directors of an insurance company to have","options":["Not less than five and not more than ten members","Not less than seven and not more than fifteen members","Not less than three and not more than seven members","Not less than ten and not more than twenty members"],"correctOption":1,"section":"Insurance company organisation and operation","explanation":"NAICOM regulations require the board to have not less than seven and not more than fifteen members. The other ranges may look reasonable but do not match the NAICOM requirement."}},{"itemId":"ccdf5a51-b567-5495-9067-25f5f16ef34b","questionId":"25c09212-5e1d-5c20-8525-bb1c46a0ccfd","sourceKey":"bank:INS101:I101N1-085","payload":{"prompt":"In an insurance company, which body sets policy, approves major decisions and oversees management?","options":["The customer service department","The claims department","The board of directors","The underwriting department"],"correctOption":2,"section":"Insurance company organisation and operation","explanation":"The board of directors sets policy, approves major decisions and oversees management. The departments carry out the work day to day under that oversight rather than setting company policy."}},{"itemId":"98beb1fd-4d4c-51f3-8ce6-aa762465c073","questionId":"67d493e1-73ea-51fb-9e73-7cfce2b19a8e","sourceKey":"bank:INS101:I101N1-086","payload":{"prompt":"Which executive in an insurance company is the highest-ranking officer, responsible for strategy and for representing the company to regulators and investors?","options":["Head of underwriting","Chief Operating Officer (COO)","Chief Financial Officer (CFO)","Chief Executive Officer (CEO)"],"correctOption":3,"section":"Insurance company organisation and operation","explanation":"The CEO is the highest-ranking executive, sets strategy and represents the company to regulators and investors. The COO handles daily operations rather than representing the company externally."}},{"itemId":"7430c9ce-e353-513f-aba7-5a7f5ba4e9b0","questionId":"3c2579fa-40a4-5887-89bf-ea628a83298e","sourceKey":"bank:INS101:I101N1-087","payload":{"prompt":"Which executive in an insurance company is responsible for daily operations?","options":["Chief Financial Officer (CFO)","Chief Executive Officer (CEO)","Chairman of the board","Chief Operating Officer (COO)"],"correctOption":3,"section":"Insurance company organisation and operation","explanation":"The COO is responsible for the company's daily operations. The CEO focuses on strategy and representing the company, while the CFO handles finance."}},{"itemId":"f7a61413-ef73-5c79-bfc0-ebcad58ce0d1","questionId":"fd33e1d0-dfca-553b-a296-5ef8953e1baa","sourceKey":"bank:INS101:I101N1-088","payload":{"prompt":"Which executive in an insurance company is responsible for financial planning, risk management, record-keeping and reporting?","options":["Head of claims","Chief Executive Officer (CEO)","Chief Operating Officer (COO)","Chief Financial Officer (CFO)"],"correctOption":3,"section":"Insurance company organisation and operation","explanation":"The CFO handles financial planning, risk management, record-keeping and reporting. The COO runs daily operations and does not carry these financial responsibilities."}},{"itemId":"4cffafed-6799-593d-aebc-7d800b1e16a5","questionId":"1c3faeed-3a35-5f78-b109-af679f38d6d3","sourceKey":"bank:INS101:I101N1-089","payload":{"prompt":"A proposal to insure a warehouse in Apapa is examined to evaluate the risk, set the premium and decide whether to accept or reject it. Which department does this?","options":["Claims department","Underwriting department","Legal and compliance department","Customer service department"],"correctOption":1,"section":"Insurance company organisation and operation","explanation":"The underwriting department evaluates risks, sets premiums and accepts or rejects proposals. The claims department deals with claims after a loss, not with deciding whether to accept a new risk."}},{"itemId":"5e24e8c1-56b8-5f7c-b1e5-336980be55a8","questionId":"1629206c-3ace-5d48-8d6f-0adec65ac07c","sourceKey":"bank:INS101:I101N1-090","payload":{"prompt":"Which department of an insurance company makes sure the company follows NAICOM rules and other laws?","options":["Legal and compliance department","Underwriting department","Sales and marketing department","Actuarial department"],"correctOption":0,"section":"Insurance company organisation and operation","explanation":"The legal and compliance department makes sure the company keeps to the law and regulatory rules. The actuarial department builds statistical models for risk and rates, which is a technical rather than a legal role."}},{"itemId":"2b84e41b-bcae-5d01-a4b2-d55a171ad130","questionId":"5a96ba85-d5f0-535a-9e95-9b4212a08c4e","sourceKey":"bank:INS101:I101N1-091","payload":{"prompt":"Which of the following is NOT one of the seven departments of an insurance company?","options":["Actuarial department","Production and manufacturing department","Customer service department","Finance and investment department"],"correctOption":1,"section":"Insurance company organisation and operation","explanation":"The seven departments are underwriting, claims, actuarial, finance and investment, sales and marketing, customer service, and legal and compliance. An insurer sells a service, so a production and manufacturing department is not one of them."}},{"itemId":"078c2516-9455-5cab-b9dc-1397cd54b059","questionId":"3b5deed9-f2fb-53c9-9937-23dd9af9f51a","sourceKey":"bank:INS101:I101N1-092","payload":{"prompt":"An insurer in Lagos places part of its premium income in bonds and equities. Which insurance company operation is this?","options":["Claims management","Policy issuance and administration","Premium collection","Investment management"],"correctOption":3,"section":"Insurance company organisation and operation","explanation":"Investment management is the operation of placing funds in assets such as bonds and equities. Premium collection is about receiving the money from policyholders, not investing it afterwards."}},{"itemId":"bf193dc5-d745-5504-8162-8d8c4d1ca10f","questionId":"ad8ff8d3-a10d-56d7-bc16-be087bd820f8","sourceKey":"bank:INS101:I101N1-093","payload":{"prompt":"An insurance broker acts on behalf of","options":["The reinsurer, and is paid by the insurer","The insurer, and is paid by the insured","NAICOM, and is paid by the government","The insured, but is paid by the insurer"],"correctOption":3,"section":"Insurance company organisation and operation","explanation":"A broker acts for the insured, yet is paid by the insurer. Saying the broker acts for the insurer reverses the relationship and describes the insurer's own agents more than a broker."}},{"itemId":"71bae228-3c5e-50f9-a972-bc39bda7aaef","questionId":"0ca7bf35-2cfd-513a-8c01-228f3da6f0ad","sourceKey":"bank:INS101:I101N1-094","payload":{"prompt":"Which insurance intermediary is regarded as the most important?","options":["The insurance broker","The loss adjuster","The surveyor","The actuary"],"correctOption":0,"section":"Insurance company organisation and operation","explanation":"The insurance broker is regarded as the most important intermediary, acting for the insured in placing cover. Loss adjusters and surveyors provide supporting services and are not the main intermediaries between buyers and insurers."}},{"itemId":"4af2f753-1008-51ea-9895-f3b7e17130f6","questionId":"1bb0012d-cf98-52df-9739-2f646a3a65ea","sourceKey":"bank:INS101:I101N1-095","payload":{"prompt":"Which of the following is NOT a component of the insurance market?","options":["Retailers","Sellers","Buyers","Ancillary service providers"],"correctOption":0,"section":"Insurance company organisation and operation","explanation":"The insurance market is made up of buyers, sellers and ancillary service providers. Retailers are not listed as a component of the insurance market."}},{"itemId":"8283cf0a-786a-57af-ab20-e1762e5fd7b4","questionId":"57dd17b5-ed63-5e5f-93a1-c587f3eff1e3","sourceKey":"bank:INS101:I101N1-096","payload":{"prompt":"An insurance company that transacts several classes of insurance business, rather than just one, is called a","options":["Captive company","Specialist company","Composite company","Mutual company"],"correctOption":2,"section":"Insurance company organisation and operation","explanation":"A composite company transacts several classes of business, while a specialist company handles only one. Mutual describes ownership by policyholders, which is a different way of classifying insurers."}},{"itemId":"ac6e33c5-7385-5d17-b879-31742d5a24f3","questionId":"8e1fe041-6588-525a-bc74-cab3c068a23e","sourceKey":"bank:INS101:I101N1-097","payload":{"prompt":"An insurer in Lagos paid claims of N45 million in a year in which its premiums earned were N60 million. What is its loss ratio?","options":["133%","75%","25%","45%"],"correctOption":1,"section":"Insurance company organisation and operation","explanation":"The loss ratio is claims paid divided by premiums earned, so N45m / N60m = 0.75, or 75%. Dividing the other way round, N60m / N45m, gives about 133%, which inverts the ratio."}},{"itemId":"54173d0c-b18d-5870-ba45-b78035377b5a","questionId":"a811741b-802d-55bb-bd37-29f5b0e067dc","sourceKey":"bank:INS101:INS-0008","payload":{"prompt":"The primary purpose of government regulation of insurance is to","options":["raise revenue through premium taxes","prevent artificially high premiums","guarantee fair contracts at fair prices from sound insurers","all of the above"],"correctOption":2,"section":"Insurance regulation and legislation in Nigeria","explanation":"Insurance is regulated mainly to protect the public: to make sure people get fair contracts at fair prices from insurers that are financially sound enough to pay claims. Option B is one part of that aim, but C states the full purpose. Raising revenue (option A) is a by-product of premium taxes, not the reason for regulation, so D cannot be right."}},{"itemId":"cc3b6400-3c8e-5f91-ace1-e84fd836f6fe","questionId":"09adeeb0-c46a-5be3-8203-c50f4d464523","sourceKey":"bank:INS101:INS-0137","payload":{"prompt":"Which of these is not reason for insurance regulation?","options":["to prevent fraud","to donate to charity","to ensure financial solvency","to ensure competence"],"correctOption":1,"section":"Insurance regulation and legislation in Nigeria","explanation":"Insurance is regulated to protect the public, for example by preventing fraud, keeping insurers solvent and making sure they are run competently. Donating to charity has nothing to do with regulation, so B is the odd one out. Options A, C and D are all genuine reasons."}},{"itemId":"1352f96f-e010-5001-96a5-e6a3539ab8ba","questionId":"9138c8df-ff61-5e4b-98c0-eb1618c9b1db","sourceKey":"bank:INS101:INS-0221","payload":{"prompt":"Modern insurance was brought to Nigeria from Great Britain","options":["False","False, because it came from the United States","True","False, because modern insurance began in Nigeria as a local invention"],"correctOption":2,"section":"Insurance regulation and legislation in Nigeria","explanation":"Modern insurance came to Nigeria from Great Britain, through British trading companies and the agencies of British insurers in the colonial era. Options D and B are wrong because it was neither a local invention nor an American import."}},{"itemId":"896ab129-fb66-5fd5-8323-5b0da59ab7ae","questionId":"77f1fe4f-7dd0-599c-8777-3c504dda0eff","sourceKey":"bank:INS101:INS-0234","payload":{"prompt":"The first act set up for insurance regulation in Nigeria is the Insurance Act of 1976","options":["False","True, because there was no insurance law in Nigeria before 1976","True","True, because the 1976 Act created NAICOM"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"The first law made specifically to regulate insurance in Nigeria was the Insurance Companies Act of 1961, so the 1976 Act came later. Option B is wrong for the same reason, and option D is wrong because NAICOM was established in 1997, not by the 1976 Act."}},{"itemId":"cc1b32f9-0cae-50ea-bf22-028b1b0ad746","questionId":"77d75c17-001f-591b-9ab7-abb74eee7716","sourceKey":"bank:INS101:INS-0238","payload":{"prompt":"Recapitalization of insurance companies was effected in 2008","options":["False","True","True, because Nigerian insurers have never been recapitalised","True, because recapitalisation was announced and completed in 2008"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"The major recapitalisation of Nigerian insurance companies was announced in 2005, with a deadline in early 2007, so it was not effected in 2008. Option D gets the year wrong, and option C is clearly false because the exercise did take place and greatly reduced the number of insurers."}},{"itemId":"3dacae5c-35a8-5806-a21f-152fc5a5bfbe","questionId":"33f243e3-0bcb-5297-aced-6381d84a6751","sourceKey":"bank:INS101:INS-0239","payload":{"prompt":"The regulatory body of insurance business in Nigeria is NAICOM","options":["False, because the regulator is the Central Bank of Nigeria","False","True","False, because the regulator is the CIIN"],"correctOption":2,"section":"Insurance regulation and legislation in Nigeria","explanation":"NAICOM, the National Insurance Commission, is the body that regulates and supervises insurance business in Nigeria. The Central Bank (option A) regulates banks, and the CIIN (option D) is the professional institute for insurance practitioners, not the regulator."}},{"itemId":"5951fea7-20ec-58c3-bca0-56dfcd35e44e","questionId":"7b079c43-bf6d-5781-8f2f-1d51d86d0f5a","sourceKey":"bank:INS101:INS-0244","payload":{"prompt":"Premiums are regulated by the Chartered Insurance Institute of Nigeria (CIIN)","options":["True, because the CIIN is Nigeria's insurance regulator","True, because the CIIN fixes all premium rates by law","False","True"],"correctOption":2,"section":"Insurance regulation and legislation in Nigeria","explanation":"The CIIN is the professional body that trains and examines insurance practitioners, while regulating insurance business, including premium matters, is the job of NAICOM. Options A, B and D are wrong because they treat a professional institute as if it were the regulator."}},{"itemId":"77640514-8e8f-5a84-b875-4f19ac8e2309","questionId":"37b29471-2932-552c-a9b1-5effa6dd4c01","sourceKey":"bank:INS101:INS-0245","payload":{"prompt":"The regulatory body is responsible for registering new companies","options":["False, because new insurers are registered by the CIIN","False, because insurers need no registration in Nigeria","True","False"],"correctOption":2,"section":"Insurance regulation and legislation in Nigeria","explanation":"NAICOM, the regulator, registers and licenses new insurance companies before they can transact business in Nigeria. Option A is wrong because the CIIN is a professional institute, and option B is wrong because operating without registration is not allowed."}},{"itemId":"01f27049-dc7f-5b31-b4a5-d591dd312bf0","questionId":"f2844cc1-40d6-51db-bd7f-f7ed92a7ddf7","sourceKey":"bank:INS101:INS-0248","payload":{"prompt":"One reason of the regulation of insurance business is prevent insolvency","options":["False","False, because insolvent insurers are not a concern of regulators","True","False, because regulation is only meant to raise government revenue"],"correctOption":2,"section":"Insurance regulation and legislation in Nigeria","explanation":"Regulators aim to keep insurers solvent so that they can pay policyholders' claims when losses happen. Options D and B are wrong because protecting policyholders from insurer failure is a central goal of regulation."}},{"itemId":"b4e7205d-8937-50a1-a19b-e368779830a1","questionId":"7d9226a5-e56b-595f-965c-8b8ec7167f0f","sourceKey":"bank:INS101:INS-0249","payload":{"prompt":"The National Insurance Commission was established in 2003","options":["False","True, because NAICOM was created by the Insurance Act 2003","True, because NAICOM was created when the CIIN was founded","True"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"NAICOM was established in 1997 by the National Insurance Commission Decree, before the Insurance Act 2003 was passed. Options B, C and D are wrong because they give the wrong origin and date for the commission."}},{"itemId":"e73b1f3c-848b-5b6d-973e-a9f6ec4f474a","questionId":"cc26b269-63d7-587f-b57a-443dfe900685","sourceKey":"bank:INS101:INS-0256","payload":{"prompt":"Insurance business is regulated in order to protect the insurers","options":["True, because regulation exists mainly to protect insurers' profits","False","True, because policyholders are not considered in regulation","True"],"correctOption":1,"section":"Insurance regulation and legislation in Nigeria","explanation":"Insurance is regulated mainly to protect policyholders and the public, for example by keeping insurers solvent and treating customers fairly. Options A and C are wrong because protecting insurers' profits is not the purpose of regulation."}},{"itemId":"75519c0a-5616-5a4b-a592-2cdcdc179d29","questionId":"10a737b0-c09f-5232-9b98-6d805d92e022","sourceKey":"bank:INS101:INS-0258","payload":{"prompt":"Insurance companies do not have to maintain other financial reserves aside from its capital reserves","options":["True, because insurers only need to keep their paid-up capital","False","True, because reserves are optional for insurers","True"],"correctOption":1,"section":"Insurance regulation and legislation in Nigeria","explanation":"Apart from capital, insurers must keep technical reserves, such as reserves for unexpired risks and outstanding claims, so that they can meet future claims. Options A and C are wrong because these reserves are required, not optional."}},{"itemId":"635f766f-3345-5c67-af74-60a7e5f614d6","questionId":"cfa0271c-031d-5fdf-8fe9-be26c904b003","sourceKey":"bank:INS101:INS-0268","payload":{"prompt":"All of the following are reasons for regulating Insurance EXCEPT","options":["protect insurance companies","maintain solvency level","premium regulation","make insurance available"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"Insurance is regulated mainly to protect policyholders and the public, not to protect insurance companies (A). Keeping insurers solvent (B), making sure premiums are reasonable (C) and making insurance available (D) are all genuine reasons for regulation."}},{"itemId":"fa6f836c-1844-5501-89a7-1dd9765420a6","questionId":"e0fa467b-68c3-5441-ac0e-7c276459c659","sourceKey":"bank:INS101:INS-0273","payload":{"prompt":"The National Insurance Commission (NAICOM) is responsible and reports directly to","options":["minister of finance","governor of the central bank","president","none of the above"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"NAICOM operates under the supervision of the Federal Ministry of Finance, so it reports to the Minister of Finance. The Central Bank governor (B) oversees banks, not insurers, and the President (C) does not directly supervise the commission."}},{"itemId":"873c3e90-9e83-5ddc-bf18-3a924d9a4021","questionId":"df4d0afa-c107-5bfc-ad71-61ab9af04282","sourceKey":"bank:INS101:INS-0296","payload":{"prompt":"Only the __________ can approve the establishment of an insurance company.","options":["The President","Chartered Insurance Institute of Nigeria (CIIN)","The Commission (NAICOM)","Security and Exchange Commission (SEC)"],"correctOption":2,"section":"Insurance regulation and legislation in Nigeria","explanation":"In Nigeria, the National Insurance Commission (NAICOM) is the regulator that registers and licenses insurance companies before they can operate. Option B, CIIN, is the professional body for insurance practitioners, not a licensing authority. Option D, SEC, regulates the capital market, and option A, the President, does not license insurers."}},{"itemId":"269d2ac2-611e-5050-b60b-d6c2a9d416a9","questionId":"6ea27ac5-14fe-5cc0-b93d-9d16511e5356","sourceKey":"bank:INS101:INS-0346","payload":{"prompt":"The technical regulatory term for the required difference between an insurer's assets and liabilities is the","options":["free asset ratio","profit margin","reinsurance retention ratio","solvency margin"],"correctOption":3,"section":"Insurance regulation and legislation in Nigeria","explanation":"The solvency margin is the minimum amount by which an insurer's assets must exceed its liabilities, set by the regulator to make sure claims can be paid. Option A is a related ratio but not the regulatory term for this required gap. Options B and C measure profitability and how much risk is kept, not solvency."}},{"itemId":"d421c257-7565-5d9a-84d6-9d816d8e1e69","questionId":"056bc84f-3070-5d4a-8c0b-13eaccc1f9ee","sourceKey":"bank:INS101:INS-0349","payload":{"prompt":"Solvency margin is necessary for the following reasons","options":["to ensure that claims will be paid as at when due","protect insured from financial insecurity","prevent social and economic costs associated with insolvency","all of the above"],"correctOption":3,"section":"Insurance regulation and legislation in Nigeria","explanation":"A solvency margin makes sure an insurer can pay claims as they fall due, protects policyholders from losing their cover, and avoids the wider social and economic costs when an insurer collapses. Since A, B and C are all valid reasons, 'all of the above' is correct."}},{"itemId":"99376699-4e7d-56d2-bc2f-11947b9be956","questionId":"852fb5b2-24d2-51d4-80d8-0848efd5cfd6","sourceKey":"bank:INS101:INS-0449","payload":{"prompt":"The Insurance Act 2003 in Nigeria provides:","options":["Rules for insurance practices","Factory operation laws","Marketing guidelines","Educational policies"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"The Insurance Act 2003 is the main law governing insurance business in Nigeria, covering matters such as registration of insurers, capital, and the conduct of insurance practice. It does not govern factories, general marketing or education (options B, C and D)."}},{"itemId":"adc32833-d19a-5bf5-9c16-d836a8d06d6b","questionId":"6e3f3787-d943-5853-911d-bb44fe59c6c0","sourceKey":"bank:INS101:INS-0450","payload":{"prompt":"The primary goal of insurance regulation in Nigeria is to:","options":["Safeguard clients and stability","Boost premium rates","Shrink coverage options","Evade fiscal strategies"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"Insurance regulation exists mainly to protect policyholders and keep the insurance market financially sound and stable. Raising premiums, shrinking cover or avoiding financial planning (options B, C and D) would harm the public, not protect it."}},{"itemId":"6d5a4913-29fc-5258-8323-49d27d38e4e6","questionId":"6cfc4f2b-b271-50e2-a766-3d474258f8a2","sourceKey":"bank:INS101:INS-0452","payload":{"prompt":"NAICOM in Nigeria is responsible for:","options":["Approving insurer licenses","Producing goods","Promoting products","Staffing companies"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"One of NAICOM's key duties is to license (register) insurers and other operators and supervise them afterwards. Producing goods, promoting products and staffing companies (options B, C and D) are not regulatory functions."}},{"itemId":"65a02f98-fe64-5d34-a69f-99fe3c0d000c","questionId":"741625fa-60c6-5059-8b11-fe63e681c7b4","sourceKey":"bank:INS101:INS-0453","payload":{"prompt":"The overview of finance in insurance includes:","options":["Insurance as long-term funding","Skipping financial foresight","Cutting investment plans","Abolishing premiums"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"Insurers, especially life offices, hold premiums for long periods, so they are an important source of long-term funds for government and business through their investments. Options B, C and D describe the opposite of how insurance supports finance."}},{"itemId":"2cb3f924-e4d0-5fb4-a364-0f1313458eb3","questionId":"798308d2-e9a0-5310-a5fe-7b184acf2cab","sourceKey":"bank:INS101:INS-0455","payload":{"prompt":"Insurance regulations in Nigeria require companies to:","options":["Hold sufficient capital reserves","Deny all payouts","Slash premium rates","Overlook clients"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"Regulators require insurers to keep adequate capital and reserves so that they can pay claims even when losses are high. Denying payouts, slashing rates or ignoring clients (options B, C and D) would weaken an insurer and are not legal requirements."}},{"itemId":"d67bcd3f-5bf0-5258-bdb7-652d1916ab9d","questionId":"daaf2064-3652-53da-8a10-1a6afcd75180","sourceKey":"bank:INS101:INS-0456","payload":{"prompt":"The history of insurance regulations shows a focus on:","options":["Consumer protection and equity","Raising premium costs","Limiting policy scope","Undermining stability"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"Insurance regulation has developed over time largely to protect consumers and ensure they are treated fairly. Raising costs, limiting cover and undermining stability (options B, C and D) are the problems regulation tries to prevent."}},{"itemId":"f65cbcfe-6e8a-5e8d-90f2-61ab06b010ba","questionId":"4fdf7ea7-af12-599b-a97a-e30454b5703d","sourceKey":"bank:INS101:INS-0458","payload":{"prompt":"Current legislation in Nigeria requires insurance companies to:","options":["Follow NAICOM standards","Ignore all regulations","Scale back operations","Skip fiscal planning"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"Insurers in Nigeria must comply with the standards, guidelines and directives issued by NAICOM under the law. Ignoring regulations (option B) is an offence, and scaling back operations or skipping financial planning (options C and D) are not legal requirements."}},{"itemId":"c8782ca9-80c8-5f68-8238-a81a00470623","questionId":"da5ebe12-f9dc-5e01-9b85-895b33028b2d","sourceKey":"bank:INS101:INS-0459","payload":{"prompt":"The overview of finance in insurance highlights:","options":["Insurance aiding economic growth","Avoiding investment roles","Cutting premium levels","Wiping out risks"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"Insurance supports economic growth by protecting businesses against losses and by investing the funds it collects into the economy. Options B, C and D are wrong because insurers are major investors and cannot wipe out risk, only transfer and spread it."}},{"itemId":"2f2aca15-7378-56a0-9f48-1cbee1cc7370","questionId":"84574c7e-dab7-5b6e-bc29-04a3f7744892","sourceKey":"bank:INS101:INS-0461","payload":{"prompt":"Insurance regulations in Nigeria aim to:","options":["Promote clarity and accountability","Hike premium charges","Shrink coverage areas","Dodge financial foresight"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"Regulation aims to make insurers transparent and accountable to policyholders and the regulator, for example through proper records and returns. Hiking premiums, shrinking cover and dodging financial planning (options B, C and D) are not aims of regulation."}},{"itemId":"97b4d8c7-07d9-5491-b980-1837a9e35301","questionId":"7d54c146-d801-5f19-9750-8e31314463c6","sourceKey":"bank:INS101:INS-0462","payload":{"prompt":"The history of insurance regulations in Nigeria includes:","options":["NAICOM's creation in 1997","Britain's 1911 legislation","U.S. 1935 Social Security","Beveridge's 1942 report"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"NAICOM was established in 1997 as Nigeria's insurance regulator, which makes it a key event in the history of Nigerian insurance regulation. Options B, C and D are real historical events, but they happened in Britain and the United States, not Nigeria."}},{"itemId":"1177c986-a10c-5694-8d8e-2c1b2c7c8505","questionId":"a4b8772e-3081-5a65-ade1-383bd02bb10a","sourceKey":"bank:INS101:INS-0463","payload":{"prompt":"The role of finance in insurance includes:","options":["Funding sectoral projects","Slowing economic progress","Halting all investments","Eliminating premiums"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"Through their investments, insurers channel premium funds into projects in sectors such as housing, infrastructure and industry. Options B, C and D are wrong because insurance encourages investment and economic progress, and premiums are the very basis of the business."}},{"itemId":"d3d350ec-51e8-5d1c-9e8d-f66863e8ea13","questionId":"6d02ee0e-5ac3-54a6-88bd-b4995e77d930","sourceKey":"bank:INS101:INS-0479","payload":{"prompt":"At the enactment of Insurance Act 2003, Life insurance capitalization was __________","options":["N150m","N200m","N2b","N8b"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"When the Insurance Act 2003 came into force, the minimum paid-up capital for a life insurance company was N150 million. Option C, N2 billion, is the tempting trap, because it came with the later recapitalisation of life insurers, not with the 2003 Act. Options B and D do not match the 2003 figure for life business."}},{"itemId":"826f6488-64f6-52e0-8119-fe2fb2b0468c","questionId":"529f9791-afd3-57f6-b0af-ac5634dc7b30","sourceKey":"bank:INS101:INS-0530","payload":{"prompt":"The Insurance Act 2003 applies to:","options":["Only life insurance","Only marine insurance","The entire Nigerian insurance industry","Foreign insurers only"],"correctOption":2,"section":"Insurance regulation and legislation in Nigeria","explanation":"The Insurance Act 2003 is the main law for all insurance business carried on in Nigeria, covering both life and non-life classes. It is not limited to life or marine business (options A and B), and it applies to all insurers operating in Nigeria, not only foreign ones (option D)."}},{"itemId":"9fd6da06-314b-5fd3-8737-8ca607de0bc7","questionId":"d77a8cae-793b-587a-8218-d1befcd586ec","sourceKey":"bank:INS101:INS-0539","payload":{"prompt":"The National Insurance Commission Act 1997 established:","options":["NAICOM as the regulator","Private insurance courts","Unlimited commissions","Tax exemptions for agents"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"The National Insurance Commission Act 1997 created NAICOM as the body to supervise and regulate insurance business in Nigeria. It did not set up insurance courts (option B), unlimited commissions (option C) or tax breaks for agents (option D)."}},{"itemId":"1f889ee1-f12c-5ba4-b7b5-2c9fc26bfc21","questionId":"562ff94d-ec19-5bd3-8b38-0bfd26bd310c","sourceKey":"bank:INS101:INS-0871","payload":{"prompt":"The government agency that regulates insurance business in Nigeria is","options":["NICON","CIIN","NAICOM","NIA"],"correctOption":2,"section":"Insurance regulation and legislation in Nigeria","explanation":"The National Insurance Commission (NAICOM) is the government agency that supervises and regulates insurance business in Nigeria. NIA (D) is the trade association of insurance companies, CIIN (B) is the professional body for insurance practitioners, and NICON (A) was a state-owned insurance company, not a regulator."}},{"itemId":"86de33f0-33de-5c25-a7a1-fa8e8e63ac3f","questionId":"d8723b27-389a-5e86-9946-b93b7fa1ce9c","sourceKey":"bank:INS101:INS-0934","payload":{"prompt":"When was the Insurance Companies Act enacted in Nigeria?","options":["1945","1960","1961","1976"],"correctOption":2,"section":"Insurance regulation and legislation in Nigeria","explanation":"The Insurance Companies Act of 1961 was the first formal attempt to regulate insurance in Nigeria, and it required insurers to register with the Registrar. Option D, 1976, is the year of the later Insurance Decree No. 59, and 1960 (option B) is the year of independence, not of the Act."}},{"itemId":"4b6e4cee-a86b-55ff-9618-d67473fa6d93","questionId":"c353f185-8f57-546c-9a2c-8835edb51fdd","sourceKey":"bank:INS101:INS-1086","payload":{"prompt":"Which government agency is responsible for the regulation and supervision of insurance companies in Nigeria?","options":["Central Bank of Nigeria (CBN)","National Insurance Commission (NAICOM)","Securities and Exchange Commission (SEC)","Nigeria Deposit Insurance Corporation (NDIC)"],"correctOption":1,"section":"Insurance regulation and legislation in Nigeria","explanation":"NAICOM, set up in 1997, licenses, regulates and supervises insurance business in Nigeria. NDIC (D) is tempting because of the word 'insurance', but it protects bank depositors, while CBN (A) regulates banks."}},{"itemId":"4878b8e7-3227-58f1-9d5f-cbe40563704e","questionId":"f95a7689-7629-56d8-8feb-fb1fb2c6c98e","sourceKey":"bank:INS101:INS-1088","payload":{"prompt":"What is the primary objective of insurance regulation in Nigeria?","options":["Promote competition among insurance companies","Protect the interests of policyholders and the general public","Ensure profitability of insurance companies","Encourage foreign investment in the insurance sector"],"correctOption":1,"section":"Insurance regulation and legislation in Nigeria","explanation":"Regulation exists mainly to make sure insurers stay solvent and treat policyholders fairly, so that claims are paid when losses happen. Competition (A), profitability (C) and foreign investment (D) may be side benefits, but they are not the main reason for regulating insurers."}},{"itemId":"d5079207-157b-523a-9064-e846fb542ee6","questionId":"99c1c874-3b6e-59ab-b5f6-8a1ad728f0a5","sourceKey":"bank:INS101:INS-1093","payload":{"prompt":"What is the primary role of the National Insurance Commission (NAICOM)?","options":["To provide insurance cover for government properties","To regulate the operations of insurance companies in Nigeria","To promote cooperation among insurance companies","To establish ethical standards for the insurance industry"],"correctOption":1,"section":"Insurance regulation and legislation in Nigeria","explanation":"NAICOM is the regulator: it licenses insurers and intermediaries and supervises how they operate. It does not itself sell insurance, so option A is wrong, and promoting cooperation among insurers (C) is more the work of their trade body, the Nigerian Insurers Association."}},{"itemId":"f63c4b52-9eec-5fb7-94a9-4b2c4a457b03","questionId":"c8ce0526-4e2a-54b2-a581-65d8b9b9ecc8","sourceKey":"bank:INS101:INS-1283","payload":{"prompt":"The amount by which an insurer's assets exceed its liabilities, which regulators such as NAICOM require insurers to maintain, is called the","options":["Solvency margin","Profit","Goodwill","Premium income"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"The solvency margin is the cushion of assets over liabilities that shows an insurer can still pay claims even in a bad year, and regulators set a minimum. Option B is earnings for a period, not a buffer of assets over liabilities. Option C is an intangible value of reputation, and D is money received from policyholders."}},{"itemId":"0ab455aa-ebb4-576b-bb63-2a861c3505ad","questionId":"dfc59ef3-2009-5362-88b3-2c29631b1c1f","sourceKey":"bank:INS101:I101N1-098","payload":{"prompt":"Which Nigerian law of 1964 was passed to fill gaps in the Insurance Companies Act of 1961?","options":["Insurance Decree No. 59","The Insurance Act","The National Insurance Commission Act","The Insurance (Miscellaneous Provisions) Act"],"correctOption":3,"section":"Insurance regulation and legislation in Nigeria","explanation":"The Insurance (Miscellaneous Provisions) Act 1964 filled the gaps left in the 1961 Act. Insurance Decree No. 59 came later, in 1976, bringing stricter rules and higher capital."}},{"itemId":"969ae8af-0156-5fac-9ff7-7a018677437a","questionId":"b8b099b8-59fe-5b73-bf1b-a3d5b1b98aa4","sourceKey":"bank:INS101:I101N1-099","payload":{"prompt":"The National Insurance Commission (NAICOM), established in 1997, replaced which earlier body?","options":["The National Insurance Supervisory Board (NISB)","The Registrar of insurance companies","The Chartered Insurance Institute of Nigeria (CIIN)","The Nigerian Insurers Association"],"correctOption":0,"section":"Insurance regulation and legislation in Nigeria","explanation":"NAICOM was established in 1997 under the National Insurance Commission Act, replacing the NISB. The CIIN is a professional body and does not regulate insurance, so it was not the body NAICOM replaced."}},{"itemId":"ef230cd5-ca32-5bf9-9fc7-c0a2bb6a1881","questionId":"463fa679-df51-50fd-8a58-a10dcd507d05","sourceKey":"bank:INS101:I101N1-100","payload":{"prompt":"Insurance Decree No. 59 of 1976 raised the minimum paid-up capital of Nigerian insurers. What was the requirement for a composite insurer?","options":["N150,000","N500,000","N800,000","N300,000"],"correctOption":2,"section":"Insurance regulation and legislation in Nigeria","explanation":"Decree No. 59 of 1976 set N300,000 for life, N500,000 for non-life and N800,000 for composite insurers. A composite insurer writes both life and non-life business, so its requirement is the highest of the three; N500,000 is only the non-life figure."}}]}$official_bank_source$::jsonb;
  v_course uuid := (v_bank->>'courseId')::uuid;
  v_actor uuid := (v_bank->>'actor')::uuid;
  v_seed_actor uuid := (v_bank->>'seedActor')::uuid;
  v_audited jsonb;
  v_final jsonb;
  v_live jsonb;
  v_row jsonb;
  v_id uuid;
  v_item public.managed_content_items%rowtype;
  v_catalogue uuid;
begin
  if p_action is null or p_action not in ('apply', 'rollback') then
    raise exception 'Official bank %: unknown action %', v_bank->>'code', p_action;
  end if;
  -- Every CBT question of the course, locked in one order before anything is read or written.
  perform 1 from public.managed_content_items
    where course_id = v_course and kind = 'cbt_question' order by id for update;
  -- A new course, once: its repository identity and the link from its catalogue course, which must already apply at the
  -- official level and semesters. A rerun finds them in place; anything else is refused.
  if p_action = 'apply' then
    insert into public.courses (id, content_key, is_shared)
      values (v_course, v_bank->'shell'->>'contentKey', null) on conflict do nothing;
    if not exists (select 1 from public.courses where id = v_course and content_key = v_bank->'shell'->>'contentKey') then
      raise exception 'Official bank %: the repository identity is not this course''s', v_bank->>'code';
    end if;
    update public.institutional_courses set repository_course_id = v_course
      where course_code = v_bank->>'code' and repository_course_id is null
        and display_title in (select jsonb_array_elements_text(v_bank->'shell'->'titles'));
    select id into v_catalogue from public.institutional_courses
      where course_code = v_bank->>'code' and repository_course_id = v_course;
    if v_catalogue is null or (select count(*) from public.institutional_courses where course_code = v_bank->>'code') <> 1 then
      raise exception 'Official bank %: the catalogue course is not linked exactly once', v_bank->>'code';
    end if;
    -- Which students see the course stays the catalogue's: the import never adds or removes applicability rows.
    -- It refuses a catalogue course that does not already apply at the official level in every official semester.
    if exists (select 1 from jsonb_array_elements_text(v_bank->'shell'->'semesters') s(key)
        where not exists (select 1 from public.course_applicability a
          join public.academic_levels l on l.id = a.academic_level_id
          join public.academic_periods p on p.id = a.academic_period_id
          where a.institutional_course_id = v_catalogue and l.key = v_bank->'shell'->>'level' and p.key = s.key)) then
      raise exception 'Official bank %: the catalogue course does not apply at the official level in every official semester',
        v_bank->>'code';
    end if;
  end if;
  select coalesce(jsonb_object_agg(value, 1), '{}') into v_audited from jsonb_array_elements_text(v_bank->'audited');
  select coalesce(jsonb_object_agg(k.value->>'itemId', case when (k.value->>'revise')::boolean then 2 else 1 end), '{}')
    || coalesce((select jsonb_object_agg(a.value->>'itemId', 1) from jsonb_array_elements(v_bank->'add') a), '{}')
    into v_final from jsonb_array_elements(v_bank->'keep') k;
  select coalesce(jsonb_object_agg(id::text, published_revision), '{}') into v_live from public.managed_content_items
    where course_id = v_course and kind = 'cbt_question' and published_revision is not null;

  if p_action = 'apply' then
    if v_live = v_final then
      return 'unchanged';
    end if;
    if v_live <> v_audited then
      raise exception 'Official bank %: the published questions are not the audited set', v_bank->>'code';
    end if;

    -- Kept questions keep their item and question id; a different bank payload becomes the next revision.
    for v_row in select value from jsonb_array_elements(v_bank->'keep') where (value->>'revise')::boolean loop
      select * into v_item from public.managed_content_items where id = (v_row->>'itemId')::uuid;
      if v_item.created_by is distinct from v_seed_actor then
        raise exception 'Official bank %: % is not a migration-owned question', v_bank->>'code', v_item.id;
      end if;
      if exists (select 1 from public.managed_content_revisions where item_id = v_item.id and revision = 2) then
        if not exists (select 1 from public.managed_content_revisions where item_id = v_item.id and revision = 2
            and payload = v_row->'payload' and authored_by = v_actor) or v_item.current_revision <> 2 then
          raise exception 'Official bank %: % has another revision two', v_bank->>'code', v_item.id;
        end if;
      else
        if v_item.current_revision <> 1 then
          raise exception 'Official bank %: % has an unpublished edit', v_bank->>'code', v_item.id;
        end if;
        perform private.assert_managed_payload('cbt_question', v_row->'payload');
        insert into public.managed_content_revisions (item_id, revision, payload, authored_by)
          values (v_item.id, 2, v_row->'payload', v_actor);
        update public.managed_content_items set current_revision = 2, lock_version = lock_version + 1,
          updated_at = now() where id = v_item.id returning * into v_item;
      end if;
      if v_item.approved_revision is distinct from 2 then
        insert into public.managed_content_reviews (item_id, revision, parent_revision, decision, reviewed_by, lock_version)
          values (v_item.id, 2, null, 'approved', v_actor, v_item.lock_version + 1);
        update public.managed_content_items set approved_revision = 2, lock_version = lock_version + 1,
          updated_at = now() where id = v_item.id returning * into v_item;
      end if;
      insert into public.managed_content_publications (item_id, lock_version, action, revision, parent_revision,
          previous_revision, previous_parent_revision, acted_by)
        values (v_item.id, v_item.lock_version + 1, 'publish', 2, null, v_item.published_revision, null, v_actor);
      update public.managed_content_items set published_revision = 2, lock_version = lock_version + 1,
        updated_at = now() where id = v_item.id;
    end loop;

    -- Retired questions are unpublished, never deleted: past attempts and reports keep their pinned revision.
    for v_id in select value::uuid from jsonb_array_elements_text(v_bank->'retire') loop
      select * into v_item from public.managed_content_items where id = v_id;
      insert into public.managed_content_publications (item_id, lock_version, action, previous_revision, acted_by)
        values (v_id, v_item.lock_version + 1, 'unpublish', v_item.published_revision, v_actor);
      update public.managed_content_items set published_revision = null, lock_version = lock_version + 1,
        updated_at = now() where id = v_id;
    end loop;

    -- New questions: created, approved and published at revision one, or republished after a rollback.
    for v_row in select value from jsonb_array_elements(v_bank->'add') loop
      select * into v_item from public.managed_content_items where id = (v_row->>'itemId')::uuid for update;
      if found then
        if v_item.created_by is distinct from v_actor or v_item.course_id is distinct from v_course or
           v_item.kind is distinct from 'cbt_question' or v_item.question_id is distinct from (v_row->>'questionId')::uuid or
           v_item.source_key is distinct from v_row->>'sourceKey' or v_item.approved_revision is distinct from 1 or
           not exists (select 1 from public.managed_content_revisions r where r.item_id = v_item.id and r.revision = 1
             and r.payload = v_row->'payload' and r.authored_by = v_actor) then
          raise exception 'Official bank %: % is not the same migration-owned question', v_bank->>'code', v_item.id;
        end if;
        insert into public.managed_content_publications (item_id, lock_version, action, revision,
            previous_revision, acted_by)
          values (v_item.id, v_item.lock_version + 1, 'publish', 1, v_item.published_revision, v_actor);
        update public.managed_content_items set published_revision = 1, lock_version = lock_version + 1,
          updated_at = now() where id = v_item.id;
        continue;
      end if;
      perform private.assert_managed_payload('cbt_question', v_row->'payload');
      insert into public.managed_content_items (id, course_id, kind, question_id, source_key, parent_item_id,
          current_revision, approved_revision, published_revision, published_parent_revision, lock_version, created_by)
        values ((v_row->>'itemId')::uuid, v_course, 'cbt_question', (v_row->>'questionId')::uuid,
          v_row->>'sourceKey', null, 1, 1, 1, null, 3, v_actor);
      insert into public.managed_content_revisions (item_id, revision, payload, authored_by)
        values ((v_row->>'itemId')::uuid, 1, v_row->'payload', v_actor);
      insert into public.managed_content_reviews (item_id, revision, parent_revision, decision, reviewed_by, lock_version)
        values ((v_row->>'itemId')::uuid, 1, null, 'approved', v_actor, 2);
      insert into public.managed_content_publications (item_id, lock_version, action, revision, parent_revision, acted_by)
        values ((v_row->>'itemId')::uuid, 3, 'publish', 1, null, v_actor);
    end loop;

    select coalesce(jsonb_object_agg(id::text, published_revision), '{}') into v_live from public.managed_content_items
      where course_id = v_course and kind = 'cbt_question' and published_revision is not null;
    if v_live <> v_final or (select count(*) from jsonb_object_keys(v_live)) <> (v_bank->>'bankCount')::integer then
      raise exception 'Official bank %: the final published count is not the bank count', v_bank->>'code';
    end if;
    return 'applied';
  end if;

  -- Rollback: publication is a pointer, so the audited set is republished through the same history.
  if v_live = v_audited then
    return 'unchanged';
  end if;
  if v_live <> v_final then
    raise exception 'Official bank %: the published questions are not the imported set', v_bank->>'code';
  end if;
  for v_row in select value from jsonb_array_elements(v_bank->'keep') where (value->>'revise')::boolean loop
    select * into v_item from public.managed_content_items where id = (v_row->>'itemId')::uuid;
    insert into public.managed_content_reviews (item_id, revision, parent_revision, decision, reviewed_by, lock_version)
      values (v_item.id, 1, null, 'approved', v_actor, v_item.lock_version + 1);
    insert into public.managed_content_publications (item_id, lock_version, action, revision, parent_revision,
        previous_revision, previous_parent_revision, acted_by)
      values (v_item.id, v_item.lock_version + 2, 'publish', 1, null, v_item.published_revision, null, v_actor);
    update public.managed_content_items set approved_revision = 1, published_revision = 1,
      lock_version = lock_version + 2, updated_at = now() where id = v_item.id;
  end loop;
  for v_id in select value::uuid from jsonb_array_elements_text(v_bank->'retire') loop
    select * into v_item from public.managed_content_items where id = v_id;
    if v_item.approved_revision is distinct from 1 then
      raise exception 'Official bank %: % is no longer approved at revision one', v_bank->>'code', v_id;
    end if;
    insert into public.managed_content_publications (item_id, lock_version, action, revision, acted_by)
      values (v_id, v_item.lock_version + 1, 'publish', 1, v_actor);
    update public.managed_content_items set published_revision = 1, lock_version = lock_version + 1,
      updated_at = now() where id = v_id;
  end loop;
  for v_row in select value from jsonb_array_elements(v_bank->'add') loop
    select * into v_item from public.managed_content_items where id = (v_row->>'itemId')::uuid;
    insert into public.managed_content_publications (item_id, lock_version, action, previous_revision, acted_by)
      values (v_item.id, v_item.lock_version + 1, 'unpublish', v_item.published_revision, v_actor);
    update public.managed_content_items set published_revision = null, lock_version = lock_version + 1,
      updated_at = now() where id = v_item.id;
  end loop;
  select coalesce(jsonb_object_agg(id::text, published_revision), '{}') into v_live from public.managed_content_items
    where course_id = v_course and kind = 'cbt_question' and published_revision is not null;
  if v_live <> v_audited then
    raise exception 'Official bank %: rollback did not restore the audited set', v_bank->>'code';
  end if;
  return 'rolled-back';
end;
$official_bank$;

revoke all on function private.official_bank_ins101(text) from public, anon, authenticated, service_role;
select private.official_bank_ins101('apply');
